local addon = WoWKoreanClient
if not addon.active then return end
local text = addon.worldText.speech
if not text then
    text = { values = {}, templates = {} }
    addon.worldText.speech = text
end
local rows = text.values
rows["175:1212436603"]="드레네이, 그리고 이 때문에, 나는 둘 중 한 명도 아닙니다. 오크가 아닙니다. 드레네이도 아닙니다. 내 종은 드물다."
rows["175:1260562848"]="모가들이 유물을 파고 있는 걸 봤어$b$b그건 좋은 일이 아닐 수 없어요$b$b우리는 여전히 모고들이 미술품과 신비한 힘을 사용하는 방법을 알고 있을 때 했던 모든 악의 이야기를 들려줍니다."
rows["175:1341524374"]="조카스트는 당시 최고의 사냥꾼이었는데, 요즘은 그녀는 센라리온 앙클라브에서 사냥꾼의 길을 시작하는 사람들을 가르치고 있습니다."
rows["175:134569635"]="친구, 이건 새벽의 꽃입니다. 여드 숲에서 판다레네의 삶의 중심입니다. 만약 당신이 인상을 남길 원한다면, 저는 이 시민들 중 많은 사람들이 당신의 도움이 필요할 것이라고 확신합니다."
rows["175:1364947911"]="그라니스 스와프트렉스는 테이블 아래에서 물고기를 마실 수 있지만 그의 도끼는 여전히 진동합니다. 하지만 훈련을 찾고 있다면, 당신이 그를 이해할 수 있는 동안 그를 잡는 것이 좋습니다."
rows["175:1387852461"]="상황이 좀 복잡해, 타럴 더 많은 블랙무어 부대가 나타나기 전에 산으로 향하는 것이 좋습니다."
rows["175:1540338985"]="사실, 이 크레이터에 있는 많은 생물들은 내 주인이 도착하기 훨씬 전에 존재했지만, 그렇지 않은 것들이 있습니다.$b$b하지만 우리는 편견 없이 모든 것을 지켜야 합니다."
rows["175:1560270910"]="왜 그렇게 하지 않는지? \"마비\"는 \"오른\" 2개로 줄게, 그리고 다시 와서 파티를 하겠네!$B$B내 여인과 함께 해변에 있는 멋진 작은 집을 찾은 거야"
rows["175:1567500991"]="아라티 계곡에 있는 인간들은 우리의 도움이 필요해요."
rows["175:1575044969"]="모든 Shado-Pan은 세 가지 영원한 맹세를 합니다.\010이 땅을 지키고, 그 사람들을 보호하고, 그들의 학생을 훈련시키기 위해서요.\010샤도파인이 죽으면, 그들은 이 유대로부터 해방되어야 합니다."
rows["175:1586999961"]="여기 있는 재료에 대해 불평할 수 없어 모든 것을 대체할 수 있어"
rows["175:1590168481"]="나는... 분노의 관문에 없었지만, 살아남은 병사들이 많은 이야기를 전해주었다. 그대의 아들은 명예롭게 싸웠고 영웅답게 전사했다. 그러니 영웅답게 묻힐 자격이 있다."
rows["175:1602816832"]="난 널 전에 들어봤어. 넌 너의 세상을 구하고 우리로부터 배우기 위해 온거야. 할머니 게야는 너를 가르칠 일을 내게 맡겼고, 그래서 너는 내 말을 들어줄 거야, 고엘"
rows["175:1781859905"]="우리 민족의 불멸을 되찾기 위해, 그리고 서클의 승인을 받아 스태겔름과 가장 강력한 드루이드는 이제 당신이 서 있는 갈래에 테일드라시를 키웠다."
rows["175:1846913691"]="여기 사람들은 낯선 사람들에게 조금 경계하지만, 그들을 알게 되면 따뜻해집니다.$B$B더 많은 경험을 쌓으면 그들을 도와줄 수 있습니다."
rows["175:1868354771"]="그래, 도시에서 약품 판매자가 있어요. 토미 팅커스패드는 공예의실에서 왼쪽으로 들어갑니다.$B$B지도에 위치를 표시해 줄게요"
rows["175:1904451264"]="모가 우리를 창조했다고 주장하고... 현재의 모습으로 변신시켰다고 주장하는$b$b우리는 우리 자신의 민족입니다. 위대한 창조자 크로스에서 진화했습니다!"
rows["175:1984064963"]="이 직장을 당신 가족에게 부탁해서 맡겼어요. 그 결정에 후회하지 마세요."
rows["175:205378191"]="이차 방어 시스템을 활성화하면 궤도 위치로 허가되지 않은 생명체의 멸종이 발생할 것입니다.$B$B- 당신은 허가되지 않은 생명체입니다."
rows["175:216318163"]="블러드펀그의 워크겐이 탄압을 주도했고, 이 괴물은 그 무리가 수년 동안 이 땅을 공포로 몰아넣었습니다."
rows["175:250662616"]="적절한 가격에, 내 승무원과 함께 봉사할 것입니다.$B$B나즈그림 장군은 명예로운 오크이기 때문에 100 처음에는 금으로, 나와 내 사람들을 위해 큰 위험을 감수합니다."
rows["175:332206183"]="병은 에메랄드 드림의 악몽에서 탄생하고 용 타에라가 퍼뜨리고 있습니다. 그는 자신의 옛 자아의 미쳤던 그림자입니다."
rows["175:376897427"]="로얄 거래소 에 위치한 실버문 시티 인은 벨라드라라는 재능 있는 여성 이 운영 하는 곳 이다. 유명 포도주 관리자 는 때때로 그 곳 에서도 발견 될 수 있다고 알려졌다."
rows["175:407064647"]="시험 의 계곡 은 가장 약한 사람 들 을도 호드 에 합류 할 만한 전사 로 완화 시키게 될 것 이다. 그 시험 을 감당 할 수 없는 사람 들 은 황무지 의 화려 한 태양 에 굽기 위해 남겨 려질 것 이다."
rows["175:481859216"]="고릴라들은 매력적인 존재야 밤의 엘프보다 더 낫다 멍청한 짓을 하는 놈들"
rows["175:498962900"]="그러니 우리의 의무를 굳게 붙들고 나아가자. 아제로스의 인간들이 천 년을 더 살아간다 해도, 사람들은 여전히 이렇게 말할 것이다. '그때가 그들의 가장 빛나는 순간이었다.'"
rows["175:675040743"]="티인은 재능 있는 스킨러입니다. 제가 본 최고의 린크스피드를 만들어냅니다. 만약 그녀로부터 배우고 싶다면,"
rows["175:709282166"]="해적들, 장난을 그만해줘서 나 좀 나가게 해"
rows["175:73710818"]="만약 당신이 어떻게든 C'Thun를 물리치지 않고 우리를 해방시키면, 우리는 모든 힘을 집중해서 짐승이 왔던 지옥으로 망명되는 것을 보도록 할 것입니다."
rows["175:75406243"]="멍청하다고 불렀지만 내가 보여드릴게 내가 가진 모든 냄비를 지켜보고 그들이 어쨌든 물건을 끓일 수 있다는 걸 증명할게"
rows["175:858472177"]="만약 압도당하면 태양의 빛 능력을 사용하세요!$B$B|TInterface\\Icons\\spell_holy_divineprovidence.blp:64|t"
rows["175:925130305"]="그 중 한 명이야. 맥시밀리안은 여기 있는 어둠의 예술에 대해 아는 유일한 사람이야."
rows["175:930688103"]="우린 명예롭게 이 일을 해낼 걸세. 승리를 거둔다는 일념으로 스컬지와 같은 수준으로 추락하지는 않을 걸세. 그렇게 한다면 우리가 싸워 물리치려는 저들과 다를 바가 없지 않겠나!"
rows["175:934483348"]="아, 그래서... 당신은 그것을 찾았어.$B$B<Mathredis는 당신 손에 있는 책을 가리키고 있습니다.>$B$B필요한 부품들을 수집했나요?$B$B이리브람에 기록된 표면, 멍청이!"
rows["175:944255671"]="발리언스 케이프로 갈 수 있다면 여기와 보레안 툰드라 사이에 가는 화물선에 올라갈 수 있어"
rows["175:947521304"]="당신과 당신의 동맹국으로 우리는 이 섬에 머물고 다시 건설하기로 결정했습니다.$B$B슬픔이 계속 오는 동안, 우리는 살아남을 것 같습니다.\010"
rows["175:985556925"]="넌 세상에서 가장 위대한 샤만일 수도 있겠지만, 넌 필사적일 뿐이야.\010"
rows["176:1118492309"]="내가 여기 있는 제군들에게 바라는 것은 이 구역에 있는 급유소, 주거지, 창고, 농장, 닭장, 화장실, 개집의 정확한 위치를 파악해 오는 것이다."
rows["176:1127023304"]="스랄의 가짜 호드들이 감히 내 요새 안에 이렇게나 깊숙하게 쳐들어왔단 말인가? 스랄마의 포로들을 데려오고 사형 집행인을 불러라! 이곳을 침범한 대가는 목숨으로 치러야 할 것이다!"
rows["176:1159380926"]="아무 말도 안 돼$b$b그들은 매일 새로운 병사를 데려왔다. 호드와 얼라이언스, 둘 다.$b$b어떤 사람들은 같은 날 끌려갔고, 다른 사람들은 일주일 동안 그 곳에서 머물게 됐습니다."
rows["176:1172006787"]="폴드링 경, 볼바르가 살았을 수 있겠소? 그렇다면 얼라이언스와 호드 사이에도 평화가 찾아올지 모르오. 이 저주받은 곳 꼭대기로 가서 그 성기사를 풀어줘야겠소!"
rows["176:1192374830"]="그는 위르메스트에서 그들의 노력에 도움을 줄 것을 요청받았습니다. 아제로스 죽음의 날개의 위협을$b$b빛의 길을 안내해 주시기 바랍니다."
rows["176:1200541124"]="제 작품이 이렇게 멀리 갈 수 있을 줄은 상상도 못했어요. 그것은 키파리의 위대한 힘에 대한 증거입니다. 우리 문명은 그들이 없었다면 회복되지 않았을 것입니다. 기억하세요."
rows["176:1237271658"]="이 공격에 대해 혼란이 없으니, 원자들과 거인들은 우리를 공격할 때, 어떻게든 우리는 스톤모더 테레잔의 분노를 얻었을 것 같습니다."
rows["176:1247359120"]="위대한 전사인 척 하는 게 아니라 전쟁으로 위대한 전사가 되지만,"
rows["176:1284747335"]="와우, 와우, 와오! 스푸터발프는 이 아기를 운전하게 해줬다는 걸 믿을 수가 없어요. 제가 처음 비행을 했는지 말씀드렸나요? 걱정 마세요. 모든 것이 통제하에 있습니다."
rows["176:1304469343"]="죽은자를 처음 보았을 때, 저는 그들의 공포와 외로움을 상상할 수 없었기 때문에 울었습니다. 지구 어머니께서 그때 저에게 말씀하셨고, 그녀는 내 피를 노래했습니다. 그리고 그녀는 제게 말했습니다. \"그들을 구하라\"."
rows["176:1318550998"]="대장, 기하급수자들은 밤낮으로 일하며 오그리마에서 공급을 준비하고 있습니다. 아직 많은 일이 있지만 우리는 시간보다 한 시간 앞당겨 있습니다."
rows["176:1334146907"]="수십 개의 짜증나는 작은 개구리들이 있는데, 우리를 괴롭히고 있는 거리를 잡을 수 없어.$B$B적어도 난 내 무기를 잃지 않았어"
rows["176:1356334545"]="난 죽었어?$b$b네, 맞아요, 난 죽었어 오크가 내 손을 잘라서 죽게 내버려뒀어$b$b발드레드는 손을 내려다보죠$b$b내 손들이 아니야!"
rows["176:1392569540"]="오래전 우리는 한 조각의 주츠를 입었지요. 혁신적인  ⁇ 이 덕분에 우리는 더 이상 그런 비실용한 의상을 입지 않습니다."
rows["176:1416348950"]="내 신뢰를 얻었으니, 이것은 지금껏 가장 위험한 임무가 될 것입니다."
rows["176:1471586373"]="이제 다른 선생님과 함께 지식을 확장할 때가 됐습니다. 오킬은 엔지니어의 많은 놀라운 것들을 밝혀냈고, 발견의 길을 이끌 것입니다."
rows["176:1484215302"]=" ⁇ 자라는 적절한 구성 요소로 고대 트롤 매력을 만들 수 있습니다. 이 마법은 하카르와 그의 하위들을 물리치는데 도움이 될 것입니다.$B$B두 가지 물건만 가져오라고 부탁합니다."
rows["176:1484238073"]="우리는 데즈코와 그의 선택에 서 있습니다. 우리는 모고, 사우로크, 샤, 심지어 호드의 전두환에 맞서서 이 계곡을 마지막까지 보호할 것입니다."
rows["176:1531872335"]="너무 으스대지 마라. 무슨 생각을 하는지 알겠다만, 폭풍우 요새는 잠시 머무르는 곳이었을 뿐이야. 내가 정말로 눈먼 반쪽짜리 나이트 엘프 잡종 따위에게 미래를 맡길 거라고 생각했나?"
rows["176:1576931309"]="어린 원동생 달걀이 동굴 바닥에  ⁇ 니다. 최근 출산된 많은 달걀은 주변 지역을 채우고 있습니다. 이 많은 원동생 달록으로, 가로쉬의 침략으로부터 어느 곳이도 안전하지 않을 것입니다."
rows["176:1579025454"]="틈이 떨어지고 오그리마 이 포털은 공격의 두 번째 반이 될 것입니다.$B$B포털로 들어가서 공격에 압력을 가해"
rows["176:15867532"]="여객선이야, 전쟁새가 아냐, 하지만 직업은 직업이야, 공작이 돈을 지불할때까지 난  ⁇ 바스트 대장에게 농담을 해$b$b어쨌든, 배에 오신 것을 환영합니다."
rows["176:1600954022"]=" ⁇ 문에게 잠시 맡겨서 윤의 집을 둘러볼 수 있겠어"
rows["176:1619652376"]="압력을 사용하여 파괴기의 속도와 손상 및 방어력을 높일 수 있습니다.$B|TInterface\\Icons\\INV_Gizmo_RocketBootExtreme.blp:32|t |TInterface\\Icons\\INV_Weapon_Rifle_31.blp:32|t"
rows["176:1657293375"]="우리가 아는 건... 왜 우리에게 그 파멸의 역병이라는 게... 효과가 없는지... 너희가 모른다는 것뿐이야. 웨스트윈드 님께서 대수도원장님께 그 축복의 기도를 알려줬지. 부탁이니... 제발... 그만?!"
rows["176:1687592682"]="스펠파이어 테일러링에 대한 실력을 잊는 것은 가볍게 할 수 있는 일이 아닙니다. 만약 당신이 그것을 포기하기로 결정한다면, 당신은 스펠파이어 테일러링을 만들어야 하는 모든 레시피를 잊을 것입니다!"
rows["176:1703564375"]="전 뒤에 남아서 노예들을 구해줄게 네가 그들을 해방시키면서"
rows["176:1754418366"]="저기 게으른 댄 말고?$b$b북쪽으로 사냥하기 전에 에비랑 시간을 보냈어요$b$b물론 누가 엄마 스톰스타우트를 잊을 수 있을까요?"
rows["176:1818631353"]="바르조크와 얘기해 오그리마경비원이라면 그를 찾아갈 수 있는 방향을 알려줄 수 있을 겁니다.$b$b성전 내부에 오그리마의 포털을 찾을 수 있습니다."
rows["176:1840018191"]="우리는 스파크로켓 아우트포스트에 2방향 포털을 유지할 수 있고, 오그리마와 두 달의 성당으로 한방향 포털도 유지할 수 있습니다.$b$b어떤 용병을 연료로 부추길래?"
rows["176:190396413"]="하지만 말만 해도 되겠네, 동포들! 이것은 행동의 촉구입니다. 우리는 이 \"선택한 사람들\"에게 우리의 것을 빼앗길 수 없게 해 줄 것입니다. 우리는 이 포로가 잡았고, 우리 스스로 그것을 옛 신들에게 바쳤습니다!!"
rows["176:1924718531"]="이건 조종실이 아니라, 또 다른 방어 장치가 있고, 록 트로그스가 여기 침입했어."
rows["176:1949888372"]="난 여기서 앉아서 큰 바다의 소리를 듣고 너무 좋아해요. 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네, 네."
rows["176:1974818786"]="우리는 이 일에 집중해야 합니다. 성소가 능력을 최대한 발휘하기 시작하면 실버문도 지원을 보낼 수밖에 없겠죠. 비전 성소를 작동하기에는 물자가 부족합니다."
rows["176:2063369424"]="숲의 호zen의 손님으로 살아남았다고 전해졌어요$b$b여행자여, 우리의 겸손한 집으로 환영합니다."
rows["176:2092670944"]="내 명령 전에 나를 순교하려고 하니까 그렇게 해줘서 날 죽여라 빛 - 정복된 사람들의 - 끊이지 않는 계속될 것입니다."
rows["176:2112468798"]="드레네이군과 그들의 얼라이언스 동맹국들은 호드 폭풍의 눈에서 아웃랜드당신은 그들과 함께 우리의 편으로 전투의 흐름을 바꾸려고 노력할 수 있을까요?"
rows["176:260535110"]="자이나는 우위를 지나갔고, 선리버들을 감옥에 가리고 저항하는 사람들을 공격하고 있습니다. 더 나쁜 것은 은 동맹이 피 흘리는 데 참여할 기회를 잡았다는 것입니다."
rows["176:294798200"]="매일 더 많은 낯선 사람들이 우리 해변에 오르고 있습니다.$b$b어제 저녁까지 이 무리가 서로 총을 쏘아 올렸는데"
rows["176:297709995"]="여기선 연습생들이 많지 않아? 저는 그 이유는 학부들이 우리에게 위험한 일을 맡기기 때문이라고 생각하기 시작했습니다."
rows["176:343633898"]="또한, 저는 오버로드 크롬가르의 권위로 여기 왔습니다. 그는 우리 전쟁장 가로시 지옥경으로 임명되었습니다."
rows["176:367428648"]="캡틴은 지금 바쁘고 지하실 속의 실리시드 유충지를 연구하고 있어요"
rows["176:374695101"]="틈이 떨어지고 아이언포지 이 포털은 공격의 두 번째 반이 될 것입니다.$B$B포털로 들어가서 공격에 압력을 가해"
rows["176:452837728"]="틈이 떨어지고 스톰윈드 이 포털은 공격의 두 번째 반이 될 것입니다.$B$B포털로 들어가서 공격에 압력을 가해"
rows["176:466061617"]="오 형아, 이봐요, 그는 여기 5시간 동안 아기와 같이 울고 있을 거야"
rows["176:50929653"]="여러분 스스로의 가슴에 갑자기 \"부려들\"게 되는 것이 좋겠습니까?"
rows["176:560199013"]="영웅의 환영은 남서부 달라란에서 은 엔클라브 바로 옆에 위치하고 있습니다.$B$B이곳은 맥주 정원과 도시의 최고의 요리 트레이너 중 하나를 자랑합니다."
rows["176:561951399"]="너희가 심판을 받았고 너희들은 그 대상이 되셨으니 경고하라 너 희의 외면은 너희 영혼을 시험하리니 너희가 준비된 후에"
rows["176:609366026"]="내 가공에 오신 것을 환영합니다. 블랙스미스. 이 작은 비밀을 공유해 드리겠습니다. 당신은 아무도 믿을 수 없습니다."
rows["176:624063555"]="난 전사 테라스에서 있는 일일리아  ⁇ 포에서 대부분의 무기 훈련을 받았어요. 새로운 무기를 사용하기를 배우고 싶다면 그녀를 찾아보시면 좋을 겁니다.  "
rows["176:661987816"]="오그리마는 잠금 상태입니다. 모든 가게는 닫혀 있습니다. 상자, 경매 사업자 또는 트레이너가 필요한 경우 썬더 블러프 또는 실버문 시티를 방문하십시오.$B$B언더시티에서 멀리 떨어져!"
rows["176:702045408"]="적어도 좋은 소식은 있긴 하지만, 겔빈, 경의를 표하지 마요."
rows["176:729489658"]="앨나는 오라클 글레이드에서 대부분의 시간을 보낸다. 그 곳에서 그녀의 직업을 연습합니다. 마법사의 직업을 배우고 싶다면 그녀를 찾기 위해 그곳에 가야 합니다."
rows["176:834947735"]="그래서, 당신은 나를 찾았어. 당신은 억압과 통제를 배우게 되었어.$B$B난 그 이상의 많은 것을 가르쳐 줄거야... 당신은 또한 희생에 대해 배울거야.$B$B다이오가 미소 짓습니다"
rows["176:841809443"]="최근 우리는 벡터 코일 근처에 엄청난 힘을 가진 존재가 소환되는 소식을 들었습니다. 두려워하지 마세요."
rows["176:856906446"]="이런 직업은 심장이 약한 사람한테는 안되는데, 한 손 잃은 삼촌이 있어요."
rows["176:914873925"]="아덴 대장님, 항상 게이트에서 봉사합니다.$B$B제가 가진 포스팅은 제 경비자와 상인의 딸들을 동시에 볼 수 있게 해줍니다."
rows["176:948278577"]="마지막 것보다는 좀 낫군. 다른 것들처럼 골격 구조가 약하긴 하지만! 이런 걸 소환해야 일이 제대로 되는 거야."
rows["176:961253202"]="낙스라마스 죽음의 기사 중에서도 4인 기사단이 가장 강력하다. 그들은 켈투자드의 최정예 경비병이기도 하지. 첫 번째인 영주 코스아즈는 불의 힘을 다룬다."
rows["176:964942009"]="우리 모국어로 \"우나'페\"는 \"피난민\"로 번역될 수 있습니다. 하지만 그 이름은 더 이상 적합하지 않습니다. 우리가 이 캠프를 세운 순간부터, 이 이상한 정글은 그것을 삼키고 위협했습니다. "
rows["177:1027163830"]="내 개인적인 성소수자 여러분, 환영합니다. 저는 여러분이 좋아하는 숙소를 찾기를 바랍니다. 여기 여러분은 제 실패한 실험들 그리고 궁극적으로 저의 가장 큰 승리의 많은 것을 찾을 것입니다."
rows["177:1035484780"]="내 가족 해마어?! 당신을 소유한 것은 무엇이었을까... 상관없어요."
rows["177:1049262384"]="이 재판 에서, 애완 동물 을 치료 할 수 없습니다. 위대한 지도자의 특징 중 하나는 여러 배경을 가진 많은 주체들을 하나의 깃발 아래 연합하여 이끌 수 있는 능력입니다."
rows["177:1091205531"]="죽음의 날개의 탈출은 우리 세계를 망치는 것뿐 아니라 타이탄들이 만든 강력한 돌이 이 방 안에 있었습니다."
rows["177:1113433764"]="그래, 가로쉬가 좀 강렬하긴 하지만, 그들이 어딘가에 가는 것 같아\010어쨌든, 승려가 되는 것에 대해 뭘 보여줄 수 있어?"
rows["177:1135858541"]="재조조를 하고 싶었소?\010오그리마의 에테레알은 당신을 도울 것입니다.\010도시의 경비원이라면 누구나 안내를 줄 수 있습니다."
rows["177:114553553"]="꿀벌 마을은 꿀벌들이 운영하고 있지만 그 마을의 진정한 중심지는 맥주 공장입니다."
rows["177:1154619976"]="동물 들 의 복리 에 대한 관심 을 나타낸 것 은 칭찬 의 대상 이다. 아래층 에 있는 볼루그 는 그 에 도움 이 될 수 있습니다. 은행 과 호스 사이의 그를 찾아보세요."
rows["177:1288193668"]="우리는 스스로를 숲 트롤의 마지막 부족으로 부르며 자랑스럽게 생각합니다 호드.$B$B시간이 지나면 다른 부족과 왜성들을 정복해내고 하인터랜드는 우리의 것이 될 것입니다."
rows["177:1367004702"]="첫 번째 게이트, 아가마스, 철거되었습니다. 로헨도르의 두 번째 게이트는 이제 우리의 통로를 차단합니다.$B$B우리 마법사들은 $3255w 두 번째 게이트의 방어구역을 통과해"
rows["177:1388005875"]="챔피언, 우리 국민이 전쟁에 걸렸다는 건 알지만 만약 당신이 이 흑 용에게 무관하게 신뢰한다면 당신은 당신의 대장보다 더 낫지 않나요?"
rows["177:1662599090"]="그 말을 전하러 온 거요? 은빛 여명회가 비굴하게 살아남고 붉은십자군이 몰락한 이유를 내게 설명하려는 건가? 사령관, 당신은 그 세 치 혀로 오래된 상처를 들쑤시는군!"
rows["177:1767896653"]="이 배럴들을 발굴 현장에 배달하는 것은 힘든 일이지만, 폭발물 파우더를 가져오기 위해 우리에 의존하는 배럴들이 너무 많습니다.$B$B우린 암흑 철자에 맞서기 위해 최선을 다해야 합니다!"
rows["177:1793858409"]="레이  ⁇ 이 그의 귀국 후에도 왕좌에 몰려들 수 있는 많은 동맹자들을 발견한 것은 실망스럽습니다."
rows["177:1810187692"]="이 섬에는 엄청난 신비한 힘이 있습니다. 아직은 그 힘은 번개왕의 손에 있거나,$B$B시간이 지나면 알 수 있을 거야"
rows["177:1907753886"]="지각이 없는 사람들을 죽이는 긴 하루였어 스컬지 죽은 흉터를 따라 계속 퍼레이드하는 걸 보고 싶고"
rows["177:2135798109"]="좀 더 일찍 오지 못해서 미안하오, 헬스크림의 아들이여. 그대의 아버님에 대해서 들려줄 말이 무척 많지만 우선은 어디로 가야 대모님을 찾아뵐 수 있는지부터 말해 주겠소?"
rows["177:21450467"]="트롤을 이 곳에서 구하기 위해 모든 요소들의 도움이 필요해 라그나로스의 부하들은 사이클론스, 하이드리우스, 심지어 테레잔만큼이나 타협적인 것이 아니다."
rows["177:287775597"]="쓸모없는 스파이, 만약 당신이 두개골이라고 부르는 그 구멍 안에 한 조각도 정보가 있다면 이미 그것을 기침해버렸겠죠."
rows["177:329421071"]="어 ⁇ 든, 그녀는 돌아왔고 기분도 좋지 않았기 때문에 요구가 쏟아지기 시작했어요.\010"
rows["177:340735180"]="가젯잔은 언고로와 비교해도 좋지만, 우리한테는 물품을 가져다 줄 수 있는 좋은 사람들이 있습니다."
rows["177:347535386"]="난 비행기를 타고 다르나서스산에서 헤엄쳐나갈 수 없어서 바다를 넘어서면 잘 되겠군"
rows["177:34908035"]="저는 키라지 전쟁의 전선에서 싸웠고 아조엘 네루브의 깊이를 점령했습니다. 곤충 군대가 통제되지 않은 상태에서 세상에 미칠 위협을 직접 알고 있습니다."
rows["177:354701509"]="아그라, 내 심장은 내가 이기적이지만 내가 한 모든 일은 자랑스러움의 소리로만 성취했지"
rows["177:354901358"]="바람의 협상회가 사라졌어요. 여러분의 존엄한 행동과 결단성으로..."
rows["177:36709498"]="네가 모르는 사이에, 눈먼  ⁇ 돌고 있는 벌레처럼 끝없는 광기와 절망으로 몰려다니며"
rows["177:384976565"]="저 저주를 받은 존 스터링은 우리를 멸망으로 이끌고 있을 거야"
rows["177:413066170"]=" ⁇ 로크는 우리로부터 떨어진 격곡을 건너 앉아 있는 고대 신의 이름입니다.$B$B우리는 이것을 끝낼 필요가 있습니다! 그렇지 않으면 우리는 모두 우리의 멸망을 맞이할 것입니다!"
rows["177:448810954"]="앞에 보이는 것이 지옥사냥개일세. 이 야수는 주문 잠금을 비롯한 여러 가지 능력을 타고났기 때문에, 마법을 사용하는 적을 상대하는 데 탁월하지."
rows["177:555657777"]="성전 경비자들은 몇 명이지만 그들의 정신은 여전히 강하다. 우리는 샤를 물리치고 우리 성전에서 쫓아낼 수 있다고 믿습니다."
rows["177:556386924"]="한 번 그의 재위인 블랙 프린스의 존경을 얻으면 내 일을 받을 수 있을 겁니다.$b$b그 때까지 가, 내가 팔릴 게 없어"
rows["177:608436591"]="식물학에 대해 더 많은 것을 배우고 싶다면, 네 바람의 계곡의 하프힐 시장에서 한 꽃꽃과 이야기해 주세요.$B$B내가 그의 위치를 표시해 줄게요"
rows["177:645205136"]="르나타키, 천발의 칼$B$B고통은 그의 생명 피이고 두려움은 그의 동맹이고 언젠가 그가 돌아와 기쁨의 피를 흘리도록 해$B$B레나타키는 이제 미쳤다는 가장자리에 살고 있습니다."
rows["177:645687548"]="대영주님의 병사들을 메아리 골짜기에서 포격을 막아내는 인간 방패로 이용하기에 리치 왕의 군대는 아무런 방해도 받지 않고 기지로 공격해 오는 상황입니다."
rows["177:708869627"]=" ⁇ 키는 티르트가 여전히  ⁇ 은 플래트에서 있다는 걸 알기를 원하지 않아서 닭이 된 거야!$B$B플럭키를 찾으면 그에게 연락해봐"
rows["177:714206040"]="이 직업을 정말 배우고 싶은 마음이 있다면, 북부 다르나서스의 공예인 테라스에서 숙련된 수학자인 아이네틸에게 안내해 드리겠습니다."
rows["177:719685367"]="반갑습니다, 친구. 제 첫 번째 노그네포거 엘리엑서를 만들지 않은 지 몇 년이나 됐어요.$B$B이제 전 도시를 운영하고 있어요!"
rows["177:822423857"]="카즈로갈의 죽음 소리 때문에 불타는 군단의 핵심에 공포가 부딪힐 것입니다. 그들은 이제 당신의 세력의 힘을 알고 있습니다."
rows["177:831723954"]="팻 네이글! 월드 디자인 팀입니다! 코리 스톡튼, 폴 C., 짐 채드윅, 스태츠, 에드 헤인스, 모리스, 고처, 제시!, 사라 B., 빅토르 C., 데이브 A.! 배경을 담당하고 있는 미술 팀입니다!"
rows["177:862125482"]="보안이 허용됐습니다.$B$B부차적 시스템에서 백업 비활성화는 콘커스에 위치한 개별 생성기를 통해 액세스 할 수 있습니다."
rows["177:903572929"]="이 훈련자들은 약해 있습니다. 그들은 벽을 걷기 위해 준비가 되어 있지 않습니다. 맨티드나 모그를 직접 마주치면 더욱은 그럴 것입니다."
rows["177:927581808"]="우린 군대가니까, 연합해있어요. 영웅들은 어디 있어요? 볼진은 젊은 워시프 옆에 서 있는 보호소에서, 의식이 없죠. 툴진은 실종됐고, 아마 죽었을 겁니다."
rows["178:1017377488"]="하지만, 북풍은 그리 호락호락 패배를 인정하지 않았다네. 그 대신에 자네 기억을, 고향을 파괴하는 것이 최고의 복수라 생각하고 때를 기다리며 힘을 모았지."
rows["178:1019616850"]="라자크의 로프라이더들과 함께 뛰면 명령에 따라가는 것을 배우게 될 겁니다.$B$B첫 번째는 죽을 때까지 싸워야 하고 두 번째는 첫 번째가 되어야 합니다."
rows["178:1114358825"]="\"그 애 는 어떻게 살는지 보는가?\"라고 물었습니다. \"그렇게 살고 싶습니까?\""
rows["178:1158408434"]="공학자가 없는 스팀드레 선박은 뭐든지 도와줄 수 있어"
rows["178:1179165398"]="기어벌들은 항상 우리 수용소 주변에서 음식과 물품을 찾아왔지만, 최근 우리 농장과 농촌에 직접적인 공격이 일어나게 된 것은 무엇인가요."
rows["178:1210880640"]="하지만 나는 내 형제들이 그러듯이, 내 형제들이 응당 그래야 하듯이, 싸우지 않았소. 난 길고 거대한 장창을 들었으나 휘두르지는 않은 채로 내 늑대가 시합 대상에게 돌진하게 하였소."
rows["178:1229996982"]="지시어. 에시르와 바니르. 일반적인 용어로 폭풍과 대지의 거인이라고 합니다. 로켄이 제1관리자로 지정되었으며, 용의 위상들은 아제로스의 진화를 주시하는 역할을 맡았습니다."
rows["178:1234902795"]="나디아는 오랜 기간 동안 가죽 작업에 뛰어들었습니다. 다르나서스로 서쪽으로 가서 그녀를 방문해 보세요."
rows["178:1277068933"]="코로크, 어둠달 골짜기 거인들의 힘을 빌려주십시오. 주인님도 보통 통치자와 다르지 않습니다. 이 세계에서 반대 세력을 진압하는데 협조를 아끼지 않은 이들을 절대 모른 척하시진 않을 겁니다."
rows["178:1317028577"]="스톰윈드에 기리폰 마스터가 있습니다. 만약 어딘가에 비행을 해야 한다면, 당신은 히어로즈의 계곡을 지나가면서 오른쪽에 기리폰이 착륙하는 것을 볼 수 있어야 합니다."
rows["178:134862716"]="버드의 팀이라고?$b$b네, 그는 사람을 존중하지 않을거야. 그는  ⁇ 을 할 수있는 모든 사람을 대할 것입니다$b$b...그들 외엔 부드도 싫어해요 개인적으로는 겁이 나네요\010"
rows["178:1383216891"]="그 거품장님이 특별품을 제안한다면, 해양에 던져버릴 수 있어."
rows["178:142126841"]="젤다마르는 새로운 마법을 가르쳐 줄 수 있겠지만, 그는 최근 레온 프라이드 인에 머물기를 좋아하고 있어,"
rows["178:1465614860"]="이미 Shado-Pan에게 무슨 일이 일어났는지 알렸어$B$B저는 우리 모두가 앞으로 직면할 수 있는 시험에 대해 아쉽게 준비되지 않은 것처럼 생각합니다."
rows["178:1476649996"]="이 호드 이 해안에서 구매를 찾을 수 없습니다. 그리고 번개왕이 패배했을 때, 얼라이언스 영웅들이 그들의 필요시대에 그들을 지지했습니다."
rows["178:1547738755"]="이 호드 이 대량차원의 개입을 허용하지 말아야 합니다. 얼라이언스 모든 마나 세포 아웃랜드당신은 폭풍의 눈에 대한 공격에 피 엘프와 함께 할 것인가?"
rows["178:1672039102"]="경비자들로부터 멀리 떨어져 있어, 이 마법은 밤 엘프들의 시야에서 지켜줄 것이지만, 여전히 거리를 유지해야 한다."
rows["178:1689929404"]="타이란데의 손으로 이 임무에 나 선택했어요$b$B그녀는 비전 때문이라고 했지만 아버지가 그녀를 이 임무에 동의하도록 설득했기 때문이라고 생각합니다."
rows["178:169771801"]="귀부인 팰리나는 생전에 식물학자였고, 죽어서는 거미를 키우고 돌본다. 거미 무리를 감독하면서 리치 왕을 위해 강력한 독을 개발하고 있지."
rows["178:17082807"]="내가 다드민을 청소하는 동안 모든 것을 지켜보도록 하겠습니다."
rows["178:1730808773"]="살데릴 경, 실버문의 멋진 포도주를 많이 준비했으면 좋겠어요. 이런 말씀드리기는 좀 부끄럽지만 그 포도주만 마시면 평범한 농가의 아낙이 된 기분이랍니다!"
rows["178:1750726720"]="우리의 탐구는 우리를 거대한 바다와 깊은 정글을 가로지르고 있지만, 우리는 여기 모든 곳에서 서로를 만나게 됩니다."
rows["178:1799796511"]="마케팅은 우리를 이 곳에서 벗어날 수 없습니다.$B$B그 무라를 가져와 항구로 가야 돼!"
rows["178:1837049448"]="우리 모두 아만니 제국을 계속 유지하려고 노력해. 이제 우리는 친구들을 갖게 되었습니다. 우리는 이제 젠다라리와 함께 있습니다. 우리는 더 큰 무언가의 일부분입니다. 당신은 우리를 막을 수 없습니다. 온 세계가 피를 흘릴 것입니다!"
rows["178:1947218381"]="하파나는 그냥 거무고, 당신을 드레드 캡틴 데메자 쪽으로 날려버립니다.$B$B한 거대한 팔의 털 아래에는 화살이 뚫린 심장에 \"MAGATHA\"라는 단어의 문신이 그려져 있습니다."
rows["178:1958217961"]="바락이나 돼지와 휘슬 타버너에서 구시가지를 둘러봐."
rows["178:2043018893"]="그렇다면 역사에 대한 여러분의 지식을 시험해 보겠습니다.  ⁇  쿠르드란 와일드햄러는 최근 용기 있는 그리폰이 화재로 죽었을 때 비극적인 손실을 당했습니다. 그리폰의 이름은 무엇이었을까요?"
rows["178:2120557128"]="저 복도 너머에 여러분이 적이라 부를 만한 자들을 주시하세요. 여러분을 갈라놓은 증오심에도 여러분의 적에 대해 존중할 본질이 있답니다. 그들의 용맹함은 인정받아야 하니까요."
rows["178:233698766"]="호드은 옛날의 영웅을 위해 울고 있습니다. 진정한 피의 오크는 인간에게 굴복하지 않고 배신도 안합니다. 우리 민족을 다시 자랑스럽게 만들 수있는 전사입니다."
rows["178:276615562"]="호드은 이제 우리의 자원 수집을 끝냈고 준비되어 있습니다. 우리는 단지 느린 얼라이언스이 그들의 전투를 끝내고 영광스러운 전투에 계속 될 때까지 기다립니다!"
rows["178:322911954"]="잘, 모든 것이 계획대로 진행된다면 곧 그론에서 해방될 것이고 산의 오그루들이 오그릴라에서 온 오그루들의 빛나는 축복을 누릴 수 있을 것이다."
rows["178:339385596"]="너 너 너 너 너 공자 자루를 찾아가야 마구'산 궁전의 발걸음을 걷고 있는 걸 알 수 있어$B$B네 지도에 그의 위치를 표시해 줄게"
rows["178:457835679"]="엘리사라 선스트라이커가 살테릴 신을 사로잡을 수 있다고 믿으세요?"
rows["178:471480180"]="Twilight의 해마어 (Twilight's Hammer) 은 죽음의 측면에 의해 위탁되었습니다. 그것은 세계들을 파괴합니다."
rows["178:520661864"]="고통에 참을 수 없는 사람들을 위한 치유입니다. 하지만, 당신이 해야 한다면,"
rows["178:579835479"]="야생 구름 뱀은 거의 번식하지 않으며, 따라서 각 알은 매우 귀중합니다.$B$B만약 우리가 야생 구름 뱀을 돕고 보호하지 않는다면, 언젠가는 사라질 수도 있습니다."
rows["178:586932855"]="우린 현재 블랙 테플을 테스트하고 있어$B$B카라잔을 하면서 얻은 명성은 이렇습니다."
rows["178:592765466"]="한 번, 진우는 이 곳에서 온 판다리아를 통치했습니다.$B$B우리는 역사에서 가능한 모든 것을 배워야 합니다. 그래서 우리가 다시 우리의 고대 지혜를 되찾을 수 있습니다."
rows["178:693864335"]="여어, 친구! 언더시티 전투는 이미 시작됐어. 스랄이 안에서 싸우고 있으니 찾을 수 있을 거야. 아니면 여기서 기다려도 돼. 곧 돌아올 테니까."
rows["178:714156310"]="시라, 시라, 내가 만난 가장 아름다운 사람이자 파다리아를 걷는 가장 친절한 영혼이다.$b$b우린 결혼하고 싶어 하지만 그녀는 골든드라프트, 난 웬더브루"
rows["178:725811461"]=" ⁇ 산디, 우리 집으로 돌아오게 해!  ⁇ 스피어로 돌아가서 다시 드럼을 들아라!"
rows["178:760769745"]="한 번 앉으면, 고객 은 니들 수프 를 배달 하기 위해 잠시 기다립니다. 줄을 서는 것 처럼, 고객이 떠나기 전 에 음식 을 가져갈 것을 확실히 하십시오."
rows["178:810633278"]="발린다 스톤하스 대장이 전선에 얼라이언스 그녀는 북쪽 전투장인 스톤헤어스 포스트에 있다.$B$B발린다가 죽었어"
rows["178:811114515"]="이것은 여러분이 익숙한 환경과는 다소 다르겠죠. 그것은 우리가 가진 힘을 보여 주는 것뿐입니다. 우리는 자원을 의식합니다."
rows["178:814527674"]="내가 도와줄 수 없어, 넌 나보다 더 오래 걸린 사람을 만나기 위해 준비됐어 얼라이언스 그래서 리얼리아마 스파크스핀드와 얘기해 스톰윈드."
rows["178:909613677"]="이웃을 도와줘서 이웃이 널 도울 거야$B$B물론 가끔씩 집 일을 도와줄 수 있지만 선물은 더 빨리 친구를 만들죠"
rows["178:920167950"]="감옥은 왜 가고 싶은가?$B$B정말 거기 가려고 한다면 조심해 난 폭동 소식을 들었어"
rows["178:952151345"]="안녕하세요, 저는 시카리입니다. 자이드 번개와 치, 치유 안개가의 마스터입니다. 이 재판에 대해, 당신은 내로 오는 환상으로부터 나를 보호해야 합니다."
rows["179:1033434570"]="마트레인은 참신한 피부를 벗는 데 능숙합니다. 만약 이것이 당신의 습관이라면, 사테인을 피부로 공급합니다."
rows["179:1052442756"]="랜달은 좀  ⁇ 지만 믿을만한 사람이고 제가 취학하는 학생들 중 많은 분들이 더 많은 것을 말할 수 있습니다."
rows["179:1082273099"]="누가 알 수 있겠지, 어떤 어두운, 끔찍한 것들이 바깥 어둠 속에서 거꾸로 거꾸로 거꾸로 거꾸로 거꾸로 거꾸로 거꾸로 거꾸로 거꾸로 거꾸로 거꾸로 거꾸로 거꾸로 거꾸로 거꾸로 거꾸로 거꾸로 거꾸로 거꾸로 거꾸로 거꾸로 거꾸로 거꾸로 거꾸로 거꾸로 거꾸로 거꾸로 거꾸로 거꾸로 거꾸로 거꾸로 거꾸로 거꾸로 거꾸로 거꾸로$B$B- 우리는 알고 있습니다. 당신은 더 많은 것을 알고 싶어 왔어요."
rows["179:1115519197"]="|TInterface\\Icons\\inv_misc_head_dragon_black.blp:20|t  ⁇ 은 탱크에 지구의 힘을 심어주죠 |cFF9900CC|Hspell:106218|h[최후의 수호자 아제로스]|h|r!"
rows["179:111828425"]="우리 부족의 몇몇은 번개의 힘을 이용했습니다. 우리는 그것을 인간, 오크, 공룡 등 침략자로부터 방어하기 위해 사용합니다.$b$b우리 번개는 모든 공룡을 놀라게 해"
rows["179:1153757899"]="비서기 키우를 시로스로 보냈는데, 그녀는 아직 돌아오지 않았어."
rows["179:1173159926"]="페어웨더와 저는 실바나어의 이익을 대변하고 있습니다.$B$B드루이드는 수용하는 것 이상이었지만 호드의 여정을 허용하면"
rows["179:1190112355"]="말푸리온 스톰게이지, 더 오래 당신을 바쁘게 유지하기를 희망했었는데"
rows["179:1256771427"]="제 목숨을 구해주셔서 감사합니다. 동료들에게 돌아가 당신의 용맹함을 널리 알리겠습니다. 온 힘을 다해 스컬지와 맞서 주십시오. 우리들이 곁에서 응원하겠습니다."
rows["179:1283216156"]="먼저 정착해 보세요. 여러분은 농장을 재배할 수 있을 겁니다. 하지만 더 나아가기에는 너무 경험이 부족하다고 생각합니다."
rows["179:1323857444"]="이 항구? 이 밤 엘프의 곳으로 가는 배를 잡을 수 있어요. 그 이름이 뭐죠? 아우베르딘은 모르겠어요."
rows["179:1358887839"]="만약 동아리 조직을 만들고 싶다면, 동북부 다르나서스의 공예인 테라스에서 리시아나라는 소속 기단장님을 만나야 합니다."
rows["179:1395453761"]="선물은 어디서 찾을 수 있을까요?$B$B이런 농장에서 어떤 일이 일어날지 알 수 없습니다.$B$B어쩌면 당신 자신의 땅에서 뭔가를 파고 갈 수도 있겠죠!"
rows["179:1434161170"]="지금 이 순간은 적들과 전투장에서 맞서기 위한 시간입니다. 제가 말하고 있는 동안 우리 형제 자매들은 켈다나스 섬의 킬제덴군을 물리치려고 싸우고 있습니다."
rows["179:1486588205"]="지금 내가 중요하지 않아, 트롤이 탈출할 수 있도록 도와줘서"
rows["179:1498784846"]="제네트렌이라고 부르는 한 지역 화학자를 알고 있는데, 마지막으로 봤을 때 그는 사라틸의 항구로 향하고 있었는데"
rows["179:1505044668"]="그래, 도시에 약초 판매자가 있습니다. 하푸나 랜드워커는 건물 안으로 들어오는 동안 왼쪽의 숙제실에서 찾을 수 있습니다.$B$B지도에 위치를 표시해 줄게요"
rows["179:1601973489"]="만약 아버지가 죽으면, 그는 세계 기둥의 중간 조각이 어디에 숨겨져 있는지 알고 있습니다."
rows["179:1603451338"]="이 존재는 수천 년 동안 땅속에서 동면하고 있었죠. 때를 기다리면서... 자신을 해치려는 자들에게 복수할 그 순간만 기다리면서 말이죠."
rows["179:1607789474"]="검색 중... 창조주들은 기생 감염체를 적출하기로 했습니다. 그러나 검사 결과, 고대 신 증후군이 악성으로 진전했음이 밝혀졌습니다. 기생체를 제거하면 숙주의 생명 활동도,"
rows["179:1619923150"]="네 아버지는 내 아이들을 죽이고, 그들의 시체를 드래곤즈 엔드에서 돌의 칼에 매달아 놓았어."
rows["179:1670513963"]="난 다르나서스 잠겨있었어! 도시로 침입하려고 했던 모든  ⁇ 돌이 놈들을, 내가 잡았어! 내 함정을 통해 이동하려 했던 모든 2비트 짜릿한 초라탄을 빼앗아갔어!"
rows["179:1746826969"]="여기에는 옛 신이 언급되어 있습니다. \"Y'Shaarj\". 일곱 머리 동물, 어둠을 숨쉬는 것인데 그 물건은 오늘날까지 판다리아를 괴롭히는 샤의 근원이라고 생각합니다."
rows["179:1800125799"]="내가 누군가의 말에서 떨어질 때마다 책임을 지지는 못해요. 어떻게 공식적인 봉기를 받았는지 모르겠지만, 돈을 받아서 다시 말해주세요!"
rows["179:1843090967"]="느껴지는가? 불쌍한 생명체들이여! 이 땅에 드리워진 그림자는 전주곡에 불과했다. 머지않아 너희들이 소중히 여기는 모든 것이 우리 손아귀에 들어올 것이다. 너희는 리치 왕의 힘 앞에 무릎을 꿇으리라."
rows["179:1910817115"]="키렌의 신뢰성 있는  ⁇ 리업에 오신 것을 환영합니다. 제 가게는 여러분의 필요에 맞는 것 같습니다. 저와 함께 훈련하고 싶다면, 부탁만 하세요."
rows["179:1945707248"]="브루페스트에 오신 것을 환영합니다. 그 안에 재미를 유지하기 위한 방법이 많아서, 질문이 있다면, 알려주세요. 그렇지 않으면 맥주와 프레스텔을 사세요!"
rows["179:1949110358"]="마법사의 직업은 자연의 중심에 있는 파괴와 창조의 순환을 보여줍니다."
rows["179:2003651779"]="스태프들은 한아시, 트롤 무기 마스터가 가르치고 있습니다. 오그리마'예의 계곡'과 '안세크와'의  ⁇ 어무기 마스터 썬더 블러프."
rows["179:206076122"]="내가 어떻게 할지 잘 알고 있소 지옥의 아들아, 너희들이 서서히 너의 무능함을 깨닫고"
rows["179:2105367873"]="최근에 여기 있는 몇몇 데피아즈단들과 나쁜 만남을 가졌지만 미셸 벨은 저를 꽤 잘 고쳐줬어요."
rows["179:2110556252"]="유일론의 눈앞에 있는 우리 학생들 중 많은 사람들이 그 벽 안에서 훈련을 계속하도록 보내집니다."
rows["179:2144261561"]="화학자는 평범한 허브를 통해 기적들을 할 수 있고, 치료와 수중 호흡 등 모든 효과를 가진 안정적인 약으로 변환할 수 있습니다."
rows["179:431915813"]="알터랙밸리의 묘지는 죽은 자들의 영혼들이 휴식을 취하고 구원받는 곳이고, 만약 당신이 죽으면, 당신의 영혼은 우리의 가장 가까운 묘지로 이동할 것입니다."
rows["179:441066742"]="이곳을 떠나라... <유물이 희뿌옇고 뜨거운 불길을 내뿜습니다. 머릿속에 환영이 나타납니다. 검은무쇠 드워프 하나가 일곱 개의 시체에 둘러싸여 불타는 비석 앞에 무릎을 꿇고 있습니다.>"
rows["179:441159263"]="정찰병의 보고에 따르면 리치 왕은 얼어붙은 왕좌 바깥쪽, 투영의 전당이라 불리는 곳에 자기 공간이 따로 있다고 한다. 영웅들이여, 그곳이 우리 목표다."
rows["179:486627617"]="때가 왔다, 굴단! 너의 흑마법사들에게 좀 더 노력하라고 해라! 지금부터 어둠의 문이 열리고 너의 호드는 이 썩어빠진 불신의 세상으로 풀려날 것이다!"
rows["179:494138226"]="수직자 들 이 필요로 하는 물품 의 상당수는 다르나서스 를 통해 오게 됩니다. 그 들 이 모두 일 하기 위해 그곳 으로 이사 한 것 은 놀라운 일 이 아닙니다. 수직자 되고자 한다면 다르나서스 로 이동 하는 것 이 좋다."
rows["179:496737960"]="이 의심스러운 곡물을 압수하고 있어요, 페렐리."
rows["179:563459735"]="모가들이 뱀의 척추를 건설했고, 가장 불행한 노예들은 그 구조와 방어에 도움을 주도록 보내졌고,"
rows["179:614025022"]="내 자유를$B$B내 사람들을 함께 죽음의 날개에 대항하도록 풀어주십시오.$B$B그게 충분한 이유가 아니라면, 당신은 큰 부로 보상될 것입니다."
rows["179:652085369"]="수천 년 동안, Ilyenia Moonfire는 수많은 무기를 마스터하고 지금은 다른 사람들을 훈련시켜서 사용하도록 제안합니다."
rows["179:672556606"]="우리 이 세상 이 섬세 하게 엮인 조직 은 매우 섬세 한 조직 이다. 이 조직 을 찢기 위해 단지 약간의 지식 과 그 지식 을 적용 하는 것 이 필요 합니다. 따라서 균열 이 탄생 합니다. "
rows["179:706646559"]="제네트렌이라는 지역 화학자를 알고 있는데, 마지막으로 봤을 때 그는 살테릴의 항구로 향하고 있었는데"
rows["179:715802970"]="준비는 완료됐어 이제 당신과 당신의  ⁇ 돌이 앞에 있는 것은 더 큰 소환의 순례와  ⁇ 돌의 정신을 묶는 것입니다"
rows["179:72038844"]="드루이드들이 행하고 있는 달 축제 기념식은 무롱라데에서 열리고 있습니다. 여행하기에는 너무 멀리 있다면, 그들은 바로 바깥 스톰윈드에 교통을 제공하고 있습니다."
rows["179:890364308"]="벨의 통불에 1:00 오후입니다. 우리는 점심 시간 급행 중입니다! 당신의 독, 전염병과 유해 가스들은 60 초 안에 배달됩니다 또는 당신의 주문은 무료입니다!"
