rows["180:1082813391"]="내가 이 랩터로부터 벗어나서 쉬게 됐다고 생각했을 때, 여기 상황은 더 악화됐어요.$B$B하지만  ⁇ 은거리가 쓸모없어 우린 이 문제를 제대로 된 왜소처럼 다뤄야지"
rows["180:116387521"]="하지만, 중요한 건 아닐세. 클레멘타인 씨의... 음, 공헌에 대한 얘기가 있긴 하지만 이건 놀카이라는 자의 일지인 것 같네. 그리고 뒷부분에 기록된 내용은 잔인한 전쟁에 대한 묘사일세."
rows["180:1215748503"]=" ⁇  모로흐의 추운 곳에서 작은 꽃이 계속되는 것을 보는 것은 놀랍지만 여기서 약사가 없을 것입니다. 아이언포지 그 직업에 대한 교육을 받을 수 있도록"
rows["180:1225659502"]="잘 된 거!$b$b그는 부의 약속을 하면서 바보들을 유혹하고 술에 취해서 더러운 일을 하기 위해 그들을 이용하죠.\010"
rows["180:1265982885"]="치마에론, 정말 제 과학 능력의 살아있는 증거입니다. 저는 수년간 그의 형태를 수많은 번이나 변형하고 왜곡했습니다."
rows["180:1277931318"]="형제들이여, 전우들이여! 나는 호드의 병력을 찾아 이곳으로 이끌러 가야 한다! 용감한 사냥꾼들이여, 마음을 굳게 먹어라! 차원문에서 쏟아지는 악마들에게 쓰러지지 마라!"
rows["180:1306331904"]="풀이 부드럽고 풍요로운 공기, 빛과 노래가 가득한 신선한 공기. 내가 본 모든 것 은 테일드라시일이 꿈이 실현 된 것 을 알려 준다. 그렇다면 왜 내 마음 은 선망으로 가득 차 있습니까?"
rows["180:1363047158"]="그 때 저는 매우 자랑스럽게 Brakgul Deathbringer가 무장실에서 당신을 도와준다고 말씀드리고 있습니다."
rows["180:1454023862"]="여기 키우는 와이버너들은 드레너가 제공하는 가장 잔인하고 이상한 날씨를 감당할 수 있도록 훈련받았어"
rows["180:1482840634"]="그들은 코링우드를 해안에서 침몰시켰지만 우리는 그녀의 카로나드를 해안으로 끌어당겼습니다.$B$B그 동물들은 이 해변에 한 발도 걸지 않을 거야"
rows["180:1488781983"]="제 도끼는 많은 전투를 보았고, 저는 그것을 손에 들고 있는 것을 좋아합니다. 적군이 수도를 몇 번이나 침략했지만 두려워하지 마세요. 우리는 항상 그들을 쫓아냈다."
rows["180:1508823026"]=" ⁇ 슨의 옷장에서 세일랑드와 얘기해봐"
rows["180:1537081925"]="이 실패에도 불구하고 저는 다시 한번 제 비중을 달성하기 시작했습니다. 최근 스톰스타우트 맥주공장에서 어떤 일이 일어나고 있는데요."
rows["180:1549173440"]="오늘날 은 스컬지 의 많은 패배 중 첫 번째 날 이다! 죽음 기사 들 은 한 번 리치 왕 의 봉사 에서, 그의 포수 를 벗어났으며 그의 독재 에 대항 하여 새로운 얼라이언스 을 형성 하였다!\010"
rows["180:1635161396"]="사실, 윈터스프링의 언덕들은 현재 스컬지 공격, 당신의 도움이 큰 도움이 될 것입니다.$B$B남아있는 네크로폴리스의 수는: $2284W"
rows["180:1645646165"]="어쩌면 사라 스틸푸리는 언젠가 내처럼 좋은 도끼를 만드는 법을 가르쳐 줄지도 몰라"
rows["180:1659028510"]="5분 후에 위커맨의 불타는 일이 시작될 것입니다 언더시티 - 그리고 하로우의 끝을 축하하고 스컬지!"
rows["180:1762929938"]="이 판다렌 농부들은 사람들을 즐겁게 하고 있습니다.$b$b칼림도어 또는 동부 왕국에 있는 큰 도시들과는 매우 다릅니다."
rows["180:1818740286"]="난 람카헤네의 나두누 왕자네프레셋 부족이 다른 톨'비르에 반발했습니다$B$B날 탈출시키세요. 그래서 내 동생인 왕을 이 배신자들과 전쟁을 하도록 롤비할 수 있어요!"
rows["180:1846420978"]="엄호해 주시오. 빨리 끝내야 하오. 내가 이쪽 측면의 수정을 날려버리면 시로나스에게 힘을 주는 광선을 방해하여 그녀가 깨어날 것이오! 그녀가 우리를 보면 엄청난 화를 내뿜을 거란 생각이 드는군..."
rows["180:1881922866"]="저는 신생들을 훈련시키는 시간을 순수심의 힘으로 보낼 수 없습니다. 우리의 동맹인 죽은자가 너무 고통받고 있습니다."
rows["180:1910077410"]="정확히는 모르겠군요. 왕자가 성기사 훈련을 받고 있다고 듣긴 했습니다. 테레나스 국왕은 은빛 성기사단에서 왕자를 교육시킬 것이라고 믿고 있지요. 아서스 왕자를 제대로 교육시킬 인물이 있다면 바로 우서 경일 겁니다."
rows["180:1945008133"]="두 명의 연인을 찾고 있는데 그들의 가문의 야망을 알지 못해$b$b불행히도 그들은 나무들나 예술 속에서 답을 찾지 못했습니다."
rows["180:1952643887"]="영웅들, 우리는 이 짐을 다시 한번 여러분의 어깨에 부어넣어야 합니다. 아제로스."
rows["180:2036301491"]="물 의 영 들 은 가장 솔직 한 말 이 아닐 수 있습니다. 그들은 친절 하고 이해 합니다. 사실, 만약 당신이 목소리 들리는 데 어려움을 겪고 있다면, 물 을 시작 해야 합니다."
rows["180:222131020"]="제 시간을 낭비하기 위해 여기 온다면, 당신은 전체적으로 센리온 서클의 시간을 낭비하고 있습니다."
rows["180:350054211"]="불행히도, 당신의 경험으로 누군가에게 가르쳐 줄 수 있는 것은 거의 없습니다. 다르나서스의 공예인 테라스에서 거주하는 밤 elf Sylvanna Forestmoon를 찾아보세요."
rows["180:359405935"]="동물들을 돌보는 것은 울브렉 파이어핸드가 아주 진지하게 받아들이는 일이죠. 보통 그는 사냥꾼들과 함께 무장관에서 어울려요."
rows["180:359480460"]="무익한 문명의 불구속 시민이 될 정도로 헌신적으로 레지옹을 섬길 사람들이 있다는 것을 아는 것이 두렵습니까?"
rows["180:405360541"]="불타오염 반도에서 우리의 많은 적들 중, 불타오염 성곽의 오크들이 그들 가운데 서 있는 것은 안타깝습니다.$B$B하지만... 누가 더 나은 도전하고 호드오크보다?"
rows["180:500351016"]="오크여, 더 이상 때리지 마라! 말할 테니까! 암호는... 갈퀴흉터 거점에 있는 상자들 중 하나에 숨겨져 있다... 그곳에 있는 나가가 열쇠를 지니고 있다..."
rows["180:571525327"]="은빛십자군과 칠흑의 기사단에 있는 우리 동맹은 얼음왕관의 정문을 통과하여 성채 안에 근거지를 마련하려는 중이에요."
rows["180:580938157"]="아니, 대체 왜 그런 짓을 한 게지? \"누르지 마시오.\"라고 쓰인 경고 문구 못 봤나? 자폭 장치를 활성화해 놓으면, 도대체 어떻게 발명품을 시험하지?"
rows["180:65392281"]="얼라이언스의 방문 멤버들은 주로 남서쪽 달라란의 실버 앙클라브에 머물고 있다.$B$B거기에는 숙소가 있고, 다양한 전투장과 스톰윈드의 포털도 있다."
rows["180:700907037"]="미안하지만, 내가 아는 모든 걸 이미 배웠어. 밤 elf Faldron은 당신에게 추가 훈련을 제공 할 수 있습니다. 다르나서스."
rows["180:738746744"]="오늘 네가 승리했지, 하지만 내일이 안되네."
rows["180:857953570"]="넌 그냥 확대해 나가야 해! 난 네가 모르는 걸 가르쳐 줄 수 없어, 하지만 스프링스파이더 피즈레거는 확실히 할 수 있어! 아이언포지 스프링스피델을 찾을 수 있어. 행운아!"
rows["180:88688406"]="신성 상징, 체크, 촛불, 체크 아카나 파우더, 아카나 파워?"
rows["180:926982055"]="틈이 떨어지고 썬더 블러프 이 포털은 공격의 두 번째 반이 될 것입니다.$B$B포털로 들어가서 공격에 압력을 가해"
rows["180:938073528"]="형제들이여, 전우들이여! 이곳에 호드의 힘이 필요하다! 용맹스러운 사냥꾼들이여, 정신을 무장하라! 어둠의 문에서 기어나온 악마들에게 무릎을 꿇을 수는 없다!"
rows["180:941906501"]="우리가 불지방에 침입할 준비를 하고 있는 동안, 불의 주인이 그의 하사들을 보내서 우리의 공격을 물리칠 것입니다."
rows["181:1047415218"]="인정해야 합니다. 이 야심찬 작은 신생에 대해 흥미를 느끼고 있습니다.$b$b판단에 서두르지 않겠지만, 불안한 소문을 들었어요.$b$b그의 동기는 옳지 않은가?"
rows["181:1054833005"]="이 부부의 아들들과 딸들 호드오늘 당신은 당신의 영웅들의 힘과 이 챔피언의 행동으로 인해 자유로울 것입니다 $p코크론의 도착은 호드."
rows["181:109137279"]="이제 주사위는 던져졌다. 쿠엘다나스 섬에 온 것을 환영한다. 태양샘은 남쪽 고원에 있고, 캘타스 왕자는 동쪽에 있는 마법학자의 정원에 숨어 있다."
rows["181:1094033683"]="네, 형제들아, 우리는 이 죄수에게 진작 Twilight의 아들들을 주장하고 있습니다."
rows["181:1267304598"]="도심문 밖에서 다렛이라는 워크겐 드루이드가 있어요. 당신을 도울 수 있을지도 몰라요.$B$B흰색 가죽과 털로 덮인 거대 괴물이야"
rows["181:1292821817"]="$B$B빨리, 도시의 각 구석에 있는 얼음 돌을 이용해... ...원자계로 가는 포털을 열어 책임자를 불러라.$B$B승리할 수 있도록 모든 돌을 동시에 활성화시켜라"
rows["181:1509232291"]="죽음의 날개가 세계 기둥을 파괴했을 때, 그는 당신과 우리 사이의 격차를 열었습니다.$B$B함께 처리할 수 있는지 보자"
rows["181:1515250992"]="내가 내 왕에게 짐승의 귀를 보여 주며 그 짐승의 죽음을 내 것으로 주장하고 내 이익을 위한 보상을 가져오겠다. 다른 사람이 실제로 한 일을 자신의 것으로 주장하는 것은 잘못이다."
rows["181:1525610216"]="형제자매들이여, 우리의 수는 적지만 오늘 나와 함께 피를 나누자! 그렇게 지독하지는 않으리라. 최근 적들의 상황은 악화되었다."
rows["181:1525763464"]="스팀위들 전투 경기는 시작되었습니다. 아레나 조직원들이 가젯잔에서 아레나 팀 차터를 판매하고 있고 나그란드와 블레이드즈 엣지 산맥의 아레나 밖에서 있습니다."
rows["181:1576410420"]="전 탐험가 리그에 일했지\010하지만 그때 제가 정말 찾는 유일한 것이 귀화물이라는 걸 깨달았습니다.\010크고 빛나는, 다채로운, 귀중한 보석... 오, 내가 당신을 얼마나 사랑하는가!"
rows["181:1633848692"]="만일 너희가 우리의 메시지에 관심이 있다면 나는 모임을 개최하리니 더 많은 것을 알고 싶다면 나와 이야기하라 그러나 주의하라 실로 오그리마는 진리를 침묵케 하는 사람들로 가득차 있나니"
rows["181:1769621397"]="환상 터널들, 스피디와 저는 이 적들을 마주쳤어요. 조심하세요. 그들은 땅에 묻어서 갑자기 새로운 목표 아래로 튀어나오게 될 수도 있습니다."
rows["181:1796556240"]="이게 좋을 것 같아요. 이제 조각을 해야겠어요. 쉬운 작업은 아닐 거예요. 난 설인 암컷이 짝짓기할 때 내는 소리가 어떤지도 모른다 말이에요!"
rows["181:1816687009"]="내 사람들은 와일드햄러와 좋은 관계를 오랫동안 유지해 왔습니다.$B$B우리 중 몇 명이 이곳에 정착해 왔어요. 이 땅을 지키기 좋은 집이라고 생각하는 사람들입니다."
rows["181:1893815783"]="사지 멀쩡한 이를 모두 끌고 나와 대규모 공격을 벌여 봤자, 쓸데없이 우리 용사들만 죽어나갈 뿐이다. 쓰러진 이는 적으로 되살아날 것이다. 아제로스는 언데드의 위협 앞에 속수무책이 될 것이다."
rows["181:1913363491"]="모트가 널 내게 보내지 않았나? 그는 더 잘 알고 있어. 네가 내가 너에게 가르쳐 줄 것을 아직 이해할 수 없어. 내 아들 모트를 보러 나가, 그와 함께 훈련을 마감하라. "
rows["181:1924448274"]="내가 아직 준비를 마친 건 아니지$B$B성전을 존중하고 내게 돌아오라 우리는 서둘러 산을 무시해서는 안 된다."
rows["181:2023146951"]="사용된 모든 조각은 우리를 낭비하지 않게 하고 지구 어머니와 더 가까워지게 합니다. 무란타는 길을 알려줄 수 있습니다. 썬더 블러프 중층에 갑옷을 들고"
rows["181:2082143741"]="트래커 랭, 스테이블 마스터는 주요 건물에 들어가기 전에 메인 테라스에서 발견됩니다.$B$B지도에 위치를 표시해 줄게요"
rows["181:341514249"]="수도원 수업을 그만두면 무슨 일이 일어날지 알겠어?$b$b하지만 나쁘지 않아, 내가 직접 닦아줄게$b$b우는 숨쉬고 있다"
rows["181:345693633"]="색상과 세부사항에 대한 더 나은 눈을 배울 수 있는 것은 아무것도 없습니다. 시몬 테너와 이야기하세요. 그는 가죽을 다루는 많은 첨단 기술을 알고 있습니다."
rows["181:350924934"]="저는 이 연구에 도움을 주는 것이 영광이라고 생각합니다. 아제로스아시다시피!\010내가 도와줄 게 있어?"
rows["181:423419386"]="고마워 친구, 지금 네가 개입하지 않았더라면 난 그 불쌍한 구조에 묶여있었을 거야$B$B하지만, 저는 여기 없어야 합니다. 우리는 영결제자들을 막을 필요가 있습니다."
rows["181:450343972"]="아칸라이트 스펜러에 대해 얘기하고, 가혹한 아담안티트의 녹음 요구사항에 대해 불평하고,"
rows["181:524771723"]="포세이큰 지원군이 도착할 때까지 얼마나 남았소? 이곳에서 우리 처지가 위태로운 상황이오. 당신의 여군주는 우리에게 더 많은 병력을 약속했소. 데솔름과 스컬지에게 전력을 집중해야 해!"
rows["181:540105786"]="죽어가면서 간단한 수학적 능력을 완전히 파괴했을 겁니다. 그 구조의 레이아웃이 작동할 수 있는 방법은 없다는 것을 알 수 없나요?\010"
rows["181:578245280"]="우리는 적은 수지만 행복한 소수, 피를 나눈 형제자매다. 오늘 나와 함께 피를 흘린 자는 누구든 내 가족이 되리라. 아무리 미천한 자라도 오늘은 귀한 이가 되리라."
rows["181:633024758"]="이제 당신은 당신의 삶을 저와 나의 삶을 연결하는 길을 따라갈 준비가되어 있습니다. 단 한 시간이라도. 하지만 우리는 당신이 영들이 말하는 것을 이해하도록해야합니다."
rows["181:664279452"]="난 너무 늙어서 너무 많아요$b$b<함대장 시아호른은 숨을 쉬기 위해 잠시 멈추고 있다.>$b$b내가 무슨 말인지? 그들은 충분하지 않습니다!"
rows["181:669524829"]="많은 사람들이 땅 각지에서 온 것으로 문이 열렸으니 너희 백성들 가운데는 이미 많은 자들이 들어왔으니 너희는 그 안에서 위안을 구하고 피난처하라"
rows["181:682172943"]="이제 우리 불에 대해 알고, 그들을 존중하고, 우리의 적의 불에 대해 알고, 그들을 끄는 것을 알고, 당신은 그에게 돌아와 보상을받을 수 있습니다."
rows["181:684052571"]="드루이드 들 은 자연 이 호드 를 칼림도어 에서 쫓아낼 때까지는 단지 시간 문제 일 뿐이라고 말 합니다. 그럼에도 불구하고 부패 는 우리 땅 에서 계속 퍼지고 있습니다. 심지어 여기 텔드라시일 에서도 마찬가지 입니다."
rows["181:796448628"]="고 마법사 바르도란은 스라이어 계층의 시어 도서관에서 발견 될 수 있습니다. 예술의 위대한 마스터, 그는 그의 학생들: 마스터, 수련자, 전문가, 여행자들로 둘러싸여 있습니다."
rows["181:849180061"]="마녀들은... 그 마녀들은... 그 마녀들은... 그 마녀들은..."
rows["181:897334194"]="오, 짝지 이 귀여운 녀석! 보세요, 잘 되는군요! 수렁군주들이 잘 먹는군요! 이제 제가 할 일은 여기서 이 버섯들을 더 많이 기르는 일이랍니다. 수렁군주들도 이제 스포어링들을 건드리지 않을 겁니다!"
rows["181:900830423"]="우리는 함께 일하고 있을지도 모르지만, 그것은 단지 신중한 필요성을 증가시킵니다.$B$B우린 여기 있는 유일한 사람이 아닙니다"
rows["181:908124254"]="제 시간에 배울 수 있겠지만 아직 못 해! 스프라이트 점프스프로켓과 얘기해봐요."
rows["181:935583595"]="샤에 대한 우리의 많은 지식은 시간이 지남에 따라 사라졌습니다.$B$B전투가 계속되는 동안, 저는 그들의 본질을 연구해야 합니다.$B$B그러면만 앞으로 이런 일이 일어나지 않도록 할 수 있습니다."
rows["181:942856188"]="좋은 쇼... 내가 당신을 설득하지 못했어요. 제 직원들을 무리한 학살으로 고용 신청에 부정적인 영향을 줄 수 있을 것 같아요."
rows["181:960230775"]="만일 너희가 우리의 메시지에 관심이 있다면 나는 모임을 개최하리니 더 많은 것을 알고 싶다면 나와 이야기하라 그러나 주의하라 실로 스톰윈드는 진리를 침묵케 하는 사람들로 가득차 있나니"
rows["181:970167780"]="만약 불방습을 연습하고 싶다면 여기서는 눈이 많이 올 수도 있지만 스틸그릴이나 그 거미들이 언제 폭발할지 알 수 없죠"
rows["181:977960456"]="우리는 안전하다... 당분간은 말이지. 마지막으로 싸웠을 때보다 아서스는 열 배나 강해졌다. 리치 왕을 물리치려면 강력한 군대가 필요하다. 호드가 모을 수 있는 것보다 더 강력한 군대 말이다."
rows["181:984163411"]="이름에서 알 수 있듯이, 유적 근처에서 발견될 수 있습니다. 로레스 아란은 답을 가지고 있습니다.$B$B사실, 이름에서 그런 생각이 들지 않습니다. 저는 단지 곰팡이를 명명하는 데 똑똑해지기 위해 노력했습니다."
rows["181:994793773"]="결국, 난 내 의무였기 때문에 전두환에 서있었고, 나를 쓰러뜨린 건 네가었기에 기쁘다. 호드... 번영의 새로운 시대를 맞이하게 될 것입니다."
rows["182:1062483199"]="대라란 북서부 마구스 무역 거래소에는 큰 수강과 도자기장이 있습니다.$B$B거대한 마법의  ⁇ 과 색칠 된 유리 창문을 찾아보세요."
rows["182:1095013088"]="이 공연에서 나보다 더 잘하고 난보다 더 많은 경험을 가진 사람을 원하니까 다르나서스."
rows["182:110643759"]="월트는 무슨 말을 하는지 몰라 난 혼자 이 왜곡자들을 쫓아내고\010"
rows["182:1142010428"]="레크슬로트가 정보를 원한다면 돈을 지불해야 한다고 말해줘"
rows["182:1214611751"]="당신은 그 안에 보고 싶어 언더시티. 옛 유적에 로데론여기 남쪽으로 엘리베이터가 내려가면 언더시티 수호자 더 많은 방향에 대해"
rows["182:1243380220"]="아바스트 유, 친구  쿠키는 내 이름, 요리는 내 게임 맥위크사우스 혈통은 남녀의 섬세한 감각을 기쁘게 하는 요리사와 상인들이 긴 줄입니다"
rows["182:1266792900"]="정해져 있습니다. 영원한 꽃의 계곡은 열려있을 것입니다. 외부인의 범죄는 큰 ...하지만 나는 그들이 잘못 된 것을 바로 잡을 수있는 능력을 본다."
rows["182:1286311176"]="이제 우리가 가장 친한 친구인 만큼 고백해야 할 일이 있는데... 농부 펑은 정말 좋아하지만, 또 다시,$B$B결정할 수 없어!"
rows["182:1336890193"]="다시 와서 이 같은 비참한 일을 해줘 내가 가시 소변으로 온화한 작은 철 상자 안에 집으로 보내줄게"
rows["182:1437601953"]="내가 필요한 미트릴 바를 모두 가지고 있을 뿐 아니라 호드 이제 모집이 끝났어, 보아도 얼라이언스 그리고 우린 전쟁에 나설 거야!"
rows["182:1505618768"]="그립은 동물들과 너무 많은 시간을 보내지만 그 외의 사람은 사냥꾼의 길을 알고 있지 않습니다."
rows["182:154532313"]="몇 가지 알고 있지만 전문가가 아니죠. 다행이 마거가 가게 뒤에 서있어요. 도와줄 수 있는지 보세요. 하지만 그를 짜증나게 하지 않도록 조심하세요. 그는 짜증나게 될 수 있습니다."
rows["182:164221702"]="아, 당신은 외계인이어야 합니다. 불행히도 저는 전쟁에 대한 무기를 만들고 있습니다. 한 번, 얼마 전, 기도와 축하를 위한 악기를 만들었습니다. 이 전쟁은 모든 사람들을 경계로 만듭니다."
rows["182:1651527347"]="적대자 가 어떤 일 을 하고 있든, 적대자 가 압력 지점 에 적절 한 힘 을 행사 한다면 그 는 그 의 발길 을 막아낼 수 있습니다. 이 방법 을 이용 하여 위험 한 공격 을 피 할 수 있습니다."
rows["182:1864021065"]="죽은 놈들이 비극에도 불구하고 우리를 도와줄 수 있어"
rows["182:1883944288"]="내가 설명할 시간도 없고, 욕도 없어요. 이제 중요한 말이 있으세요?"
rows["182:192139800"]="저는 이것이 원래의 전력원이라고 믿습니다. 그는 피 엘프들에게 선웰에 대한 중독에서 해방시키기 위해 제공하려고 했으나 어떤 이유로 그들이 가까이 오지 못하게 했습니다."
rows["182:1967588736"]="왜 카플라크와 얘기하고 싶니? 상관없어. 라저힐의 남서쪽 모퉁이에 있는 굴 위에 그를 찾아라."
rows["182:2006460408"]="치유을 만들려고?\010오드윈 라클린과 이야기해봐 스톰윈드 비스토르 센터에서"
rows["182:2069342424"]="낯선 사람, 당신 자신 의 의심 이 드러나고 있습니다. 판다리아는 당신이 온 땅과 같지 않습니다. 그것은 살아 숨 쉬고 있습니다."
rows["182:2076146304"]="주인님에 맞서는 자는 완전히 파괴되리라. 주인님을 섬기는 자는... 마음과 영혼을 다 바쳐 온전하게, 의심 없이 섬기는 자는 이해할 수 있는 경지를 넘어 저 높은 곳에 이르렀도다."
rows["182:232446171"]="마지스 트레이너인 케인 파이어송은 브릴의 남동쪽 끝에 있는 '갤러스 엔드 타버너'에 올라가서"
rows["182:279024284"]="우리 도시는 바다 밑에 있고, 우리 방은 다크 아이언 배신자들 가득하고, 난 상처가 너무 많아서 아무것도 할 수 없어.$B$B메네틸 항구에 오신 것을 환영합니다!"
rows["182:290752470"]="이 알두아르의 태블릿은 우리를 올바른 방향으로 이끌고, 브랜이 확신하고 있다면, 나도 확신할 수 있을 겁니다."
rows["182:352738387"]="사람들을 하나로 묶는 공통적인 적은 없다 왜나이 족속들이 이렇게 연합한 적이 없어 평화가 지속된다면 우리 세 왕국은 이전보다 강해질 것입니다"
rows["182:4293691"]="조르문트 스톤브로우가 바늘에 대한 재능이 있군 훈련이 필요하다면"
rows["182:528186748"]="잘했어, 웨이커. 내가 좀 더 오래 머물게 될거야 내 칼의 갈증을 가라앉히기 위해. 다른 사람들에게 내 귀환을 말해 줄 수 있겠지만, 나는 나의 빠른 날개들이 나를 당신 앞에 Klaxxi'vess에 데려갈 것이라고 믿습니다."
rows["182:589233082"]="대체 앞으로 증원군이 몇 명이나 더 다쳐야 저 나무를 베도록 허락해 줄지 모르겠군. 박쥐 때문에 엄청난 돈을 날리고 있는데 말이야. 여기에 그물이라도 쳐 놔야 하나..."
rows["182:602798792"]="이스파트, 친구, 더 단단한 소금도 없는데 북해의 자유 배들 뿐이야$B$B'아,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이,  ⁇ 이!"
rows["182:697872311"]="황제들이 죽으면 성전 내의 이동을 막는 마법의 보호가 크게 약해졌어요"
rows["182:764391800"]="작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고 작고"
rows["182:917175989"]="칠흑의 기사단 사령관이자 스컬지 제압자, 어둠의 무기고에서 승리를 거두신 란크랄 공작님의 명령에 따라, 즉각 사퇴를 선고하는 바이다. 어떤 의견이 있는가?"
rows["182:94608020"]="그렇다면 역사 에 대한 지식 을 시험 해 보겠습니다. 장갈마르쉬 에 위치한 이 건축물 은 아웃랜드 의 물 으로써 귀중 한 제한적 인 자원 을 배출 하려고 노력 한 나가 들 이 통제 하였다."
rows["182:990560801"]="스컬지의 군대가 타나리스로 왔고, 그들의 유적지들과 다른 세력들이 상당수가 그곳에 파견되었다고 합니다.$B$B남아있는 네크로폴리스의 수는: $2283W"
rows["183:1047004613"]="우리 앞에 쉬운 길은 없습니다. 만약 당신이 강한 팔을 가지고 있다면, 내 부대 중 하나가 Ymirheim에 올라갈 준비가 될 때까지 머물라. 그들은 그들이 얻을 수 있는 모든 도움을 사용할 수 있습니다."
rows["183:1048462483"]="만약 여러분이 우리의 해변에 가져오려는 전쟁이 있다면, 땅 자체가 여러분의 열망과 폭력에 반응할 것입니다."
rows["183:1183718841"]="샤도파인은 고대의 계급으로 가장 우수한 사람들만 훈련시키고 받아들인다.$B$B당신 이 유용 하게 할 수 있다면, 많은 강력한 물건 을 발견 할 수 있을 것 입니다."
rows["183:1203438685"]="우리의 최고 정신은 지진적인 활동을 연구하고 있습니다. 우리는 대부분 건물의 틀을 어떻게 확보할 수 있는지 조사하고 동시에\010"
rows["183:1283489272"]="내가 크리스탈을 이용해 태블릿을 보호해줘서 나를 방어할 힘을 줄 수 있어"
rows["183:1350632931"]="크로그 군주께서 이 전선을 잠금 지키기 위해 나를 보내셨지만 아직 군대를 보내지 않았습니다.$B$B이 곳을 봐, 난 괴물, 난 Twilight's Hammer, 난 아무것도 없어"
rows["183:1440862485"]="여기 서있었고, 여기 떨어졌어요. 시블반스 윈드런러의 시간 잃어버린 반향은 영원히 용왕궁의 부패한 장벽을 통해 울려 퍼질 것입니다."
rows["183:1468864167"]="네 마음이 가죽 작업에 있다면, 그레이트 포지의 북서쪽에 있는 그의 가게에서 피블 핀스핀드에게 얘기해봐"
rows["183:1550305677"]="네, 내가 원하는 대로 가르쳐 줄 수 있지만, 수미와 튜미로부터 멀리 떨어져 있어, 그들은 당신 같은 사람들을 위한 것이 아니다."
rows["183:1605408948"]="그래요, 우서 경. 용서하세요... 제가... 제가 왜 그랬는지 모르겠네요. 이 정보를 얼음왕관 성채 안에서 스컬지와 전투를 벌이는 기사들과 폐하께 알리겠어요."
rows["183:1667281967"]="필멸의 존재들이 이 지역에서 만든 세 균열은 반드시 봉해야 한다. 그렇지 않으면 대지가 우리의 작업을 보고 들어, 끊임없이 우리를 방해할 것이다."
rows["183:1689454750"]="물러나세요! 저 검에 손을 대면 영혼에 영원한 상처가 남을 거예요! 서리한에 갇힌 영혼들과 대화해봐야 해요. 자리를 좀 비켜주세요. 물러서요."
rows["183:1692433233"]="이 정보를 전달해 주는 게 영광이야. 마치 우리가 마침내 도시 내의 스파이를 찾았을 것 같군."
rows["183:1694141"]="당신이 그 안의 구석과 밤 엘프를 검사할 때, 당신은 예수우의 이상한 감각을 얻습니다. 어떤 이유로 그녀는 당신과 눈을 접촉하지 않습니다. 그것은 거의 당신이 그녀에게 거기에 없는 것처럼."
rows["183:1699414298"]="이제 아에리 피크에 가서 왜기 드랙 스톤핸드와 이야기해 보시오 그의 작품은 내 작품보다 훨씬 더 훌륭합니다"
rows["183:1755643202"]="네놈들의 후원자가 나타났구나. 하지만 너무 늦었어! 이곳에 흘러넘치는 마력은 세계를 수십 번은 파괴하고도 남는다. 녀석들이 무슨 도움이 될 것 같으냐?"
rows["183:1854054211"]="또 다른 군인이 어떻게든 해방되었고, 우리의 진주들을 깨고 우리를 해방시켰습니다.$b$b어떤 사람들은 표면에 향해 수영을 했습니다. 어떤 사람들은 이 동굴을 보고 그 쪽으로 수영을 했습니다.$b$b내가 유일하게 이겼어..."
rows["183:1895128458"]="안녕, 내 사랑 안비나... 그대 이름을 기억하는 이는 적겠지만, 세상을 구한 건 바로 그대야. 이제 타락은 걷혔어, 안비나... 영웅들이여, 그녀의 희생이 헛되지 않게 해 주오."
rows["183:1927471057"]="모든 것이 사라진 후에, 우리는 과잉을 거래할 수 있을지도 몰라요."
rows["183:1931362774"]="제 시선은 전 세계에 일어나고 있는 사건과 앞으로 일어날 수 있는 사건들에 대한 환상들로 가득 차 있습니다. 그 중 많은 것들이 암울하지만, 그 변화의 능력이 없다고 믿어야 합니다."
rows["183:193981141"]="듀크의 지브는 거무리의 친구였는데 3시즌 동안 계속했다. 이제 듀크의 오크가 지휘하고 가장 화가 났어요. 그는 머지않아 거무리의 음식이 멈출 것이라고 생각해서 파괴를 합니다."
rows["183:1965566406"]="저는 어린 타우렌이었는데 그 당시 겨우 십대기를 맞이했지만, 자유를 위한 전투를 용납하는 사람들은 제 이름의 의복으로 잘 보호받았다는 것을 알고 있었습니다."
rows["183:1978780545"]="모두 흥분을 가라앉히고 진정하십시오! 이 경기엔 아무 음모도 없었습니다! 저 흑마법사는 얼라이언스와 상관없이 행동한 겁니다. 마상시합은 계속 진행되어야 합니다!"
