rows["183:539579673"]="15분 후에 위커맨의 불타는 일이 시작됩니다. 언더시티 - 그리고 하로우의 끝을 축하하고 스컬지!"
rows["183:589360387"]="이 물체 를 장식 하는 여러 가지 이상한 조각 은 아마도 트롤 들 이 그 기원을 해독 하기 위해 만든 것 이다. 그 물체 는 무력 하 고 있기 때문 에 그 들 은 큰 성공 을 얻지 못한 것 같다."
rows["183:601507971"]="얼라이언스는 전쟁에 필요한 모든 것을 수집하는 데 성공한 것 같지만 이제 우리가 기다리는 것은 저 가난한 호드 생물들이 그들의 종을 끝낼 것입니다."
