rows["183:84649267"]="이웃, 넌 내 친구였으니 이제부터 내가 너에게 무상으로 농작물 예측을 줄거야. 전혀 수수료가 없어! 가끔 나와 함께 술을 마셔도 돼?"
rows["183:861897507"]="로얄 약학회도 바보들을 참을 수 없습니다. 아마 다음번에 당신과 내가 말에 대해 이야기 할 때, 당신은 언더시티에 의해 높이 평가 될 것입니다."
rows["183:917178892"]="늙은 개에게 새로운 트릭을 가르쳐주지 못해. 적어도 누군가 한 번 내게 말했죠.$b$b자, 애완동물이 재능들을 배워내기를 원하십니까?"
rows["184:1005133779"]="뭐?$b$b이 흥미진진한 발굴의 한가운데서, 저는 그런 것에 집중하는 것이 적절하지 않을까 확신하지 못합니다.$b$b그건 정말 짜증나는 이야기일 겁니다."
rows["184:1099269330"]="고대 경호가 돌아오고 있습니다. 센라리우스, 아비아나, 골드린... 그들의 존재를 느낄 수 있습니다. 우리는 그들을 이 세상에 데려오도록 해야 합니다. 그들의 적절한 도움이 필수적입니다."
rows["184:119228367"]="경보, 암호 조각을 전달하고 보관하는 절차가 있습니다."
rows["184:1225690820"]="주인님께서는 엑소다르의 소재에 관한 정보를 지키려고 엄청난 노력을 하셨다. 너 때문에 내부 첩자가 발각될 뻔했을 뿐만 아니라 우리 계획도 전부 엉망이 될 뻔했다는 걸 아나?"
rows["184:1256109235"]="짐블의 가게에서 아카인 리포저를 찾을 수 있습니다. 그리폰 마스터 바로 옆에 있는 티슬푸즈 아카네리$B$B그는 오래전부터 사라진 하이보른 엘프들 중 하나이지만, 그는 당신을 옳게 할 것입니다."
rows["184:1263212795"]="할머니, 그는 마하르가 나를 사랑하고 존경하고 신뢰한다고 말해주고..."
