rows["184:1677770612"]="용감하지만, 무지하기 짝이 없는 이 바보 둘은 서로 경멸하면서도, 너는 영웅이라고 말했다. 너희에게는 어느 한편에 설 의지가 없는 듯한데... 선택할 기회를 더 주어 보겠다."
rows["184:1694634492"]="감사합니다! $B$B현지의 영인 후이, 우리는 그의 악성 스프리트를 쫓기 위해 모험가를 고용했다는 것에 화가 났어요. $B$B그가 화가 났다는 걸 이해하지만 이 공격은 너무 멀리 간다!"
