rows["184:1901158222"]="하루 한 번만 모아서 처리할 수 있다는 걸 기억해줘요. 그 외에도, 우리는 항상 더 많은 크리스탈을 찾고 있습니다."
rows["184:1925176832"]="리치 왕은 우리 힘에 떨어질 것이고, 우리는 마지막 복수를 받을 것입니다.$B$B하지만 먼저, 스카렛 공격으로 알려진 전염병이 한 번이나 영원히 끝나도록 하겠습니다!"
rows["184:1935681382"]="판드랄, 언제나 이 말을 명심해라. 비탄에 빠져 신념이 흔들리지 않도록 해라. 만일 그렇게 된다면 네가 가는 곳마다 어둠이 깔리게 될 것이다, 나이트 엘프여. 그릇된 복수심으로는 결코 죄를 사할 수 없다."
rows["184:2000938390"]="버밀리온 리도브트는 트와일라이트 하이랜드에서 우리의 기지입니다.$B$B이 기둥에서 우리는 그림 배톨에 대한 공격과 아래의 강 계곡의 청소를 감시할 수 있습니다."
rows["184:2009717436"]="내가 할 수 있다면 너를 훈련시킬 거야, 하지만 넌 내게 너무 많잖아. 내가 뭐 할 줄 알아. 썬더 블러프의 중부 고원 북서부 상점의 타우렌 우나와 얘기해봐. 그녀는 진짜 재능이 있다."
rows["184:2097451528"]="영웅들이 영광스러운 결승에 도달했습니다. 당신은 좋은 정신을 가지고 있다고 가정합니다. 마지막 전투를 준비하고 있습니다."
rows["184:274473252"]="내가 빚진게 이해해요 필요하면 갚을 수 있어요$b$b이 돈이 필요해 숙소가 무너지고 있어 내가 수리비를 안하면 일과 집을 잃게 될 거야"
rows["184:277659198"]="이 약물은 제가 만들 때마다 더 적은 피해를 치유하는 것 같습니다. 비록 제가 같은 재료들을 사용하더라도. 한 가지 결론만 있을 수 있습니다. 식물들이 변화하고 있습니다. 저는 왜, 어떤 형태로 변하는지 말할 수 없습니다."
rows["184:288581913"]="왕의 관중실에서, 핫셰임 여인이 당신을 도와 아라티 계곡으로 데려갈 수 있습니다."
rows["184:302358212"]="북쪽은 여전히 죽은 자들의 냄새가 나고 있습니다. 우리 고향은 파괴되어 있습니다. 판다리아는 우리의 증오와 의심을  ⁇ 니다. 이 세상에는 다시 불타는 군단이 우리 해안에 착륙할 때 어떤 희망이 있습니까?"
rows["184:368804450"]="왜 순례자의 상을 축하하는 거냐는 건 누가 알 수 있겠지?$B$B감자파티, 독성성 전염병... 우리가 무엇을 요리하는지는 정말 중요하지요?"
rows["184:541664702"]="A 탭을 B 슬롯에 넣으면 당연히 BOOM가 될 것입니다. 여기, 제가 가지고 있는 것을 보여드리겠습니다. 그리고 나서 리얼리아मला 어떻게 그것을 함께 배치하는지 물어볼 수 있습니다."
rows["184:59802129"]="Twilight 신조들 중에는 우리를 위협하는 마법사들이 있습니다.$B$B우리는 그들의 존재를 우리 집에서 지우려는 모든 욕구를 가지고 있습니다.$B$B우리는 분열되어 있고, 그래서 우리는 할 수 없습니다.$B$B그래서 저는...$B$B그리고 기다려..."
rows["184:623362506"]="얼마나 매력적 인 것 같았어요. 당신은 병리처럼 보이지만 지금은 진실을 알았습니다. 당신의 사람들은 끔찍한 어둠의 무게 아래 고통 받고 있습니다."
rows["184:638029165"]="로얄 약학회도 바보들을 참을 수 없습니다. 아마 다음번에 당신과 내가 말에 대해 이야기 할 때, 당신은 언더시티의 친구로 간주 될 것입니다."
rows["184:654486827"]="실패했어, 난 이 세상을 실패했어$b$b지상의 반지는 내 리더십에 대한 믿음을 잃었고, 나의 약점은 아제로스... 잊혀질 것..."
rows["184:749961422"]="우리가 고향이라고 부르는 곳의 많은 부분을 잃는 것은 부끄러운 일이지만 스컬지!"
rows["184:792791992"]="더 나은 어린아이가 영들의 인도를 따라야 한다 썬더 블러프서로서로 배울 수 있을지도 몰라"
rows["184:799543968"]="네가 나를 이길 수 있었으면 영광이 없었을지? 칼림도어 난 기대에 지각이 너무 많아요 곧 먼지가 될 거예요"
rows["184:802912533"]="로켄?! 이거 정말 귀찮아졌군... 무쇠 드워프는 무찌른 것 같습니다만, 아직 저 어딘가에 무쇠 브리쿨을 대량으로 뽑아내는 기계가 있나 봅니다!"
rows["184:883130432"]="저는 항상 실버파인을 사랑했습니다. 리치 왕 그의 분노를 풀어주소서 스컬지 군대를 내쫓고 땅이 거대한 부패한 시체 굴로 변했습니다."
rows["184:897650585"]="그럼 우리 는 역사 에 대한 지식 을 시험 해 보겠습니다. 수쿠부스 악마 들 은 고통 을 유발 하는 데 즐거워 하고, 악몽적 인 조사를 실시 함 으로 레지옹 의 봉사 를 합니다."
rows["184:90549578"]="난 네가 처한 곤경에 도움이 되고 싶지만, 파란 드래곤 비행은 엉망이고,"
rows["184:916305950"]="이제 프로스트울프 장군이 패배한 후 윈터엑스 포지션 입구를 지키기 위해 몇 군대를 구비할 수 있습니다.$B$B하지만 조심해야 합니다. 호드 침입자"
rows["184:925009192"]="보고서를 안전하게 보관해 $p태양보행자들은 서쪽으로 이동하고 있습니다.$b$b난 여기 남아서 이 사람들을 도와줄게 네가 남아서 우리를 도울 수 있다면 더 좋은 기회가 있을 거야"
rows["184:949879989"]="네더가르드 포항에서 네더워치 코맨더 네더웨네에게 이 메시지를 전달해 주세요."
rows["184:978653639"]="나갈라는 유명한 제브라  ⁇ 을 기다리고 있을 겁니다. 그녀는 내가 채소를 줄이고 더 많이 먹어야 한다고 말하지만, 나는 그렇게 많은 체중을 얻었다고 생각하지 않아요."
rows["185:1092717363"]="공원에서 걸을 거리가 될 거야 그 공중장기가 갑자기  ⁇ 의 군대를 데리고 나오기 전까진$B$B이 끔찍한 놈들이 우리를 한 번이나 더 이상 여기로 데려다준다면 갈리위크스가 내 머리를 잡아먹을 거야"
rows["185:1165635207"]="모든 사람들이 그 미친 브루페스트 레이싱 양들을 사랑해요 더 알고 싶으세요?"
rows["185:1166576263"]="호드 노예는 마주치는 대로 자유롭게 해 주어라. 티라누스와 싸울 때 그들의 도움이 반드시 필요하다. 나는 지원병력을 모아 채석장 반대편에서 합류하겠다."
rows["185:1232197870"]="우리 의 타락 한 형제 자매 들 을 겸손 히 빛 에 맡겨 주옵소서 이 생활 에서 당신 은 그 들 을 사랑 으로 포용 하셨으며, 이제 모든 악 에서 그들을 구하고 영원 한 휴식 에 들어갈 것을 명령 하십시오."
rows["185:1273122695"]="호드의 일원으로서 우리 지역사회가 계속 번영할 수 있도록 기여해야 합니다. 따라서, 저는 여러분께 제가 맡고 있는 작은 일을 기꺼이 수행함으로써 우리를 도울 것이라고 확신합니다."
rows["185:1302439631"]="전날 레그누스 썬더그라나이트가 총기 공장에서 새로운 트로피를 자랑하는 것을 들었어요."
rows["185:1408513821"]="제가 라인에게 15개의 매머스 줄기를 주면, 그는 제게  ⁇  칼로 사용할 수 있는 다리를 주죠. 어떻게 하겠습니까?"
rows["185:1428119653"]="정말 그렇군요. 타렌 제분소와 남녘해안의 친선을 상징하는데 두 마을의 중간에 이 탑을 세우는 것보다 더 좋은 방법이 어디 있겠습니까! 훌륭합니다!"
rows["185:1440840985"]="고엘은 부모를 알지 못했고 몇 년 전만 해도 자기 가족을 찾았지"
rows["185:1500658801"]="|TInterface\\Icons\\spell_nature_unrelentingstorm.blp:20|t |cFFFF0000|Hspell:135682|h[남부 운행]|h|r는 타오르고 |cFFFF0000|Hspell:137176|h[ 과중 전동 ]|h|r를 일으켰습니다!"
rows["185:1524556207"]="부의 획득이 더 이상 우리 삶의 동력이라고 할 수는 없지만, 우리는 돈이 세상을 돌아게 한다는 것을 알고 있습니다."
rows["185:1526257085"]="이 공연에서 나보다 더 잘하고 싶으세요. 저보다 더 많은 경험을 가진 사람이 필요합니다. 저건 언더시티의 약국에서 일하는 죽은 죽은 Herbert Halsey 박사입니다."
rows["185:1533577951"]="저는 잃어버린 섬에 갇혀있었을 때 새로운 괴물 동맹국의 일을 목격했습니다. 하지만 이제 우리는 그들의 재능을 시험해 보겠습니다."
rows["185:1590914332"]="호젠 은 참으로 매우 활기찬 종족 이다. 짧은 기간 동안 살아가는데, 그 들 의 생일이 20 이 지나도 생존 하는 개종자 는 거의 없다. 그들의 지도자들은 모두 14 또는 15 입니다. 여러분 은 14 살 때 얼마나 성숙 한 사람 이었습니까? 그것에 대해 명심 하십시오!"
rows["185:1644463234"]="제 시간에 많은 것을 보았지만, 화스퍼 골치에서 탐험가들의 리그로 인한 변화는 케이크를 빼앗아갔습니다.$B$B피부가 손상되지 않은 채 빠져나온게 다행입니다!"
rows["185:1734872283"]="몇 년 동안, 명예 Hold은 지옥불 반도 의 공포 를 견디고 있습니다. 이제, 포털 사이트가 다시 열리고 아제로스에서 지원 스트림이 들어왔을 때, 아마도 이 피가 든 정착 상태는 끝납니다."
rows["185:1800113453"]="지금에도 빛과 어둠의 힘들 사이의 진정한 전투가 다가오고 있습니다. 우리는 모두 연합하도록 소집됩니다. 그리고 이 갈등을 직면해면 모든 필사적 고통은 무의미합니다."
rows["185:1827391412"]="보스, 내가 생각했는데 치 치에 대해 잘했어 그래서 농장에 양을 줄게 했잖아"
rows["185:1827696518"]="아직 완전히 이해되지 않은 신비에 빠져들지 않는 것이 좋을지도 모릅니다. 어쩌면 당신은 완화 장치를 비켜야 할지도 모릅니다. 제 동료들과 저는 우리 스스로 처리할 수 있습니다. 나는 확신합니다. 우리는 괜찮을 것입니다."
rows["185:1849980230"]="여기 낚시할 수 있는 몇 곳만 있어. 팩스턴은 다 알고 있고, 아마 몇 곳도 알려주지 않을 것 같네요."
rows["185:1908185003"]="그래서 제가 알아차릴게요, 당신은 이 용암 용암으로 수영을 하고 있었고, 이 용암 용암 용암으로 돌아다니고 있었나요? "
rows["185:1948257607"]="저는 시드키퍼 싱 싱과 함께 농작물, 채취 및 저장에 대한 보다 효율적인 방법을 개발하고 있습니다. 맛있고 신선하고 고품질의 제품을 제공하는 것이 Tillers의 목표입니다!"
rows["185:1970460304"]="스톰윈드 카운팅 하우스는 스톰윈드돈 계산이 지쳤을 때 골든드 로즈에서 술 한 잔 마시지 마"
rows["185:20313870"]="트윈 스파이어 루인스는 아직 안전하지 않아 전투 기준은 두 개의 신호등이 불면이 안전할 때만 발급해야 합니다"
rows["185:2070241513"]=" ⁇ 칸의 이야기는 슬픈 이야기인 것 같아요. 전 제 배의 선장이었죠.$b$b한 번 더 하락하면 다시  ⁇ 이 될 거야"
rows["185:223163120"]="조심하십시오, 아분. 저와 거래를 하는 스토나드의 상인이 말하길 그녀가 어떤 끔찍한 질병을 완성하려고 부단히 노력하고 있다고 합니다. 그들은 그 질병이 드레나이를 상대로 대단한 성과를 거둘 거라고 했습니다!"
rows["185:268201860"]="그쪽 신호를 들어보니 우리가 당신을... 우리가 추락한 큰 섬의 남동쪽 부분으로... 암멘 여울을 건너... 크쉬쉬쉬크 지지지트... 미안하오. 너무 많은..."
rows["185:281071520"]="미안해, 친구, 하지만 내가 생각보다 더 바쁘다.$b$b이 지역에서 지휘관의 발견을 기록하도록 지명받았습니다.$b$b그들은 분명 가장 심오한 것입니다!"
rows["185:323846364"]="하지만, 우리의 새로운 동맹국들은 뒤틀린 황천 새로운 힘의 출처와 우리 마술의 무한한 숙달을 약속해 주며 아즈하라 여인이 당신을 믿는 것처럼 "
rows["185:333692027"]="아쉽게도 용감하고 용감한 모험가 여러분, 여러분의 개입이 끝났습니다. 당신 뒤에 있는 터널에서 뼈와 철의  ⁇ 음이 올라오는 것을 들리십니까?"
rows["185:418719758"]="내 아웃랜드우리 군대는 호드 폭풍의 눈을 통제하는 것은 위험합니다. 아래의 격렬한 에너지들 사이에서 싸우고 있습니다."
rows["185:451788762"]="흙을 파는 것이 즐거워하는 취미라면, 파스트라이더스 스퀘어에 있는 벨리랑 함께 미친 짓을 하거라."
rows["185:458353304"]="|TInterface\\Icons\\spell_nature_unrelentingstorm.blp:20|t |cFFFF0000|Hspell:135680|h[북도 운행]|h|r가 불타서 |cFFFF0000|Hspell:137176|h[ 과부하 회로]|h|r를 일으켰다!"
rows["185:509070852"]="상처들을 치료할 치료사가 없을 때, 초급의 지식이 생명을 구할 수 있습니다."
rows["185:633168347"]="여기 웨더 그린텀 (Weeder Greenthumb) 의 유해가 있습니다. 워커 장의 드루이드 동반자 중 한 명입니다."
rows["185:678222075"]="제 삶 과 정신 은 참을 수 없는 호드 일 들 의 기억 들 로 가득 차 있다. 슬픔, 절망, 희생 의 시간 들 은 지나갔다. 전쟁 의 분노 는 결코 내 마음 을 떠나지 않을 수 없었다!"
rows["185:800201195"]="네, 꽤 많이 배웠던 것 같네요. 인상적이지만... 제 연습생이 되고 싶은 사람들이 몇 명인지 아세요?"
rows["185:81733833"]="나그란드를 지나 숲으로 오기 전까지 저는 우리의 원래 문화가 너무 많이 사라졌다고 두려워했습니다. 제가 틀렸다는 것을 알기에 감사합니다.$B$B할 일이 너무 많아요!"
rows["185:840405313"]="그것은 정해져 있나니 나는 권능의 대우를 명령하노니 칼림도어군인들이 이것을 이해하고 사실로 받아들이는 것을 확신하라 이미 많은 피가 흘리고 있어 우리 분단들 사이에"
rows["185:847562942"]="내가 내 부하에게 짐승의 귀를 보여주며 짐승의 죽음을 내 것으로 주장하고, 결국 내가 죽였는데, 그 후에 가난한 기사에게 그의 가족을 돕기 위해 보상을 제공했을 것이다."
rows["185:877749023"]="그 이방인은 이름이 없어, 제 아버님께서 전설의 영웅에게 줄 이름으로 남겨둔 \"요르그\"라고 정하셨습니다. 몇 년이 지난 지금 그분은 서릿결 부족의 왕이신 요르그 스톰하트로서 우리를 이끌고 계십니다."
rows["185:937968692"]="저는 종종 분노의 발작에 시달리고 있었습니다. 하지만 드리즈를 만난 이후로 행복하고 생산적인 삶을 살 수 있었습니다.$B$B그리고 저는 맨손으로 물건을 찢어 버릴 수 있습니다."
rows["185:962398257"]="우리는 방금 천안 수도원에서 졸업했습니다.$b$b우린 더 이상 학생이 아니라 첫 번째 탐구에서 숨겨진 마스터를 찾아가고 있습니다."
rows["186:1044504048"]="네, 베르텔름, 내가 네 모자를 다쳤어 가장 크고 붓고 멋진 깃털을 사용했어"
rows["186:1116705993"]="<켈스웨아는 당신과 눈을 마주치지 않습니다.>$B$B난 전투 중 탈출했지만, 모든 정식 동물들을 해방시키는 데는 한 번도 안 갔어$B$B내 곁에 둘 수 없었어요, 담배로 흩어져..."
rows["186:1120044851"]="우리의 목표는 모그를 없애는 것이지만, 우리는 우리 편을 무시할 수 없습니다.$b$b호드과 사우로크 모두 우리 옆에 있는 모구를 공격할 때, 어느 순간도 우리를 공격할 수 있습니다."
rows["186:1139480525"]="오드리 버네프와 얘기해 스톰윈드 시티, 그 곳의 경비원이라면 그녀를 찾아갈 수 있는 방향을 알려줄 수 있을 겁니다.$b$b성전 내부에 스톰윈드의 포털을 찾을 수 있습니다."
rows["186:1225668514"]="오늘 대회에서 승자가 다 됐지만, 장은 당신이 잡은 모든 맛있는 물고기를 사려고 합니다!\010어업 실력을 보여줄 수 있는 다음 일요일은 항상 있어요!"
rows["186:1252409583"]="반나르 스톰파이크는 알테락에 있는 얼라이언스 군대의 장군이며,  ⁇  발다르에서 그의 군대를 지휘한다.$B$B만약 그가 패배한다면 얼라이언스은 확실히 알터랙의 전투를 잃게 될 것입니다."
rows["186:1255279103"]="내게 충성을 맹세하라 (주님께서는 원하시니, 보고 원하시니, 굶주리니) 그리고 당신은 내 형상대로 다시 창조될 것이다. (잠깐! 불신자! 우리 가운데의 이방인!) 침입자! 너! 자신을 보여주..."
rows["186:1290249722"]="보아라, 필사자여, 너의 멸망의 도구에... ..가 ⁇ 은 피로 만들어져 있다."
rows["186:1323896168"]="<네르타라쿠가 주둥이를 숙이고 있다>$B$B카리나쿠는 드래곤마우 요새 위에 갇혀 있어 난 그녀를 풀어주려고 여러 번 시도해봤어\010"
rows["186:1330163966"]="더 이상 훈련이 없어 동쪽으로 멘더스 스텝으로 가세요."
rows["186:1344183254"]="내가 원하는 게 아니라 맹세를 이행해달라고 부탁했어 호드.$b$b우린 전쟁에 있습니다. $p잊었으면$b$b그러한 때, 의무는 개인적 이익이 두 번째로 중요하게 여겨져야 합니다."
rows["186:1398280655"]="내가 이미 많은 것을 배웠습니다. 당신이 행동하는 걸 보고만요. 당신은 젊음의 열기로 싸우고 있지만, 노인 참전용사의 경험으로 싸우고 있습니다."
rows["186:1495448099"]="이번 마상시합은 분명하게 드러나진 않을지 몰라도 강하고 단합된 군대를 구성하는 데 도움을 주고 있답니다. 우리가 준비되면 은빛십자군과 용사들 모두의 주의가 얼음왕관 쪽으로 바뀔 겁니다."
rows["186:1719706941"]="그리고 그는 그것을 발견했다. 서둘러 종파의 순위를 통과한 후, 리치 왕 자신은 라스 불멸을 부여했다. 그렇게 라스 프로스트비스퍼, 리치가 태어났다.$B$B이제 이해가 되겠나?"
rows["186:1798583924"]="제가 이 곳에서 계속 활동할 수 있게 된 것은 좋은 일입니다. 저는 적어도 환영을 지나지 않기를 바랍니다."
rows["186:1866544631"]="우린 조각들을 모으기 시작했어, 챔피언. 모고들이 만들어져 타이탄 주인들을 위해 골짜기를 지키러 보내졌어."
rows["186:1922139171"]="바람과 공기 요소는 파괴를 위협합니다 썬더 블러프만약 당신이 거기에 들어갈 만큼 강하다고 생각한다면, 내 게을리 해. 그렇지 않으면, 도시에서 벗어나서 우리가 처리해 줄 수 있다."
rows["186:2085377101"]="여러분 이 이해 해야 할 것 은, 10,000 년 의 존재 를  ⁇  수 있게 해 주는 것 이 저에게 인생 에 대한 상당히 독특한 관점 을 주었다는 것 입니다. 현재 여러분 의 시험 과 고난 은 의미 없는 것 입니다."
rows["186:2099530428"]="무덤 에서 나가기 위해 나 는 생각 했 다. 가족 들 은 저를 환영 할 것 이라고 생각 했 다. 그 대신, 그 들 은 나 는 더 이상 이해 하지 못하는 언어로 외치며 마을 에서 쫓아 나갔습니다."
rows["186:2118727218"]="이 피부는 아직 작동할 준비가 되지 않았는데, 피부를 만드는 데 시간이 오래 걸리지 않았으면 좋겠어요. 이런 기다림은 어떻게든 줄일 수 있을 겁니다. 그건 건강에 좋지 않을 겁니다."
rows["186:214332903"]="큰 강이 우리 모두를 흐르며 어떤 사람들은 물의 길을 따라 항복하고 다른 사람들은 특정 해안으로 수영한다.$B$B넌 낯선 사람이야 강이 어디로 데려가나?"
rows["186:249661577"]="그렘록은 항상 요리하는 데 행운을 가지지 않지만 배울만한 맛있는 요리법이 있습니다."
rows["186:33003753"]="아니, 여기 마법사가 없다고 생각하진 않나 엘윈 숲루칸라는 남자가 있는데 스톰윈드 하지만, 그 분에게 물어봐도 돼요."
rows["186:354393794"]="서적 제작자, 잉크와 베를루를 찾고 있을 것 같네요.$B$B지도에 위치를 표시해 줄게요"
rows["186:396143225"]="나보다 훨씬 더 좋은 수강수입니다. 하지만 내가 말한 것을 누구에게도 말한다면 부인할 것입니다. 당신은 테룸 디프포르지와 이야기해야합니다."
rows["186:628040869"]="이 작은 집 안에 갇혀서 도시 벽 밖에서 벌어지는 전투에 참여하는 꿈을 꾸고 있지만 의무는 지금 내 대신 싸우는 다른 사람들과 지식을 공유하도록 강요합니다."
rows["186:662195826"]="낯선 사람, 서둘러 레이디 제인 프라우드무어와 연락하십시오. 그녀의 작은 얼라이언스 세력은 용감하게 불타는 군단의 초기 공격을 완화하고 아치몬드의 접근을 늦추려고 노력하고 있습니다."
rows["186:672048315"]="우리 아버지 시대 이전부터 활을 사용했지. 그들은 단단하고 확실하며 적들을 빨리 쓰러뜨리죠."
rows["186:700817365"]="제 임무는 하나뿐이고, 하나의 임무입니다. 서부 성당이 원활하게 운영되도록 하는 것입니다.$B$B내 분노를 용서해야 하지만, 보시다시피, 상황은 조금 통제가 안 되는 상황입니다."
rows["186:746437583"]="다들 진정해 이건 가로쉬의 함정 중 하나처럼 들리네요 그는 우리를 해변에서 끌어내려가고 있어요"
rows["186:750651774"]="이제 혼자서도 요새로 돌아갈 수 있소. 당신이 시간을 벌어 주었으니 여기서 몰래 빠져나갈 수 있을 거요. 뉘신지는 잘 모르겠지만 어쨌든 고맙소이다. 언제나 엘룬의 축복이 함께하기를!"
rows["186:772646366"]="이 판다레네들은 좋은 사람들처럼 보입니다.$b$b그들은 전쟁에 휘말려 싶지 않지만, 몇 주간 동안 호드를 다루고 나면,"
rows["186:827277030"]="농담이냐? 농담이냐? 아니면 내가 당신을 즐겁게 하기 위해 내가 badut이라고 생각하냐?"
rows["186:889130072"]="우리 사람들에게 헌신하고 가치 있는 모습을 증명할 때까지 할크스트라이더를 사지 않을 겁니다.$b\010피의 엘프들 가운데 너회가 높은 것으로 여겨지기 전까지는 돌아오지 마"
rows["186:892793008"]="달콤한 것을 찾는게?$B$B보통 바닥에서 돌아다니지만 가끔은  ⁇ 거리를 찾아서"
rows["186:90268251"]="마가사 그림토메를 이 곳에 갇혀있다는 건 이상하지 않나요?$B$B심지어 캐어린 블러드하프를 독살했다고 들었어요"
rows["186:91616340"]="얼라이언스의 방문 멤버들은 주로 남서쪽 달라란의 실버 앙클라브에 머물고 있다.$B$B그곳에는 숙소가 있고, 다양한 얼라이언스 도시와 전투장으로 가는 문도 있다."
rows["186:928857149"]="호드은 그들이 여기 행한 것에 대해 지불할 것입니다.$B$B이 혐오로부터 집중 아이리스를 되찾으면 가로쉬가 파괴의 진정한 의미를 알게 될 거야$B$B오그리마... 드로운이 될 것입니다."
rows["186:950208234"]="저는 항상 우리가 무언가를 시작하기 위해 영감을 기다리지 말아야 한다고 가르쳐야 한다고 생각합니다. 행동은 언제나 영감을 불러일으키죠.$B$B이것이 후진들의 길이라"
rows["186:983400010"]="만약 당신이 기일을 만들려고 한다면, 당신은 그것을 조ンド르 스틸브로우에 넘어서야 합니다. 아이언포지 방문객 센터, 남동쪽으로 아이언포지 그를 만나러"
rows["187:1020194935"]="우리 두 민족 모두 칼타스와 그의 에이전트들, 레이디 리아드린의 손에 큰 고통을 당했습니다."
rows["187:10422730"]="아직이다, 이미론. 널 위한 계획은 따로 있다. 너는 우트가드 첨탑에서 나를 계속 섬길 것이다. 만약 이 벌레들이 살아남아 다시 너를 찾는다면, 그땐 네 아내의 복수를 할 수 있겠지."
rows["187:10517065"]="어떤 사람들은 토끼발 형제가 나보다 더 운이 좋다고 주장합니다.$b$b이럴 때 웃는게$b$b그는 \"형\"이라 불리지만, 나 \"부러스\"라 불리지만,"
rows["187:1147749754"]="알도르 사제회는 성스러운 빛을 섬기며 용서와 구원의 가치를 소중하게 생각하지요. 하지만, 아무리 그들이라도 블러드 엘프들이 캘타스의 명령을 받던 시절에 저질렀던 잘못을 쉽게 잊을 수 없었습니다."
rows["187:1180775794"]="이 야크 들 은 일부 사람 들 에게는 벼룩 한 짐승 으로 여겨지고, 목축 과 소수 노동 에만 적합 하다. 이 생물 들 - 흑고슴 의 후손 - 이 참으로 가지고 있는 타고난 아름다움 을 아는 사람 들 은 거의 없다."
rows["187:1440482514"]="네, 탈출구역에 갇힌 사람들이 많아요. 보스."
rows["187:1484460778"]="오래전, 여행 중에 한 남자가 제게 \"이기를 잘 사용하면 이걸 가질 수 있다\"고 말했다.$B$B그 때 몰랐고 지금도 몰라요"
rows["187:149062953"]="호드의 경우!\010우리 주변 상자에서 무장해 나가서 아그마르의 해머로 보고하라 호드 여정을 살아남기 위해서입니다.\010로카르 오가르!"
rows["187:1654716229"]="사령관, 당신은 재치가 좀 부족하군. 뭐, 별로 놀라운 사실이 아니야. 그래도, 호드에서 이번 일에 행동을 취할 거라는 말은 맞소이다. 하지만, 호드만은 아니오. 이미 아제로스 각지에서 온 영웅들이 도착했소."
rows["187:1747429101"]="틴버마우에 적대적이지 않은 사람은 공격에 대한 두려움 없이  ⁇ 을 통과할 수 있습니다"
rows["187:1788977645"]="난 람카헤흐의 나두누 왕자, 내 사람들은 톨'비르입니다.$B$B네퍼셋 사람들은 우리와 같은 사람들이고, 육신으로 만들어졌죠.$B$B죽음의 날개가 오기 전까지"
rows["187:1820659364"]="난 여기 어딘가에 있는 거 알아요!$B$B내 집은 라치트인데 제펠린이 여기 떨어졌는데, 연구하기 위해 왔던 걸 시작해야 한다고 생각했어요!"
rows["187:1852407269"]="겉으로는 잘 보이지 않을지 몰라도, 이 대회는 하나로 뭉친 강력한 전력을 만들어내고 있습니다. 준비가 끝나면 십자군과 모든 용사들의 시선은 얼음왕관을 향할 것입니다."
rows["187:1893815535"]="DEC 운영자는 또한 충전 팔에 자신을 충전하도록 선택할 수 있습니다.$B 디모시저 운전자가 멀리서 발사할 수 있게 해주는$B|TInterface\\Icons\\INV_Misc_EngGizmos_27.blp:32|t"
rows["187:1921427040"]="더 훌륭한 요리사가 없습니다 썬더 블러프 아스카 미스트런러보다 더 많은 것을 맛볼 수 있어\010더러운... 이제 난 배고프다."
rows["187:1921996013"]="준비가 된 것 같군. 명심해라. 이들은 끔찍한 역병에 걸렸고, 어차피 죽을 것이다. 스컬지의 손아귀에서 로데론을 지키려면 스트라솔름을 정화해야 한다. 가자."
rows["187:1941798245"]="대마녀 윌프레드 피즐뱅은 아직 대회 무대에 도착하지 않았기 때문에 다음 도전은 준비되지 않았습니다."
