rows["187:245195471"]="에코돔 미드림에 오신 것을 환영합니다 여행자. 그 괴물과 거래하는 것을 조심해야 합니다. 샤우리."
rows["187:346921282"]="브루페스트 경기장에 오신 것을 환영합니다. 경쟁하는 맥주공사들 간의 우호적인 경쟁을 축하하는 동안 많은 것을 즐길 수 있습니다. 질문이 있다면 알려주세요."
rows["187:421944084"]="내가 죽어야 한다면, 내 친구들이 옆에 있어 죽을 거야.$b$b내가 내 사람들을 복수하기 위해 최선을 다했다는 것을 알고 죽을 것이다.$b$b내 적의 부끄러운 얼굴에 직접 쳐다보고 죽을 거야"
rows["187:469249838"]="기둥! 기둥은 놀라운 사람들입니다. 멋진 것 입니다. 그리고 그들은 공학 예술에 대해 많은 지식을 가지고 있습니다. 당신은 아이언포지, 팅커타운으로 여행해야 합니다."
rows["187:489937093"]="모든 샤도파인은 서로 이름을 알고 함께 훈련하고 싸웠고 함께 살아남았어요$B$B당신 이 같은 말 할 수 있다면 우리 형제 자매 로 가입 할 준비가 되어 있을 것 입니다."
rows["187:538458694"]="마음을 단단히 먹어라. 심판의 날이 머지않았다. 곧 세계의 파괴자가 약속을 지키러 돌아올 것이다. 곧 존재하는 모든 것의 파괴가 시작된다!"
rows["187:555472225"]="현재 우리는 하이달 산 전투를 테스트하고 있습니다.$B$B카라잔을 하면서 얻은 명성은 이렇습니다."
rows["187:562551206"]="이리던의 하사들 중 가장 숙련된 사냥꾼들만이 내 상품에 접근할 수 있습니다.$B$B샤타르, 센리온 탐험과 알도르에 있는 신세가 높아지면 당신은 가치가 있다고 여겨질 것입니다."
rows["187:583744773"]="내 학생이 되기 전에 술조각에 대한 능력이 더 커야 합니다."
rows["187:666328074"]="방문객이 많지 않아$B$B배고프다? 나는 많은 맛있는 음식을 요리했다, 내 사랑.$B$B어기는 안 돼, 맛있는 건 못 잡으면 좋겠어"
rows["187:68847605"]="오늘, 내 가슴을 짓누르던 커다란 짐을 벗어 던졌소. 내 가슴은 자부심으로 충만하다오. 그리고 내 평생 처음으로 내가 누군지 떳떳하게 말할 수 있게 되었소이다. 마침내 가슴 속의 분노를 떨쳐버리게 되었단 말이오."
rows["187:695165576"]="<에라란은 죽음의 잡초를 씹고 있는 것 같다>$b$b사랑용 약물을 만들고 싶다면, 잘못된 곳에 있잖아. 맹인화, 마비, 살인하는 것은 내 일이고,"
rows["187:70114363"]="용사들이여, 도와줘서 고맙다. 이제 굴단의 호드는 굶주린 메뚜기떼처럼 이 세상을 휩쓸 것이다. 내가 계획한 모든 것들이 마침내 실현될 것이다."
rows["187:73720297"]="모든 삶은 하나의 끈이고 우리가 함께 짜는 도화물은 우리 세계의 이야기입니다. 판다렌의 선도들은 이 사실을 다른 사람들보다 더 잘 알고 있습니다. 이 도서관을 보세요!"
