rows["187:852187141"]="드렉타르는 얼스트울프 클랜의 군사적, 영적 지도자이며 얼스트울프 킵에서 형제들을 이끌고 있습니다.$B$B만약 그가 패배한다면 알테락의 호드 세력은 붕괴될 것입니다."
