rows["188:1293054817"]="이 유물 은 미생물 으로 남아 있는 것 처럼 보이지만, 흙 과 진흙 으로 덮여 있어 확실 히 알 수 없다. 그 유물 에는 본질적으로 마법 이 없는 것 처럼 보인다."
