rows["188:161784295"]="< 컨트롤러에 필요한 가속기 모듈을 공간 안에 배치하면 최종적으로 끌어당겨집니다. 모듈은 잠시 빛나고 장치가 활기를 불어넣으면서 전력이 소비됩니다.>"
rows["188:166699377"]="제 딸 리야리아는 제가 남은 하루를 성전 청소에 보내길 원했습니다.$b$b이 이상한 아름다운 땅으로 가는 포털을 통과하는 것만큼 살아있다고 느껴진 적이 없습니다."
rows["188:1674919819"]="내가 내 말을 높이 평가받은 자만을 위한 것이라 오그리마 오크스 종족을 찾아가서 우리한테 증명해줘요"
rows["188:1705415946"]="우리가 태양의 영역을 통제하고 있다면, 우리가 항구를 강화하지 못하면, 우리는 성공할 것입니다.$B$B우리는 $3238w 퍼센트로 목표에 도달했습니다."
rows["188:1770781669"]="위에서 불러들인 '모험가'라는 자들을 지원하는 일이 우리가 이곳에서 맡은 임무다. 우리는 그들이 섬 곳곳의 요충지를 방어하는 일을 돕고, 맡은 임무를 수행할 수 있도록 그들을 보호해야 한다."
rows["188:1805691052"]="두 마리의 드레네이들이 달의 성전 지하에 있는 마법소녀 엘리사 듀마스와 대화를 나누고 있습니다.$B$B그들은 어떻게 도와줄지 알 겁니다."
rows["188:1843487410"]="산호초가 파괴되고 있어 도로에서 이동할 때 조심하세요.$b$b아마 그들이 쉐도파인이 여기 없다는 걸 알아내서 우리를 공격하기로 결정하는 시간 문제일 겁니다"
rows["188:1867349911"]="저랑  ⁇ 니, 우리는 스리 라 마을 근처에 우리 승무원 몇 명을 씻어냈고, 달이 지은 바다에서 몇 달을 보낸 후 육지에서 걸어가기 위해 발가 부러져 있었습니다."
rows["188:2009735119"]="이 범죄는 해결되지 않을 수 없습니다. 숙소의 위치와 파괴의 폭력은 이 매우 섬세한 문제입니다."
rows["188:2060408615"]="이 공을 이용해 몇 분 안에 강력한 의식을 수행할 거야"
rows["188:2074658456"]="구루바시와 하카르가 죽었고, 제 동료 잔다라르가 고향으로 돌아왔어요.$b$b이제 저, 차발과 방말라의 다크스피어들이  ⁇ 루브를 지켜야 합니다."
rows["188:2077293060"]="필멸의 세계에서 과거의 삶과 욕망은 아무런 의미가 없다... 이제 주인님을 모시는 수행사제로서 무조건 충성하라! 가장 큰 영광은 주인님을 위해 죽는 것이다!"
rows["188:2080380605"]="네, 인정하는 게 싫지만, 훈련이 계속되려면 내 여동생에게 얘기해야 할거야. 아직은 그녀만큼은 모르겠어."
rows["188:2114463766"]="놀라서 포위 된 판다렌 노예들은 칸을 공격하려고 시도했지만, 그는 춤추는 사람처럼 그들의 공격을 가로막고 바람에 있는 바늘처럼 그들의 공격을 회피했기 때문에 실패했습니다."
rows["188:246919846"]="마주치는 얼라이언스 노예들을 모두 풀어 주세요. 티라누스와 싸우려면 그들의 도움이 꼭 필요하니까요. 나는 지원 병력을 모아 채석장 반대편에서 여러분과 합류하겠어요."
rows["188:325371291"]="포털 마지의 본질을 이해하기 위한 정신적인 면이 없다고 생각합니다.$B$B하지만, 내 뒤에 있는 크리스탈을 이용해 크리스탈송 숲의 다라란 아래의 유적으로 이동할 수 있습니다."
rows["188:329967666"]="난  ⁇ 다라르의 로아인  ⁇ 자라. 나는  ⁇ 다라르에서 이성적인 형태로 왔고, 내 백성들을 돕기 위해 왔어.$B$B난  ⁇ 다라리아 사람들을 도와준 사람들을 도와주고 있어요"
rows["188:44129756"]="스팀위들 전투 경기는 시작됐습니다. 아레나 조직원들이 가젯잔에서 아레나 팀 차터를 판매하고 있고, 나그란드와 블레이드즈 엣지 산맥의 아레나 밖에서도 있습니다."
rows["188:563282739"]="만약 당신이 전쟁의 주인 카드들을 다룬다면 더 큰 영웅적인 암흑달 카드를 받게 될 것입니다. 이 카드는 때때로 당신이 전투에 참여하는 동안 당신을 치유할 것입니다."
rows["188:660513398"]="사실 그녀는 통제에 집착하고 있었고, 그녀의 시대를 지나서 오랫동안 권력을 유지하기를 원했고, 그것을 달성하기 위해 우리의 영원한 순환을 희생하려고 했습니다."
rows["188:67530294"]="하지만 우리 모두가 그래야 하듯이 여러분도 견뎌야 합니다. 이런 어두운 시절에는 누구도 끈기의 미덕을 모르지 않습니다. 절망과 증오와 마주 대하여 우리는 믿음과 싸워나가자는 투지를 신실함으로 계속 이어가야 합니다."
rows["188:734128962"]="크라사랑에서 물고기가 미친듯이 물려요!$B$B난 여전히 바다에 있고, 큰 물고기를 흔들고 있지만 오늘 아침 낚시를 팔러 왔어요."
rows["188:753119490"]="대부분의 거머리들은 운이 좋은 걸 가지고 있어요.$b$b똥은 주머니에 있어, 행운이 많아요$b$b절대 어긋나지 않는 행운을 신뢰하지 말아요. 때로는 다른 사람에게는 그런 행운이 있습니다."
rows["188:776594491"]="헤메트가 바닥에 쏘는 동안  ⁇ 을 통해 총을 쏘지 않는 법을 배울 수 있다면 우리는 추락하지 않았을 겁니다!$B$B걱정마, 빨리 고쳐줄게"
rows["188:833396468"]="계산이 맞다면, 이 둥지를 때리면 그 문이 무너질 겁니다."
rows["188:897434854"]="막투르, 당신과 함께 여기 머물 수 있도록 허락해 줘서 고맙습니다. 장담하는데 우린 서로에게 배울 게 많을 겁니다. 그리고 난 동쪽의 잃어버린 드레나이에 대해 최대한 많은 정보를 얻고자 합니다."
rows["189:1009964508"]="오크들은 운이 좋네요... 워마트론은 드레드말 홀에서 머물게 해주고, 나머지 사람들은 현역으로 보내지죠."
rows["189:1017693934"]="네, 알을 잃었는지 알아요$B$B난 어떻게 알 수 있겠지?$B$B이 계란을 다시 한번 당신에게 맡겨주지만, 제발, 죄송합니다. 이번에는 더 잘 돌봐주세요."
rows["189:1084491477"]="여행객 여러분, 저는 카라잔의 열쇠를 가진 모든 사람을 마스터의 명예의 손님으로 여기도록 지시받았습니다."
rows["189:1091336333"]="이리던의 하사들 중 가장 숙련된 사냥꾼들만이 내 상품에 접근할 수 있습니다.$B$B샤타르, 센리온 원정과  ⁇ 이들이 있는 지위가 높아지면 당신은 가치가 있다고 여겨질 것입니다."
rows["189:1163527146"]="우리의 목표는 모그를 없애는 것이지만, 우리는 우리 편을 무시할 수 없습니다.$b$b얼라이언스과 사우로크 모두 우리 옆에 있는 모구를 공격할 때, 어느 순간도 우리를 공격할 수 있습니다."
rows["189:1206571416"]="우리는 스톰윈드에서 고원지대에 대한 기본 문을 열기로 약속했지만 Twilight의 요새로부터의 간섭은 우리의 노력을 방해합니다.$B$B저 사람들은 무슨 미친 짓이야?"
rows["189:1211050440"]="그런 마법은 나쁜 소식이야 그 그림리즈가 왜 썬더브루 디스틸리 밖에서 설 수 있는 지 모르겠어"
rows["189:1220050618"]="오늘은 그대들의 용맹뿐 아니라, 얼라이언스와 호드가 서로의 차이를 내려놓고 힘을 합친다면 리치 왕 자신조차 우리 앞을 막을 수 없다는 사실을 증명하는 날로 기억될 것입니다. ---"
rows["189:1271239457"]="스프링스파이드 피즈레거를 보고 싶으실 겁니다 기술공 도시  \010아이언포지의 문에서 동쪽으로 향하거나 폭발의 소리를 따라가십시오."
rows["189:1309020945"]="넌 나랑 네 종류가 아무 의미도 없어 멍청아, 중요한 건 주인의 뜻이야 이... 이 배수들은 사냥되고 죽여질거야"
rows["189:1377466660"]="얼음왕관에 있는 야만전사의 절벽 출신, 도살자 블라도프와 그의 매머드 왕발굽을 소개합니다! 우리의 도전자에게는 희망이 없군요! 피와 눈물이 강을 이루는 한판을 기대하십시오!"
rows["189:1402794175"]="치 지의 뱃속에서 많은 진주들을 찾을 수 없을 겁니다. 사실, 저는 유일한 사람이 아닐 수도 있다고 생각합니다.$b$b일반적으로 제 사람들은 치 지와 그의 가르침을 피합니다."
rows["189:1482518084"]="서쪽의 큰 벽을 지나가는 걸 보고 싶지만 라지쿠는 여기 있는 거대한 채소를 계속 쳐다보고 있습니다."
rows["189:1520945532"]="로모그가 우리를 습격했을 때 그는 라즈를 둘러싼 체인을 던지고 |cff71d5ff|Hspell:75543|h[ skullcracker]|h|r로 그를 때렸다! 다행히도 마지막 타격을 받기 전에 나는 멀리 떠났다!"
rows["189:1563305435"]="마네웨이버족은 다르나서스로 가는 길에서 자신의 직업을 연습합니다. 나디아 는 가죽 작업 에 있어서 탁월 한 교사 입니다."
rows["189:1720291282"]="이 남자를 깨우는 건 쉬운 일이 아니지, 내가 그를 때려 밧줄로 끌어내려고 했지, 내 몸을 그 곤그에 던져버렸어 아무것도 없었어! $B$B더 많은 아이디어가 있어요"
rows["189:1749444228"]="넌 못생긴 놈이야 하지만 싸움을 안하는 건 아냐$B$B제 부대 중 하나가 곧 발진할 준비가 되어 있어야 합니다."
rows["189:1772396022"]="보통은 직접적으로 얘기하는 것이 제 몫이 아니겠지만, 오히려 여러분께서는 미lady와 청문회를 찾으실 겁니다. 하지만 저는 여러분께 직접적으로 일을 맡겼습니다."
rows["189:1843416541"]="네스피라라는 첫 번째 고대인들과 싸움이 힘들었고, 우리 앞에 있는  ⁇ 오렉은 죽어가고 있습니다.$B$B고통의 울음을 느낄 수 있어 뭔가 생명력을 훔치고 있어"
rows["189:1852957877"]="내가 본 가장 큰 곤충이 실리시드 자생충 중 한 곳이나 둘 다였을지도 몰라"
rows["189:1968563884"]="한 아이가 저렇게 맹세합니다. 어느 날 상어와 여우가 겹쳐진 것을 봤다고요.$b$b바다에는 이상한 것들이 많지만 그건 정말 바보같아요"
rows["189:2061250641"]="워치프가 우리 사람들을 구해주고 우리가 얼라이언스에 도움을 주면 갈리위크스를 처리할 것을 약속했습니다.$B$B내 친구의 적은 내 적이지?"
rows["189:2097261417"]="그의 관심을 끌고, 그가 당신을 탑 근처에서 본다면, 당신은 그의 부당한 관심을 가질 것이라고 확신할 수 있습니다."
rows["189:2114901937"]="여러분들 모두가 여기 있는 것을 보고 기쁩니다. 올해 우리는 많은 비극을 겪었습니다."
rows["189:2116063412"]="리치 왕의 죽음으로, 많은 똑똑한 스컬지가 실업이 되었다. 그 '악마'들은 당신이 너무 섬세하게 표현했듯이 발키르라고 불립니다. 그들은 지금 내 지휘 아래 있습니다..."
rows["189:263398788"]="저는 두 가지 언어에 능통합니다. 다워비쉬, 고노미쉬 그리고 인간들의 매우 일반적인 언어입니다. 하지만 여러분들이 무슨 말을 하는지 전혀 모르겠어요!$B$B말하라, 내가 내 기어들 위에 있는 말을 들을 수 없다!"
rows["189:393911504"]="구루바시와 하카르가 죽었고, 제 동료 잔다라르가 고향으로 돌아왔어요.$b$b이제 저, 마위키와 방갈라의 다크스피어들이  ⁇ 루브를 지켜야 합니다."
rows["189:402220246"]="저는 제 말을 친절한 사람들에게만 제공합니다 오그리마 오크스 종족을 찾아가서 우리한테 증명해줘요"
rows["189:41239268"]="내가 팔고 있는 모든 상품을 봤어? 날 위해 티러스에게 호의를 얻어야 하지만 그렇게 하기 위해서는 이 땅을 여행하면서 더 많은 경험을 쌓아야 할 것이다."
rows["189:449645505"]="마리온 콜은 브릴 남동쪽 끝의 갈로우스 엣 타버너의 독서실에서"
rows["189:602125087"]="정확히요, 전 드레스를 덮고 있는 소화액의 잔여에 대해 몇 가지 테스트를 했습니다.\010<  ⁇ 길이 끊어질 것>\010내 껍질 칼은 어디에도 본 적 없어?"
rows["189:611251281"]="우린 아직 이 대륙에 작은 지지를 가지고 있지만, 인간은 영원히 우리를 물리칠 수 없습니다. 그러면 그들은 우리를 노예로 만들게 될 것입니다. 우리는 그들의 배신에 대해 그들의 거짓말 혀를 잘라내게 될 것입니다."
rows["189:644905987"]="노블레가든은 아제로스의 드루이드가 생명의 재탄생을 축하하는 시간입니다. 알은 출산의 상징이며 모든 사람을 영으로 끌어들일 수있는 훌륭한 방법입니다."
rows["189:699254948"]="희망의 콩그라 보아라! 사실 우리는 콩그라를 몇 세기 전에 콩그라로 대체했으나, 오래된 콩그라스는 꽤 작고 우리 민족에게 적절한 수준의 희망을 공급하지 못했습니다."
rows["189:732202754"]="지구인과 돌의 트로그 사이의 전쟁은 한동안 치열해왔지만, 지금 혼란 속에서,"
rows["189:811860086"]="저들이 날 쏴버리면 스컬지 우리는 정착민들이 새로운 삶을 시작하기 위해 모든 것을 포기했습니다 노스렌드.$B$B우린 손과 손톱으로 싸워야 한다고 믿으면 좋겠어"
rows["189:929226720"]="아, 제대로 된 전투장의 냄새가 난다. 우리는 너무 오랫동안 혼자였어. 이제 호드의 전력은 풀려났습니다! 그리고 다음 타격이 떨어질 곳을 지시하는 사람들은 우리입니다."
rows["189:966784970"]="펠 크리스탈 포크를 사용하여 당신의  ⁇ 은  ⁇ 은  ⁇ 을 동물의 불안정한  ⁇ 으로 변형시킬 수 있습니다. 이  ⁇ 은  ⁇ 을 더 민첩하고 강하고 더 심하게 만듭니다.$B$B아래에서 선택해"
rows["189:974388895"]="헬스크림의 아들 가로쉬여, 그대의 아버지는 우리의 가장 위대한 영웅으로 살다 가셨소. 그대의 아버지가 어떤 희생으로 우리를 악마의 손아귀에서 풀어 주었는지, 그대에게 보여 주는 영광을 허락해 주시오."
