rows["18:999872578"]="유감스러운 존재들"
rows["190:1012984322"]="이제 네 주인이네 새 왕이 오래살아!$B$B크레그는 고르도크 호크를 봐주게 하고 고르도크 호크가 제일 좋아하고 고르도크 호크가 제일 좋아"
rows["190:1023489850"]="그 똥은 지금처럼 우리에게 왔어$B$B우리는 그들을 공감했고, 이 땅에서 어떻게 살아남을 수 있는지 가르쳐 주었습니다.$B$B시간이 지나면서 그들은 더 강하고 용감해졌고 이 땅을 차지하기 시작했습니다."
rows["190:1032755828"]="우리는 모두 레븐의 지휘 아래 벽을 지나가는 여행에서 봉사했습니다. 수많은 마티드와 야롱들을 상대로 칼을 정밀히 사용했습니다. 이 모가들은 우리를 약하다고 생각하지만, 그 판단에 대한 오류는 그들에게 비싼 비용을 지불할 것입니다."
rows["190:1069449415"]="난 당신을 실망시키지 않을거야, 워치퍼 내가 할 수 있는 대로 지도하고 조언자들을 협의해 줄 거야"
rows["190:1077239751"]="아타스는 상상할 수 없는 힘을 당신에게 제공할 준비가 되어 있습니다. 스컬지포옹이"
rows["190:107923419"]="용서를 드리며, 제 마술을 통해 당신을 다시 테라모르로 보낼 수 없으니, 당신은 이 세상 모험가처럼 보이며,"
rows["190:1166439104"]="넌 모험을 원하는 사람처럼 생겼어 내가 트롤이 왔을 때 그런거 그만했지"
rows["190:1171637361"]="경호원들, 들어봐요! 우리는 괴로움의 고통을 바로 이교적인 바시르 악마들에게 전달할 준비가 되어 있습니다. 우리의 임무는 간단합니다.  "
rows["190:1253058391"]="<옛사람의 눈은 넓고 깊다.>$B$B<이 생명체는 천천히, 당신이 이해하지 못하는 언어로 말하고 있습니다. 기운이 척추에 달합니다. 당신은 공포와 혼란에 사로잡혀 있습니다.>"
rows["190:1291587280"]="몇 개의 작은 기름 샘플이 빈 잔과 함께 당신 앞에 앉아 있습니다. 잔은 아마도 5개의 샘플이 들어올 수 있을 것 같습니다.$b$b어떤 종류의 기름이 먼저 들어올까요?"
rows["190:1313857001"]="아타스 눈물이 필요해 다른 사람이 전쟁에 필요한 걸 가지고 있을 것 같네요"
rows["190:1346328021"]="저는 이 땅이 바로 젊은 두로탄이 십대에 불과했던 곳이라고 믿습니다. 그는 첫 번째 타블크를 죽였습니다. 아, 아직도 기억합니다."
rows["190:1383563614"]="야르, 대령이 보내준 건 우리가 제이드 숲에서 훔친 부품을 팔러$B$B원하시면 본토로 데려갈 수 있습니다."
rows["190:1425874361"]="이 생물들에 대해 더 많은 것을 알아내기란 쉽지 않았습니다. 제 친구와 그의 용병들을 고용한 사람이"
rows["190:1438442916"]="듀담 그레든은 오렌지 동굴에 있어 잠금집을 가르칠 수 있지만 아이언포지내 말 이해한다면"
rows["190:1446985920"]="세 장로를 처치하면 감시자 프레이야는 강화 효과를 상실합니다. 하지만, 프레이야 자신과 그녀의 소유물인 인장에도 영구적인 피해가 생길 가능성이 매우 큽니다."
rows["190:1456438988"]="여러분들의 몸은 모두 훌륭합니다. 이 클로로폼의 냄새를 맡으시면, 10 더 강한 시간 100 더 많은 시간..."
rows["190:1458448643"]="황제의 가장 소중한 재산을 가지고 있어... 샤오하오에게 호의를 구하고 싶다면, 천왕궁을 추격하려는 오든 영돌들을 몰아넣어 도와줄 수 있다."
rows["190:1473162818"]="우리의 명예는 짓밟혔다! 호드는 말도 안되는 주장을 하며 거짓으로 우리를 비난했다! 나는 정의를 원한다! 티리온 경, 나의 용사들이 그대의 기사를 대신하여 싸우게 하시오. 우리는 호드에 도전할 것이오!"
rows["190:1515186477"]="먼저, 모라는 보르송 족속이 이 트롤들을 산에서 우리를 공격하도록 유도한 것처럼 들리는 것을 알고 싶어할 것입니다. 그래서 그들은 잿빛 골짜기에도 공격을 할 것이라고 생각합니다."
rows["190:1553893904"]="이 뭉개는 내가 내 안에 불꽃을 심어왔지만, 그 생명력은 항상 내 것이 될 것이다."
rows["190:1648995307"]="여기 있는 내 친구 볼리우이프는 손잡이 무기를 사용하는 방법을 보여줄 수 있습니다. 아니면, 당신이 원한다면, 일리니아 문파이어 (일리니아 월파이어) 는 다르나서스의 전사 테라스에서 밤 elf 무기의 마스터입니다."
rows["190:1701476465"]="볼진은 딱딱한 괴짜이고 목에 칼을 찔러서 돈을 벌기 위해 돌아왔어요$b$b내 사람들은 안전과 이익을 필요로 하니까"
rows["190:1894720060"]="아, 하지만 우리 주인 영토를 침입하는 것은 당신입니다. 그는 그 범죄만으로도 당신을 순식간에 멸할 수 있습니다."
rows["190:1964857726"]="우리 핏빛안개 척후병들이 우리 정보원의 위치를 파악했다. 그 멍청이 벨렌은 곧 무방비 상태가 될 것이다. 우리가 습격하기에 충분한 시간이지! 이제, 네놈을 없애 버리기 전에 눈앞에서 사라져라..."
rows["190:2009460148"]="난 그들이 어떻게 되었는지 모르겠어$b$b포로가 끊임없이 몰려들었습니다. 호드 그리고 얼라이언스모두 겨우 살아있어요$b$b배포된 격포를 넘어 끌려갔을 거야 아니면 죽었어"
rows["190:238200930"]="막대기 때문에 왔어?$B$B잠깐! 당신은 그냥 내 쓰레기 덩어리를 내기 위해 노력하고 있습니까?"
rows["190:270398738"]="당신의 도움이 귀중했습니다.$B$B저는 여러분께 장담할 수 있습니다. Cenarion expedition는 이리단으로부터 하늘에서 떨어지는 유독한 크리스탈을 방지하기 위해 모든 노력을 할 것입니다."
rows["190:288310353"]="내가 물어보면, 수프와 소스가 준비하고 쓸 수 있게 해줘야지.$B$B우리 모두 갈색 빵이 되기 전에  ⁇ 을  ⁇ 고  ⁇ 을  ⁇ 는 게 새의 림입니다.$B$B내 말 이해가 되니?"
rows["190:314494793"]="이제 밸리에 한눈에 내려다보았으니 이 곳은 좀 익숙해졌다고 말해야지$B$B그런 것 같진 않지만 그 느낌을 떨쳐내지 못해요."
rows["190:440224247"]="올'보츠?! 그는 내 자신의 창조물입니다. 주머니 후, 그가 평화로 쉬게 해, 나는 더 오래 지속 가능한 동반자 필요했다.$b$b앰버가 그를 우리의 임무에 사용하기로 결정했으니, 그를 폭발시키지 말자!"
rows["190:578716637"]="갈반가르 대장 (Drek'Thar) 의 신뢰받는 도움으로 전투장의 남쪽 부분에서 있는 아이스블러드 가리소에서 호드군을 이끌고 있다.$B$B갈반가르 대장이 살해당했습니다"
rows["190:593112207"]="미셸 벨 의 침대에 있는 태도 는 놀라운 것 이다! 그 는 그 를 가르쳐 줄 수 없겠지만, 그 는 분명 히 적절한 초상급 을 가르쳐 줄 수 있을 것 이다. 현재 그녀는 라이온 프라이드 인 에 거주 하고 있다."
rows["190:597975774"]="트랄의 말이 진실이 되길 바랍니다. 호드 더 많은 거리는 몇 명의 고집도 지도자들과 노스렌드사람들은 가로쉬의 이름을 부르고 있다 적어도 지금은"
rows["190:609385490"]="흥미롭게도, 대부분의 조상들이 화재로 죽었습니다. 여러분들은 진보를 위해 큰 위험을 감수했습니다."
rows["190:615392246"]="호젠과 진우가 싸움을 늘리고 있다고 들었어요."
rows["190:700456909"]="당신은 훈련의 최고점에 점점 더 가까워지고 있습니다. 더 훌륭한 마법사가 되기 위해, 당신은 또 다른 강사를 찾아야 합니다. 그녀의 이름은 안노라입니다."
rows["190:744773660"]="비스턴의 스포드를 잊고 좋은 물건이 필요해 크릭셀과 얘기해줘"
rows["190:801680303"]="아이스크라운에서 카샤를 찾았어요. 그녀는 부상하고 죽어있었어요. 저는 그녀를 그림자보호로 데려다줬습니다."
rows["190:814226214"]="이쪽에 있는 선수는, 연쇄살인범, 대량학살자이자 몇 번이나 교수형을 선고받았던... 호르그렌 헬클리브입니다! 신사 숙녀 여러분... 돈을 걸어 주십시오!"
rows["190:817253493"]="타이진은 그녀의 이름이고, 당신은 그녀를 래저 힐의 동쪽에있는 바락 안에 찾을 것입니다. 그녀는 당신을 가르쳐 신들을 존중하십시오. 당신이 대가로 적절한 존중을 표시하는 것을 확인하십시오!"
rows["190:831754133"]="서적 제작자, 당신은 잉크와 베를루를 찾고 있을 것 같습니다.$B$B지도에 위치를 표시해 줄게요"
rows["190:876829659"]="제 동생이 순서에 가입하면, 그 순서의 안전을 위험에 빠뜨릴 수도 있고, 그 순서의 일정을 도와줄 수도 있고, 적응하고 배울 수 있는 능력에 대한 믿음을 가질 수도 있습니다."
rows["190:929498448"]="여기서 일이 흥미롭게 되는데, 내 계획은 산벽을 따라서 왼쪽으로 지는 겁니다. 그렇게 되면 우리는 정글에 길을 잃지 않고 적들을 줄일 수 있을 겁니다."
rows["190:942387118"]="수많은 해 동안, 그리고 많은 세계의 얼굴에서, 드레네이는 더 나은 포용을 갈망했습니다 빛 그리고 어둠을 없애고 있습니다. 우리 스크라이어 형제들도 그런 야망을 가지고 있습니다."
rows["190:983697046"]="우린 공통점이 많아요, 밤 elf. 어쩌면 운명이 우리를 하나로 묶은 것 같다고 느끼지 않을 수 없습니다. 내가 도와줄게, 카우런. 내 사람들이 도와줄게. 우리는 잘못을 바로잡을 것입니다."
rows["191:1069166536"]="몇 년마다 돌아왔는데 모래 속에 숨겨진 신비로운 도시, 끝없는 잔디밭에 사는 유목민, 얼음 아래 거대한 제국, 그리고 금으로 황금화된 마법 왕국에 대한 이야기들을 들려주었습니다."
rows["191:1163440425"]="영웅들, 저 진짜 호거라는 걸 알 수 있어. 제 눈은 그의 벨트에 매달리고 있습니다. 여기 일어난 일들의 영향은 정말 어두운 것입니다."
rows["191:1272234179"]="배신자는 가장 예측 가능한 적이 아니었지, 에스차크. 하지만 나는 두려워하지 않는다. 우리 편에 있는 빛로 우리는 오늘, 내일 또는 그가 공격할 때 그의 세력을 물리칠 것이다."
rows["191:1309606922"]="스 ⁇ 블레이드 사우로크에서 발생한 질병과 전염병을 치료하기 위해 왔습니다.$b$b그들의 병은 제가 익숙한 병과는 다른 병이지만, 몇 가지 유사점이 있습니다."
rows["191:1312274209"]="예티는 거칠고 현명한 생물이고, 이 동물은 그 종류 중 가장 강한 동물 중 하나입니다. 우리는 식물의 허브를 통해 그를 잠에 빠지게 합니다.$b$b하지만 링에서 침착하게 될 것 같진 않아요."
rows["191:1330260729"]="20년 동안 이 지옥의 구멍에 갇혀있었지, 그 망할 포털을 뚫고 소리치지 않고 도망치기 위해\010"
rows["191:1385622757"]="아라코아는 귀신적인 시선을 가지고 당신을 선호하고 당신을 바라보고 당신을 통해 보는 것을 대조합니다.$B$B우리의 노력은 우리가 막으려고 노력했던 것보다 더 큰 혐오를 일으켰습니다."
rows["191:1444319901"]="네 재능이 내보다 더 많다는 걸 알려줘서 기쁘다 이제 떠나라 썬더 블러프그녀는 매우 숙련된 여자입니다."
rows["191:1493491223"]="꽃과 씨앗 등? 그건 레이나 스톤브랑치의 전문 분야일 겁니다. 그레이트 포지의 남쪽에 있는 아이언포지 의 의사에서 식물을 돌보는 것을 볼 수 있습니다."
rows["191:1625634053"]="난 바쁜 거 때문에 시간을 낭비하지 못해 사냥꾼으로 일을 찾고 있다면 동쪽 강변에 있는 디크티나와 이야기해봐"
rows["191:1639471101"]="내가 말하는 모든 말을 기억하고 기억하라 우리의 적들이 근절될 때까지 우리는 결코 지식을 더 발전시킬 기회를 놓치지 말아야 한다"
rows["191:1707849532"]="전투는 잘 진행되고, 스컬지 세력은 약해졌다고 보이죠. 저는 그들을 해안에서 쫓아내는 데는 단지 시간 문제일 것이라고 믿습니다."
rows["191:1779385263"]="아마 타그누스가 카라노스에서  ⁇ 을 때리는 소리를 들을 수 있겠지만 최근에 귀에서  ⁇ 을 벗기지 않았다면"
rows["191:1781979431"]="우리는 선택의 여지가 없습니다. 우리가 호드의 명예를 높이지 못하면 그들은 분명 우리를 근처 스토나드에 처박을 테니까요! 당신과 당신의 친구들조차도 그들을 못 막을 것 같아 걱정이 됩니다."
rows["191:182465143"]="우리의 전투장들을 빛의 보금자리에서 찾을 수 있습니다. 또한 이 세계에서 경기 경기장 전투 경로를 대표한다고 주장하는 돌봄자 브릴과 함께 머물고 있는 \"미글릭 블로스트롬\"이 있습니다."
rows["191:1906858706"]="주요 방어 위치에는 철 konstruktor 및 Storm Beacons이 포함되어 있으며 필요에 따라 추가 건설을 생성합니다."
rows["191:1938456620"]="내 친구, 집에 있는 친구들 모두와 함께 지내야 해$B$B네 우편 상자를 설치할 수 있는 목사가 있어"
rows["191:195327909"]="마법 예술의 훈련을 찾을 수 있을 겁니다. 아이언포지줄리 스톰케틀은 책에 코를 꽂아 있는 곳이죠."
rows["191:1956546206"]="아빠는 우리가 더 나쁜 일을 겪었다고 하지만 \"우리\"라고 하면 그의 외할아버지 같은 사람들을 뜻한다$b$b내가 겪은 최악의 일은 그의 양말이 불쾌하지 않아서 화를 내는 거였어"
rows["191:2006097862"]="이 표지 에는 위험 한 소리 를 내는 작업 을 수행 하는 사람 들 에게 보상 을 주는 여러 가지 소식 과 통지 들 이 있다. 특히 눈 을 사로잡는 것 은 없다. 아마도 나중에 다시 확인 해야 할 것 이다."
rows["191:2053606345"]="명예, 전쟁터에서의 영광은 기억 안나? 당신은 인간들과 대화하고"
rows["191:2078254422"]=" ⁇ ... 이건.. 간단히 말해서.. 놀라운 것 같아요. 당신의 친구 엘라는 진짜 재능이 있어요."
rows["191:2082876183"]="오, 저게 정말 행운이네요. 제 기술들은 당신에게 유용할 만큼 좋지 않습니다. 오,  ⁇ 스피indle와 얘기해 보세요. 그는 나보다 더 오래 가죽을 사용했습니다."
rows["191:2090881236"]="이 파란 가죽은 눈길을 끌고 있습니다. 보시다시피, 우리는 많은 열망있는 신병들이 여기 주위를 달리고 있습니다."
rows["191:2113083976"]="난 초석을 이미 익힌 학생들을 가르치고 있어요. 당신은 밤의 엘프 다리아나를 찾아야 합니다. 다르나서스년]의 공예인 테라스에서. 그녀의 기술들은 당신의 완벽한 보충이 될 것입니다."
rows["191:279976142"]="살테릴의 항구에서 나온 목록인가요? 그의 경이 내 최고의 병을 필요로 할 것입니다. 그리고, 물론, 살테릴의 모든 친구들은"
rows["191:361792155"]="발투스 스톤플레이어 (Balthus Stoneflayer) 가 스킨링을 볼 수 있는 사람이고, 스킨링을 할 수 있다면, 그는 어떻게 하는지 가르쳐 줄 수 있습니다."
rows["191:391450359"]="보르고스랑 훈련하고 싶니? 네, 내가 어디를 찾을 수 있는지 말해줄 수 있어. 제 포지스 북서쪽 광장을 지나서 서쪽 길을 가. 오른쪽에 있는 두 번째 건물에서 찾을 거야."
rows["191:447284260"]="우리의 성지들은 육안으로 보이지 않는 우리 땅을 가로지르는 레이 라인 흐름의 신비한 힘을 쏘아 올립니다.$B$B선웰이 없어지면 안정적이고 신뢰할 수 있는 에너지원이 됩니다."
rows["191:494438443"]="제가 한 일을 봤어요. 만약 여러분이 /사무소에서 사용하는 기술에 대해 확신이 없다면, 저를 연습하세요."
rows["191:503194466"]="그럼, 두 사람이 모두 호그랄 바칸을 찾고 있는 것 같습니다. 그는 확실히 왜성입니다. 그래서 조만간 그는 썬더브루 디스틸러리 쪽으로 가서 맥주를 마실 것입니다."
rows["191:518489173"]="땅은 얼어붙은 바위처럼$B$B이 고기차의 바퀴는 가장 좋은 방법으로 진흙을 넘기기 위해 만들어졌습니다."
rows["191:624642313"]="한 곡식을 잘못 샀을 때 갑자기 세상이 무너지고 이제 우리는 스프리트 감염과 이주하는 새들을 시작해야 합니다.$b$B스톰스타우트 맥주 공장으로 가는 비중을 다룰 수 있도록 도와주고 싶었어요!"
rows["191:835795510"]="심장이 약한 사람들은 눈을 감고 싶어 할 수도 있습니다. 이제 링에 데려오는 것은 공포입니다. 센티파어 하비의 어두운 터널에서 잡힌다!"
rows["191:850323347"]="%s 의뢰를 |cFF088A08|Hspell:104898|h[녹색]|h|r, |cFFFF0404|Hspell:104897|h[붉은]|h|r, |cFF0080FF|Hspell:104900|h[블루]|h|r, 그리고 |cFF424242|Hspell:104894|h[검은]|h|r  ⁇ 마의 피!"
rows["191:859145549"]="Twilight's Hammer는 얼마 전 이 한때 맑은 물과 그 주변 땅을 침공했습니다.$B$B그들은 제 호수를 오염시켰고, 다시 깨끗하게 하기 위해 그들을 떠나게 하겠다."
rows["191:868323046"]="결혼식 준비됐어요 행복한 커플에게 선물 좀 줘요$B$B와일드햄어의 미래는 우리를 하나로 묶는 마지막 기회에 달려 있습니다!"
rows["191:94018141"]="영 키스 물은 브라운스톤 마스터를 깨우치고 판다렌 건설 현장에서 진전을 촉진시키거나 $B$B|TInterface\\Icons\\INV_MISC_VOLATILEWATER.blp:64|t"
rows["192:102562441"]="옛날엔 한 번  ⁇ 을 잡았다고 주장하지만, 그 숫자를 보면 너무 \"놀이\"한 것 같네요.$b$b우리가 도박을 하는 분당이 있는데 다시 찾아낼 수 있는지 보려고 합니다."
rows["192:106062441"]="사제님, 더 많은 생존자들이 오고 있다는 소식을 전하고 있습니다. 그들은 여전히 살아 있는 사람들을 찾아내기 위해 최선을 다하고 있습니다."
rows["192:1075281756"]="갑자기 블러드 엘프들이 도시의 수호자들 앞에 무기를 내려놓은 겁니다. 그리고 그들의 지도자인 블러드 엘프 장로 보렌살이 빛의 정원에 뛰어들어 아달과 대화를 요구했습니다."
rows["192:1205188256"]="만약 충분히 단단히 압축하면 기둥에서 배울 수 있는 놀라운 것들입니다.  ⁇ 을 벗어나는  ⁇ 기, 맛있는 쿠키를 만드는 방법, 심지어 비행기를 만드는 방법도 말이죠."
rows["192:1215548450"]="들어, 낯선 사람, 앉아서 얘기하는 걸 좋아하긴 하지만 머리는 거칠게  ⁇ 어요$b$b이 트롤들한테 이런 거리를 그만두라고 해줘서 얘기 좀 하자"
rows["192:1411288272"]="하루에 두 번, 아침 6시 15분, 저녁 6시 15분 기술공 메카토르크는 직접 브루페스트에 출장해  ⁇ 의 탭링 시상식에서"
rows["192:1505742537"]="새타리 천호의 순위에 조금 더 올라갈 때, 저는 당신에게 스카이가드 아우트포스트로 직접 비행을 할 수 있습니다."
rows["192:1584499986"]=" ⁇ 마의 수장 로지 애클로드로스에게 말해주세요. 그는 소그리 저널을 통해  ⁇ 마의 발전률을 지속적으로 높일 것입니다! $B$B|TInterface\\Icons\\INV_MISC_BOOK_11.blp:64|t"
rows["192:1712269869"]="아제로스의 더 독특한 아이템에 전문적으로$B$B지금 나와 얘기하고 있는 거라면, 당신이 찾고 있는 것이 무엇인지 이미 알고 있을 겁니다."
rows["192:1740561946"]="25 레벨에서 글리프를 사용하게 될 것입니다.\010나중에 선택한 글리프를 교체하기로 결정하면, 가격을 위해 다시 설정할 수 있습니다.\010이렇게 하면 추가로 더 비싸게 될 것입니다."
rows["192:1751955663"]="슈바이저와 로이투에게 모든 것이 통제하에 있다고 말해$B$B그들이 널 보내지 않았어?$B$B내가 할 일이 있어!"
rows["192:176357365"]="잘 모르겠어요, 좋은 소식은 당신이 해고됐다는 겁니다. 나쁜 소식은 오늘 밤부터는 일일이면 일회로 돌아가게 될 겁니다."
rows["192:1810533825"]="그래, 네놈이 모르고르를 속이려고 했단 말이구나, 그렇지? 일리단 님께 가기 전에 살아서는 구경도 못할 고통을 선사해주마. 기꺼이 내가 당한 복수를 해 주지."
rows["192:1848012157"]="우리는 눈 폭풍의 덮개로 공격했습니다.$b$b스컬지군들은 경비에서 벗어나지 못했고 우리의 승리는 확실했습니다$b$b그리고... 우리 뒤에서... 호드은 아무데서나 찾아왔다.$b$b그들은 우리에게 모든 것을 지불했습니다."
rows["192:1869215405"]="이 배들이 파괴되면 얼라이언스 계속 싸우게 될 것입니다 스컬지 그들의 집에서 대신 리치 왕자, 쓸모가 있는 사람이 되어 죽은 사람을 죽여라!"
rows["192:1953806779"]="양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양 양"
rows["192:1976915556"]="파스트라이더스 스퀘어의 블러드 기사들은 실버문의 무기 마스터인 이레다에게 그들의 홀 안에 공간을 허락합니다. 그녀의 훈련은 저렴하지는 않지만, 당신은 그녀의 전문성을 높이 평가할 것입니다."
rows["192:2078186178"]="큰 대회, 우리 발명품들을 보여주기 위해. 우리는 그것을 '고블린콘'이라고 부르죠. 그리고 특별한 반려동물을 선물할 것입니다."
rows["192:2106766581"]="말 좀 해봐, 달간 네 말을 듣고 있는게 다야 무슨 일이든 이제 우린 자유계약자이고 정치와 의무가 없어 우리가 원하는 곳으로 돌아다닐 수 있어"
rows["192:2125020534"]="큰 전투가 눈앞에 닥쳤지만, 함께라면 우리는 적을 흔적도 없이 날려 버릴 것이다! 감히 호드에 맞서 이런 중한 범죄를 저지른 놈들은 처절한 응징을 받으리라!"
rows["192:247268074"]="전 경주장에서 단순한 티켓 구제자였는데 경주로는 없어서 더 이상 일하지 않죠$B$B협상 중에도 힘을 쏟고 있어요."
rows["192:337293517"]="람카헨은 네퍼셋에 대한 전쟁을 벌일 수 있는 것은 고의회의 찬성만 있다면$B$B확률은 우리 반대이지만 내 동생은 죽음의 날개의 동맹자들과 논의를 할 수 없다는 것을 이해해야 합니다."
rows["192:37061688"]="우슈올라이, 폭풍마녀$B$B그의 힘은 하늘, 비가, 그리고 파괴된 땅의 힘입니다.$B$B우슈올리는 이제 미친 짓의 가장자리에 휩싸이고 있습니다."
rows["192:468943831"]="네, 네 앞에 서 있는 것은 네가 이해할 수 있는 형상이다, 필사자.$B$B<바일란이 웃는다>$B$B계속해 보죠?"
rows["192:57933705"]="%s은 버려진 목걸이를 내려다보고 슬픔에 빠져, 여인은 화려함을 매료시키고, 고성령들을 불러 일으킨다. 방은 시노레에 대한 그들의 고대 노래와 공조한다..."
rows["192:612330574"]="바로 여기 다크문 페이리가 있을 거야 내가 그 거대한 바그런을 풀고, 모든 텐트를 세우고, 동물원을 세우고, 술들을 쏟아부어 주면, 돌아와!"
rows["192:626717587"]="르나타키, 천발의 칼$B$B고통은 그의 생명 피이고 두려움은 그의 동맹이고 언젠가 그가 돌아와 기쁨의 피를 흘리도록 해  $B$B레나타키는 이제 멀리 떨어져 있어 언젠가는 돌아올 수도 있다"
rows["192:649382820"]="고위집행관, 우린 의견이 전혀 일치하지 않는군! 당신이 낸 의견을 검토하여 쿠엘탈라스를 완전히 해방하기 위해 필요한 조치들을 취하겠소. 이 회의는 조만간 계속하도록 하지."
rows["192:689068715"]="Twilight's Hammer는 이 위대한 파괴의 도구이며, 영광스러운 멸망의 방법이다! (막을 벗겨라!"
rows["192:712866099"]="비록 제 동포들은 당신이  ⁇ 드라크에서 일어나는 일에 적극적인 역할을 하길 원하지만, 우리는 주로 여기서 일어나는 일을 목격하고 제국 종말을 기록하기 위해 왔습니다."
rows["192:775032081"]="그래프폰을 타려고 하는 중인데 그리스 튜든이 그 중 한 명일 거야  \010아이언포지 중간에 있는 대전 동쪽에 그를 찾을 수 있습니다."
rows["193:1064725223"]="끔찍한... 끔찍한 것!$B$B네더스톰에서 52 구역으로 가는 길에 우리 일을 하고 있었는데 저들이 우리를 격추시켰어요!"
rows["193:1195265915"]="그래서 여러분은 오염의 중심에 왔습니다. 우리는 여러분을 도울 것입니다. 우리의 노래는 이 왜곡된 장소의 벽을 통해 울려 퍼져 포세이큰 우리 인종"
rows["193:119530487"]="남편이 전선으로 떠난 이래로 헬레네가 내 힘이 되었어요. 그녀의 친절한 마음과 날카로운 검은 힘든 시간을 지날 수 있도록 도와주었습니다."
rows["193:1201980056"]="이 문서들은 여러 오크스 스파이를 포함하고 있습니다. 우리의 최고의 암살자들은 이 배신으로 보내질 것입니다. 당신의 보상을 받아 현명하게 지출하십시오. 스톰윈드."
rows["193:1255309475"]="골든 로터스는 수천 년 동안 밸리를 관장해 왔습니다.$B$B하늘은 우리에게 그들의 표적을 보냈고 우리는 다시 문을 열어야 할 때라는 믿음에 연합되어 있습니다.$B$B준비 됐어?"
rows["193:1313811775"]="%s 의뢰를 |cFF088A08|Hspell:104898|h[녹색]|h|r, |cFFFFA901|Hspell:104901|h[유랑]|h|r, |cFF424242|Hspell:104894|h[검은]|h|r, 그리고 |cFFFF0404|Hspell:104897|h[붉은]|h|r  ⁇ 마의 피!"
rows["193:1349178725"]="피와 명예, 영웅. 호드은 당신을 환영합니다. 당신의 사람들은 Twilight의 해머를 지워서 이 먼 해변에 대한 권리를 주장하는 동안 시험에 놓이게 될 것입니다."
rows["193:1366797804"]="<바시르 결정조각의 구멍 안에 위축 조각을 넣고 레버를 끌어당기는 동안, 장치가 말 그대로 그것들을 붕괴시킵니다. 몇 분 후에 당신의 발자국들이 발 앞에 나타납니다.>"
rows["193:1391756059"]="네 족속은 귀족이야, 너의 백성은 큰 힘을 가지고 있고 그 와 함께 오는 끔찍한 짐을 가지고 있어."
rows["193:1416036074"]="적의 피드라임이 당신을 보호한다는 생각에는 대칭이 있습니다. 당신의 가죽 작업 기술을 발전시키기 위해 중간 상승에 있는 썬더 블러프 갑옷병 안에 Una를 찾으십시오."
rows["193:1437476011"]="스컬지의 전염병은 여전히 이 지역에 지배하고 있으며, 전염병이 그들을 영향을 줄 만큼 변화되기 전에 우리는 아직 먼 길을 가야 합니다. 필요한 자원을 수집하고 전쟁에 도움이 됩니다!"
rows["193:1456350124"]="만약 당신이 아버지께 돌아가서 내게 왔다면, 먼저 우리 주변을 둘러보라고 부탁해야 합니다. 우리는 정말로 이 사람들을 떠나야 할 때 얼라이언스?"
rows["193:1498516915"]="무얼버릭의 함대는 발사할 준비가 돼 있어 호드 군인들은 신호등을 요청하고 제 전투용사들이 공습을 위해 집으로 갈 수 있도록 최대한 노력해야 합니다."
rows["193:1509606204"]="아라티 연못에 있는 아라토르 동맹과의 싸움에서 디파이러들에게 도움을 주길 원하십니까?"
rows["193:1522825540"]="로로는 그의 소중한 맥주를 흘리고 싶지 않거나 그의 작은 드레스를 더럽히지 않으려면, 나는 불러야 한다."
rows["193:1533341917"]="아쉬브링거를 들고 아버지 심장을 넘겼고, 그의 마지막 말은 영원히 저를 괴롭히게 될 것입니다. \"레노, 네가 뭘 했지? 왜 이렇게 했지?\""
rows["193:1569158914"]="포세이큰 지원군? 지금 언더시티 전방에 스컬지들이 퍼져 있소. 이건 블러드 엘프들이 처리할 문제요. 우리 포세이큰은 후방 지원과 조언을 위해 여기 온 것이오."
rows["193:163678443"]="아, 강한 모험가들을 여러 번 만나게 되는군요. 황천의 폭풍은 위험한 곳이니 가장 효과가 뛰어난 마법이 필요할 겁니다. 저는 최고급 재료만을 팔고 있으며 일반 제품과 아제로스에서 들여온 물건들 등 모두 있답니다. 와서 한번 구경해 보시면 절대 실망하지 않을 겁니다!"
rows["193:1863178292"]="왕  ⁇ 은 호드에게 다른 워치프의 이름을 지도록 허락한 날 후회할 것이다.$b$b누가 이 새로운 워시프가 몇 년 후에 트롤 머리에 어떤 생각이 들지 않을 거라고 말했을까요?"
rows["193:1865353706"]="린의 손실에 대해 깊은 애도를 표하지만 내 군대의 모든 병사를 생각해야 합니다.$B$B모든 생명은 소중하고, 동등하게 평가되어야 합니다.$B$B한 사람의 목숨을 구하기 위해 많은 사람들의 생명을 도박에 걸지 못했어요"
rows["193:1975961564"]="나는 Teldrassil를 덮고있는 차가운 풀이 다른 모든 것만큼 좋은 침대를 발견하지만 Saelienne 인트래시의 인에서 보관하는 침대는 고급스러운 취향을 가진 사람들을 위해 매우 적합합니다."
rows["193:2008254361"]="신성 벨을 사용해서 우리 안에 있는 약점의 잔해를 태워버릴 거야 두려움, 절망, 증오, 의심"
rows["193:2084099369"]="그냥 2 이 임무에 필요한 폭발물도 좀 더 많이 필요해 보네요."
rows["193:2122202840"]="그럼 역사에 대한 지식을 시험해 보죠! 호드 무례하게 공격된 얼라이언스 군인들이 스컬지 이 문을 잡으려고 하고 있어요"
rows["193:232090473"]="<바시르의 성탄조각의 구멍 안에  ⁇  수 있는 절단 조각을 넣고 레버를 끌어당기는 동안, 장치가 말 그대로 그것들을 붕괴시킵니다. 몇 분 후에 당신의 플라스크가 발 앞에 나타납니다.>"
rows["193:417787471"]="내가 훈련해줄까? 우리 둘 다 알잖아, 난 못할거야. 포세이큰 이 의 아포테카리움 언더시티."
rows["193:579135862"]="공부할 능력이 내보다 더 많아서 베나 윈터하우프와 좀 더 공부를 해야 해요"
rows["193:671869397"]="미스터리 홀의 작은 마법소녀인 핑크는 아마도 당신이 가진 마법의 필요에 도움이 될 것입니다.\010미스터리 홀은 아이언포지의 문에서 북쪽에 있습니다."
rows["193:76872725"]="멀리 썬더 블러프 북쪽은 당신의 여행이 당신을 데려가는 곳입니다. 친구 한 번 당신이 찾고있는 사람을 찾을 수있는 블럭워치 중 한 사람의 지혜를 찾으십시오."
rows["193:845777497"]="저는 수많은 세계를 여행했지만, 이 겨울 베일 축제만큼 즐거운 축제를 본 적도 없습니다. 여러분은 그 축제를 직접 볼 수 있도록 왜성들의 위대한 도시인 아이언포지로 여행해야 합니다."
rows["193:927869390"]="내가 준비할 때 가르쳐줄게 좋겠지만 아직 그 시간은 오지 않았어! 다르나서스."
rows["193:966345603"]="울두아르의 네 감시자는 프레이야, 토림, 호디르, 미미론입니다. 인장은 그들의 육체와 정신에 긴밀하게 연결되어 있습니다. 별자리 투영관에 접근하려면 네 개의 인장이 모두 필요합니다."
rows["194:1035507666"]="네 손에는 특별한 혼합물을 넣었지, 웨이커. 적을 물리칠 때마다 그 시체가 독성으로 주입될거야."
rows["194:1088957387"]="아제로스의 민족들의 힘, 지혜, 끝없는 인내는 여러분들 생각도 못했던 사람들에게 영감을 줍니다. 이 날, 이 날, 피와 공포의 날, 저는 여러분들이 영웅들의 세상임을 봅니다!"
rows["194:1114731314"]="탐험가들의 협회에서 제가 함께 할 수 있게 해주었지요. 하지만 리븐우드와 주변 지역의 위험 때문에"
rows["194:1134189233"]="%s 의뢰를 |cFF9932CD|Hspell:104896|h[ 보라색]|h|r, |cFF088A08|Hspell:104898|h[녹색]|h|r, |cFF424242|Hspell:104894|h[검은]|h|r, 그리고 |cFF0080FF|Hspell:104900|h[블루]|h|r  ⁇ 마의 피!"
rows["194:1341261003"]="내가 자네의 추측을 받아들이지 않을거야 네가 직접 싸움을 하지 않는다면\010경비원 한 명과 가서 싸움을 준비해"
rows["194:1384304988"]="이제, 여러분은 소속 기일을 만들기 위해 서류가 필요할 것이고, 조ンド르 스틸브로는 이 과정을 시작하는데 도움을 줄 수 있습니다. 아이언포지 초보할 준비가 되면 방문객 센터로"
rows["194:1502272987"]="그녀가 내가 그녀를 데려가길 원한다는 것을 깨닫지 못합니까? 나는 젊고 죽고 싶지 않습니다. 우리는 앞으로 많은 좋은 년을 가지고 있어야 합니다. 그리고 이것이 유일한 방법입니다. 그녀에게 이런 것들을 말하십시오. 이해하도록하십시오."
rows["194:1585571861"]="%s 의뢰를 |cFF9932CD|Hspell:104896|h[ 보라색]|h|r, |cFFFF0404|Hspell:104897|h[붉은]|h|r, |cFFFFA901|Hspell:104901|h[유랑]|h|r, 그리고 |cFF424242|Hspell:104894|h[검은]|h|r  ⁇ 마의 피!"
rows["194:1632597206"]="바라딘 홀드 톨 바라드의 형제들은 매우 바쁘고, 필요할 때 항상 사용할 수 없습니다."
rows["194:1781483431"]="친족의 영혼들의 동행은 강력한 힘이 될 수 있습니다. 크룸은 이 일을 달성하는 데 도움이 될 것입니다. 엘리베이터 옆에 낮은 상승층에 있는 썬더 블러프 시민 정보 센터에서 그를 찾을 수 있습니다."
rows["194:1902621865"]="뛰어야 벼룩인 게 누구더냐? 물론 너는 우리가 말퓨리온 님에 이어 너까지 소환할 거라고는 생각도 못했겠지? 자, 구원받을 시간이다, 에라니쿠스. 너의 광기와 타락을 정화하도록 하마."
rows["194:1904256260"]="얼라이언스은 이 거리를 잠시 동안 유지해왔고 사냥꾼과 목재들이 이용한 것으로 보였습니다.$B$B전쟁이 계속되고 있는 상황에서 군대가 지금 이 곳에서 지휘하고 있다고 믿으면 좋겠다."
rows["194:1933238448"]="내 힘이 최고조에 달한 지금이라면 시간의 균열을 사용할 수 있도다. 그걸 사용해 적들에게 더 큰 피해를 주고 충격 충전을 얻을 수 있으리라. 충격 충전을 모아 충격의 창을 사용하면 큰 피해를 줄 수 있노라!"
rows["194:2043027257"]="볼진은 구석에 뒤집어져 있어 우리의 도움으로 그는 지옥의 성을 깨는 비단으로 되어서 우리 적들이 서로를 약하게 해"
rows["194:2063674350"]="스틸워터 경장님, 당신은 우리의 생활 방식에 위협이 되고 있습니다. 포세이큰 법은 진정한 죽음입니다."
rows["194:3057149"]="내가 '보병 친화적'이라고 부르는 것은 아니었어요. 이 것들을 돌리는 방법을 찾아볼게요. 남쪽으로 이동해 보겠습니다. 그 바위 쪽으로 가자. 어쩌면 우리는 그 바위를 통과하고 여전히 오그르를 피할 수 있을지도 모릅니다."
rows["194:323147067"]="키린 토르에게 맹세했었는데, 그 유대감은 신뢰와 상호 이해의 관계였는데, 그리고 그들은 그 유대감을 배신했습니다."
rows["194:331175257"]="제피어에 오신 것을 환영합니다. 가장 부드러운 여행입니다. 불모의 땅 ⁇ 아, 비행을 즐기세요. 기름의 향과 섞인 건조한 달콤한 공기가 아닙니다."
rows["194:518499209"]="구름 뱀의 순서에 들어가면 뱀 라이더의 여정을 시작할 것입니다.$B$B여러분은 계란에서 아기 뱀을 키우고 매일 훈련시켜서 어른이 되어 성장하는 것을 지켜보실 것입니다."
rows["194:537232023"]="파우돈 마을에 오신 걸 환영합니다. 왜 왔는지 모르겠지만,$B$B왜 좋은  cider 한 잔을 가지고 앉아서 걱정이 사라지는지 않는가?"
rows["194:576663324"]="더 많은 수업을 드릴 수 없습니다. 당신의 능력은 내 능력보다 더 뛰어나다. 썬더 블러프의 중부 고원 북서부 상점에서 타우렌 우나를 찾아보세요. 그녀는 더 고급 교육을 제공합니다."
rows["194:580888093"]="리치 왕이 정문으로 주의를 돌렸으니 우리는 측면으로 들어가 정보를 찾도록 해요. 스컬지를 마지막으로 확실히 무찌를 수 있는 정보 말이에요."
rows["194:634340395"]="네, 네 개의 원자체를 파괴하면 문이 열릴거야. 난 확신합니다. 트로그스만 조심해."
rows["194:651559975"]="이 셔프 끝나면 어드파더 윈터가 뭘 할지 잘 알고 있어"
rows["194:665769838"]="탐험가 동맹은 이 세상의 숨겨진 비밀을 밝히기 위해 존재합니다. 재앙이 대부분의 사람들에게 파괴적이지만, 우리에게는 수많은 정보와 부를 제공했습니다."
rows["194:834768465"]="이제 원심력 피조물이 하나 남았도다. 그 피조물을 찾아내어 파괴해야 바로스 클라우드스트라이더의 보호막을 못 쓰게 할 수 있노라. 피조물은 마력의 눈 중간쯤에 있는 가속의 고리에서 찾을 수 있으리라."
rows["194:845498327"]="정답, 수수주들의 전통은 수많은 세대를 거쳐져 왔고 저는 수수욕이 많은 판다렌의 한 갈라진 연결고리일 뿐입니다.$b$b하지만 가끔은 내가 마지막 연결고리일지도 모른다고 두려워합니다."
rows["194:884840936"]="분명 큰 승리로, 지금 우리는 질병으로 황폐화된 길니안 고향에 주의를 기울이고 있습니다."
rows["194:947499080"]="여기서 내 일은 끝났어, 난 마알리스와 다른 사람들이 당신이 조금이나마 도와줬다는 걸 알도록 하겠습니다."
rows["194:983428967"]="오윈은 종종 내가 재고하라고 요구하지만, 제 우선 순위는 여기 있습니다."
rows["195:1001496605"]="그럼 역사에 대한 당신의 지식을 시험해 보겠습니다. 전 건강 한 paladin 이 드레네이 는 불타는 군단와 싸워서 병에 걸려 깨진 사람 중 하나가 되었습니다. 그는 나중에 강력한 샤만이 되었습니다."
rows["195:1027863831"]="제 연습생인 샤타리아를 서쪽으로 보냈어요."
rows["195:1054810851"]="%s 의뢰를 |cFF0080FF|Hspell:104900|h[블루]|h|r, |cFF9932CD|Hspell:104896|h[ 보라색]|h|r, |cFF088A08|Hspell:104898|h[녹색]|h|r, 그리고 |cFFFFA901|Hspell:104901|h[유랑]|h|r  ⁇ 마의 피!"
rows["195:1058494946"]="내가 가르쳐 줄 모든 걸 이미 알고 있어 다른 사람과 이야기 할 때가 됐을지도 몰라 다르나서스진짜 재능이 있어"
rows["195:1087174937"]="우리 길은 거짓이라는 걸 깨달았어요. 우리가 왕자라고 부르는 사람이 우리를 배신한 것입니다. 권력에 대한 욕망으로 그는 피가 있는 사람을 보내서 우리를 공격하고,"
rows["195:1124600947"]="샌드푸리의 전설적인 검을 찾으려 하지?$B$B당신은 수르트라즈를 위해 죽이고 모래를  ⁇ 은 피를 흘리고 보물이나 권력을 찾아서$B$B만약 당신이... 사막에 오신 것을 환영합니다."
rows["195:1138692216"]="내가 왕을 다시 사자의 착륙으로 데려다보고 필요한 정보를 자원적으로 제공하도록 설득할 수 있는지 확인해 보겠습니다."
rows["195:1178751600"]="어서, 좀 더 쉬세요, 중요한 얘기를 해야 해요. 잠깐... 내가 뭘 씻는 건가?"
rows["195:1232296192"]="제 생각엔 낚시의 가장 좋은 부분은 느린 속도가어서 생각하고 과거를 생각해보고 미래를 계획하는 시간을 줍니다.$B$B음주할 수 있는 좋은 변명이기도 합니다."
rows["195:1337419840"]="이 셔프 끝나면 할아버지가 뭘 하겠는지 잘 알고 있어요"
rows["195:1382922775"]="모든 것, 휴식을 포함한 모든 것에는 시간과 장소가 있습니다. 블러드하프 마을의 서쪽쪽에 있는 카우스는 휴식을 취하는 사람들을 위해 긴 집을 유지합니다."
rows["195:1553283903"]="안퀴라즈의 쌍둥이 제왕으로 알려진 베크닐라쉬와 베클로어는 그들의 신전에 있는 성역에서 이 전투를 지켜보고 있었습니다. 이 영악한 형제는 스태그헬름의 군대를 혼란에 빠뜨리고 갈라놓을 수 있는 계략을 궁리했지요."
rows["195:1568703149"]="내가 지금 앞에 있는 기적을 목격하고 있습니다. 천 년 동안, 나는 이 방에 들어온 불쾌한 키라지와 실리티드 외에는 살아있는 단 한 개도 보지 못했습니다."
rows["195:1601704217"]="모든 사람들이 이 저주받은 성전에서 일어난 일을 알게 될 것입니다, 영웅. 아제로스 내면의 가장 먼 곳까지!"
rows["195:161627171"]="당신 은 뛰어난 재능 이 있다! 당신 은 참으로 영감 을 얻는다. 지식 을 추구 하는 데 계속 나선다면 스톰윈드 에 조지오 볼레로 와 이야기 해 보십시오. 그 는 매우 존경 받고 있으며, 당신 의 가르침 을 더 발전시킬 수 있을 것 이다."
rows["195:1638769053"]="지구 셔터라는 이름은 수백 년 동안 우리 가족에게 붙어 왔습니다. 그리고 아버지와 그의 아버지처럼, 저는 제 이름의 의류를 만드는 권리를 물려받았습니다. "
rows["195:1639901718"]="내 영원한 경비가 자부심의 부패를 멀리 두었습니다. 이 부패에 직면하기 위해 여러분은 스스로 화염 빛에서 자신을 정화해야합니다.\010준비 됐어?"
rows["195:1715875177"]="단순히 미용적인 조치일 뿐 아니라 도덕성도 높이고 우리 국민들에게 우리가 손에 꼽을 수 있는 힘이 있다는 것을 보여준다. 그리고 그 힘으로 우리는 거의 모든 일을 할 수 있습니다."
rows["195:1723416614"]="블루 보안 카드 삽입 성공 보안 레벨 델타 단위\01001010000 01101100 01100001 01111001 00100000 01001101 01101111 01110010 01100101 00100000 01010111 01101111 01010111"
rows["195:1763585737"]="그림자가 주장 한 이래로 그늘숲 나는 잠을 못 수 있습니다. 나는 바람에 소리 지르는 유령 소리 때문에 깨어 있습니다. 거의 양떼의 소리처럼 들립니다. 그들은 멈추지 않을 것입니다."
rows["195:177420940"]="아, 내가 느낄 수 있네 - 당신은 날 이길 수 있어! 나는 지금 당신을 안전하게 스트라톨메로 운송 할 수 있다고 믿습니다. 당신이 먼저 내 동료를 방문 한 조건으로"
rows["195:1941656245"]="좋은 에르마, 그녀는 몇 년 동안 지역 동물을 돌봐주었고, 당신이 원하는 모든 동물을 돌보는 것을 기쁘게 생각합니다."
rows["195:197735258"]="%s 의뢰를 |cFF0080FF|Hspell:104900|h[블루]|h|r, |cFF424242|Hspell:104894|h[검은]|h|r, |cFF9932CD|Hspell:104896|h[ 보라색]|h|r, 그리고 |cFFFFA901|Hspell:104901|h[유랑]|h|r  ⁇ 마의 피!"
rows["195:2038878187"]="네 가죽에 대한 이해는 내보다 깊어지. 어쩌면 불모의 땅의 타우라조 캠프의 타우렌 크루룸우 풀문을 방문해야 할지도 모른다. 그는 너의 재능의 학생에게 제공할 많은 지식을 가지고 있다."
rows["195:2074292103"]="내가 깨어난 즉시, 클라크시들은 내 존재를 감지하고 그들이 용기를 다짐한 만큼 전달했습니다.$B$B제 자신의 의심을 확인해줬어요. 황후는 더 이상 제국을 통치할 수 없습니다. 그녀는... 깨끗해야 합니다."
rows["195:2092954660"]="파트너, 당신은 혼자 농장을 짓고 싶어서 매일 다시 와서 채소를 심어 뜯어내면"
rows["195:2107281405"]="저와 제 동료들은 우리가 알고 있는 가장 치명적인 물질을 수집하고 적들에게 미치는 영향을 시험하고 있습니다."
rows["195:235697945"]="제네리온 탐험대는 내 목숨을 앗아간 채굴에서 나를 구해줬고 제네리온 탐험대의 동맹군들에게 제 재료를 판매하고"
rows["195:303401581"]="얼마 전지 않아 인근의 오그르들에게 Thunderlord Stronghold의 통제권을 빼앗아야 했습니다.$B$B방어에 도움이 되려고 왔어?"
rows["195:322208513"]="내가 이미 말했잖아, 맥소프, 난 3개 이상의 구조팀을 파묻혀서 아무도 돌아오지 않았어."
rows["195:352097686"]=" ⁇ 툴과 그 그림자 부문 형제들을 지하 그림자 틈에서 찾아라"
rows["195:481298756"]="항상 너무 무성심한 젊은아, 힘이 아닌 지식은 없다. 이 유물은 신성 벨과 같은 시대를 거슬러 올라간다. 그 비밀을 아는 것은 우리를 가로쉬의 상에 더 가까이 데려다 줄 것이다."
rows["195:566077827"]="해 해 해 해 해, 이런 느낌이 들지 않아 $p...이보다 더 나쁜 상황이었는데... 얼라이언스이제 사업으로 돌아가자"
rows["195:608159753"]="내가 6년 연속  ⁇ 투 대회에서 우승했어, 네가 원한다면 이  ⁇ 투를 마을로 던져서  ⁇ 투를 만들 수 있어"
rows["195:63304456"]="이 달걀은 블랙 드래곤 비행의 달걀처럼 탄력적이기 때문일 것 같습니다. 아마도 그 옆에는 수많은 절단 조각을 두면, 그 진동은 그 달걀을 찢어지게 만들었을까요?"
rows["195:656156441"]="악마의 혐의를 받고 더 좋은 이름을 기대하고\010가격으로, 저는 현재 종들을 없애는데 도움을 줄 수 있습니다."
rows["195:690827386"]="자연의 길을 막는 것은 이단성입니다. 자연의 힘은 파괴적인 힘일지라도요.$B$B하지만 다크셔를 파괴하는 세력은 자연적이지 않을 겁니다."
rows["195:708685270"]=" ⁇ 미학 트레이너를 찾고 있어요? 기술공 거미들이 모이는 도시  \010왜 내가 파란색 술은 안 먹었나?"
rows["195:817272263"]="네더스톰은 항상 지금처럼 아니었습니다.$B$B이 무너지는 땅이 파라홀론 평야라고 알려진 시절이 있었습니다. 그 시절 중 거의 이 땅은 악의 지배를 받지 못했습니다."
rows["195:876194155"]="지구에 대해 왜자와 논쟁하지 않기로 결심했습니다. 만약 청동주들이 이 태블릿이 지구의 문제를 해결하는데 도움이 될 것이라고 확신한다면, 우리는 그들을 지원해야 합니다."
rows["195:912165809"]="찢어진 손은 블랙록의 상부 성곽에 스파이를 배치할 수 있었습니다. 정보 수집 과정이 느려졌지만, 우리는 무시할 수 없는 발견을 해냈습니다."
rows["195:938339603"]="다크스피어, 드럼을 들지 않아서 오래됐어요. 의식적인 제물을 마셨죠. 포세이큰  ⁇ 스암디?"
rows["195:989847780"]="이 거대한 업적을 성취하는 데 성공한다면, 내 죽음의 화살표로 다시 돌아가서 살상르를 살아 있는 영역에서 불러내기 위해 승마자의 소원을 사용하세요."
rows["196:1072267892"]="돌진 표적에 방패 부수기를 사용합니다.$B|Tinterface\\Icons\\Ability_Warrior_ShieldBreak.blp:32|t$B표적이 무력화되었을 때 이어서 돌진으로 공격합니다.$B|Tinterface\\Icons\\Ability_Mount_Charger.blp:32|t"
rows["196:1094386273"]="날 우습게 알면 큰코다칠 줄 알아라, 아카마! 일리단 님에게 감시자를 잘 지켜보라는 명령을 받았다. 뭔가 숨기고 있는 게 들통나면 널 내 손으로 박살 낼 것이다!"
rows["196:1110544267"]="하지만, 나는 멀리 있는 마음의 울음을 들을 수 있습니다. 세상들 사이의 망막 속에서 반향을 하고 있습니다. 그것은 연인의 심장의 울음입니다."
rows["196:1115777678"]="이 난민들은 많은 고통을 겪었고, 그들은 더 많이 고통받을 것임에 틀림없습니다. 여러분은 이미 그들을 도와주셨고, 그 때문에 저는 여러분께 감사합니다.  "
rows["196:1154188181"]="'한은 고개를 끄덕인다.$B$B네, 네, 네, 네, 네, 네, 네, 네, 네.$B$B고르샤크는 당신의 워치히프가 큰 계획을 가지고 있다고 말해줬어요. 얼라이언스와 호드의 상호작용 방식을 바꿀 수 있는 계획이요."
rows["196:1172607439"]="시간 낭비하지 마, 당신보다 나이가 많은 연구 프로젝트가 있어 언더시티- 그는 포세이큰 아마 기본적인 것을 가르쳐 줄 수 있을 겁니다."
rows["196:118842304"]="내가 바보처럼 보이시나요? 왜냐하면 멍청한 사람이만 여기 남아서 당신과 당신의 동맹군들과 싸워야 할 것이기 때문입니다."
rows["196:1202632540"]="아녹은 좋은 붕대를 만들어서 호수 연안에 있는 생존의 가장 잘 어울리는 집에서 찾아요"
rows["196:1211321364"]="발린다 스톤하스 대장이 전선에 얼라이언스 그녀는 북쪽 전투장인 스톤헤어스 포스트에 있다.$B$B발린다는 아직 전투에 다시 들어가지 못했다."
rows["196:1247873501"]="어마스터 바스바이트는 높은 품질의 맛있는 물고기를 물로 심어주었습니다. 그래서 그는 대회를 할 수 있습니다.\010그가 우승을 차지하면 5개의 맛있는 물고기에 은을 줄게"
rows["196:1324041810"]="그 순간만 악마가 파괴를 일으키기 위해 필요한 것 뿐이야. 불타는 군단은 우리를 수천 년 동안 지켜보고 있어, 항상 가장 작은 균열이 빠져나가는 걸 기다리고 있어, 가장 작은 틈이 속삭이는 걸 기다리고 있어."
rows["196:1349831912"]="내가 초보자였을 지 너무 오래 됐어 내가 당신에게 가장 좋은 선생이 될 것 같지 않아"
rows["196:1400844065"]="나는 죽고 지옥으로 갔을 것 같은 맛이 있습니다. 썩는 삼성동의 사체처럼 맛있는 기울기가 있는데, 그 다음에 내 목에 비만한 타우런이 밀어내죠."
rows["196:1542798209"]="만약 제가 초보자를 가르치면 더 많은 학생들이 저를 방문하고, 모든 것이 험난하게 될 것입니다. 댄 골타스와 얘기해 보세요. 그는 약간 강렬하지만, 그는 좋은 것을 의미하고, 그는 괜찮은 교사입니다."
rows["196:1688883795"]="내가 계산을 좀 잘못한 것 같군. 감옥에 갇힌 마귀가 내 마음을 타락시키고 제1지시를 재정의하고 말았다. 이제 모든 시스템이 제 기능을 찾았다. 정상이다."
rows["196:1691846748"]=" ⁇ 니 여사는 네 눈을 들여다보고 머리를 돌리고 있어$b$b<그녀의 의도를 제대로 해석했다고 가정하면,  ⁇ 니 미스가 얼마나 강하게 타야 할까요?>"
rows["196:1708935238"]="실버문 다라란과 동맹을 맺고 있는 2000 우정은 우리가 '존중'한 바르로시 장군의 사모에 의해 방치해야 할 것이 아닙니다.$b$b오... 이 유물 때문에 왔어?"
rows["196:1756879215"]="알겠어요, 그 반대편의 풀이 더 녹색일지도 몰라요. 크라카우어와 댄포르트는 정말 전사처럼 엉덩이를  ⁇ 을 때려야 할지도 모르죠."
rows["196:1761771133"]="이 왜기는 스파이 임무 중 발견되고 살해된 것으로 보인다. 죽음의 포지의 직원들은 시체를 공개적으로 남겼고, 아마도 다른 침입자들에 대한 경고로"
rows["196:179554522"]="저 가난한 마을은 잔다라리들이 도착했을 때 함락에 갇혔어요. 그들은 스스로를 방어할 수 있는 숙련된 전투자도 없어요! 당신은 그들을 도와야 합니다. 신은 당신이 안전하게 마을에 도달할 것을 보장합니다."
rows["196:1900497122"]="흠... 저 케켁 많이 늙었다. 광란심장 일족 지도자, 장로인가 보다. 이거 좋다. 케켁 미래 훌륭하다. 전사도 되고 지도자도 된다. 케켁 여기 데려와 줘서 행복하다. 원장 아줌마는 케켁한테 이런 거 안 해준다."
rows["196:2119574336"]="실버문에 옷 기증하고 싶니?$B$B넌 그냥 호크스트라이더를 쫓아다니?"
rows["196:221233163"]="원수들이 우리 도시에 들어온 이후 내 가슴속은 증오로 가득 찼지. 보렌살이라는 자를 알았는데 그는 후에 현자라고 불리더군. 바로 놈의 손에 내 형제가 죽었는데 말이야."
rows["196:272592417"]="모가 존재에 대해 나쁜 느낌이야$B$B이 모가 유물을 발굴하는 이유는 하나밖에 없는데, 그것은 지식의 목적이 아닙니다.$B$B모그의 힘에 대한 단서를 찾고 있습니다."
rows["196:719671828"]="당신이 충분히 능력 있는 것처럼 보이지만, 만약 당신이 진정으로 배우고 싶다면, 아무것도 당신의 길을 걸리지 않을 것입니다."
rows["196:906830016"]="이게 무슨 일이야? 하, 손님이 찾아오실 줄은 몰랐는데 사과 말씀드리겠소. 보시다시피 우린 지금 무척 바쁘다오. 하지만, 손님 접대는 꼭 친히 이 몸께서 해드리겠소."
rows["196:917135382"]="그런 술은 안  ⁇ , 망치 농부! 아니, 그도 안  ⁇ ! 잊어 - 그냥 불기 전에 저  ⁇ 을 줘. 내가 할 수 있는 모든 것을 구해 줄거야. 지금, 주의를 기울여."
rows["196:918584266"]="제 순위는 오랫동안 이 땅을 돌아다니며, 우리가 할 수 있는 모든 것을 지원해 왔습니다. 레이  ⁇ 의 시대부터는 5개의 순위가 있었습니다."
rows["197:103849771"]="그는 황금 수도인 잔다라르가 카타클리즈마의 후파로 서서히 파도에 빠져들며 그 위대한 사람들이 그들의 위대한 작품들이 바다 밑에 영원히 떨어지면서 익사하는 것을 묘사했습니다."
rows["197:1057432330"]="이 직원은 우리 가족에서 세대를 거쳐 왔고, 이 곳에서 수백번의 대회를 우승했습니다.$b$b그 안에 있는 힘을 느낄 수 있어? 내가 여행한 곳보다 훨씬 강하다."
rows["197:1224890730"]="너무 끔찍해 우리 3개 총이 쓰러졌어 얼라이언스 공습 때 영토를 공격하는 동안 아무도 그들이 살아있는지 죽은지 모릅니다!$B$B이것은 우리의 공습 능력에 끔찍한 타격을 준다."
rows["197:1229236622"]="너희는 우리 조상들의 안식처를 더럽혔다. 이 죄에 대한 형벌은 하나뿐이다. 죽은 자의 땅에 찾아온 것이 잘됐군... 곧 너희도 그들과 함께하게 될 테니."
rows["197:1231075678"]="더 진보된 선생님으로 갈 때가 됐습니다. 페라라스의 피더문 강릉에 밤 elf Kylanna Windwhisper가 살고 있습니다. 그녀는 뛰어난 마음을 가지고 있으며 의심의 여지없이 더 많은 훈련을 할 수 있습니다."
rows["197:1303069588"]="드루이드로서 우리는 자연의 균형을 지키고 있습니다. 내 인생 일 이 반대를 했습니다. 내 어리석은 일에서, 난 혼란을 꿰매고, 이 변함적 작물을 더 확산하기 전에 재확해야 합니다."
rows["197:1328615272"]="첫 번째 도전은 당신이 아르헨티나 전쟁마에 올라갈 필요가 있습니다.$b$b말에 올라와 나와 얘기해, 그러면 계속할 수 있어요."
rows["197:1382198173"]="왜 그래지 알겠어? 네가 이 가게에 타고 왔는데 5,000 금 조각, 최고급, 장갑 위버너."
rows["197:1387823766"]="만약 당신이 정말로 그 후진들과 대화를 나누고 싶으면,"
rows["197:1422667943"]="<알트루이스는 당신을 향해 돌아서 웃는다.>$B$B- 아니, 안 그래$B$B<알트루이스는 네트란다무스인 그의 양동아에게 지목한다.>$B$B우리는 이 가이용 수용소가 그들이 건설하는 것을 완성하기 전에 그들을 막아야 합니다."
rows["197:1504137159"]="샤트라스를 향한 공격이 계속되었지만 보시다시피 도시는 함락되지 않았습니다. 한편, '지리'라는 나루가 일리단의 본거지 바로 앞에 있는 어둠달 골짜기를 성공리에 습격했습니다."
rows["197:1545347980"]="축하합니다. 이제 막 이 놀라운 업적을 성취한 만큼의 타이틀을 부여해 드리겠습니다. 앞으로 당신은 \"지신도, 무능력, 실망스러운 소용자의 살인자\"로 알려져 있을 것입니다."
rows["197:1559146135"]="그리고 당신은 도시를 안전하게 지키도록 위탁받았어요. 거리가 비하들로 가득한 상태에서 어떻게 내가 \"단순한 임무\"를 수행할 수 있을까요?"
rows["197:1588160120"]="이 전쟁은 우리 인력과 자원을 막아 버린 엄청난 손실이 되었습니다. 심지어 테일드라실에서도 그 영향으로부터 벗어날 수 없습니다."
rows["197:1625579058"]="여기 보드 위에 몇 개의 유명한 법안이 있습니다.$B$B하지만, 이 작은 글씨 는 여러분 이 이 할 수 있는 일 이 어느 하나 에 대해서도 아직 준비가 되지 않았음을 알려 줍니다."
rows["197:1766675419"]="날 기억 안나? 스컬지...그들은 당신을 정당한 계산의 힘으로 만든 모든 것에서 당신을 배제하려고 노력했습니다."
rows["197:19887001"]="우린 거칠게 하지 않아요, 낯선 사람, 그냥 모두가 서두르고 있어요. 우더가 도착할 때 모든 것이 완벽하다는 걸 확인하려고요."
rows["197:2029758034"]=" ⁇ 의 길을 따라가려고 하는 사람도 있지만 밤의 엘프들만이 밤의 길을 따라가려고 합니다."
rows["197:2042858053"]="우리는 모든 연령대의 사람들이 게임을 즐길 수 있도록 하고 싶습니다.$b$b링 투스는 움직이는 거북이의 뒷면에 반지를 내리는 간단한 게임입니다.$b$b내가 좋아하는 게임 중 하나죠."
rows["197:389413383"]="당신은 성원 성원의 호드 지역에서 더러운 동물을 찾고 있습니다.$B$B저는 꽤 힘든 곳이라고 들었습니다. 하지만 부엌에는 훌륭한 요리 트레이너가 있습니다."
rows["197:41138669"]="내가 네 나이였을 때 아침 식사 전에 그 빗방울들을 다 정비하고 다른 모든 일을 할 수 있었을 뿐이지 겨울 봄의 눈이 내리는 동안"
rows["197:636231997"]="이 포털은 다른 포털과 같지 않습니다 아제로스이 문제를 해결하기 위해서는 더 많은 마나 세포$B$B그게 아니면 켈로다나스 섬과 선웰 섬에 대한 접근을 잃게 될 수도 있습니다."
rows["197:700643667"]="동쪽에서 귀소로 들었는데, 우리의 존경받는 스카라브 주인은 전투에 합류했고, 샤트라트에서 온 병사들이 함께 참여했습니다. 아달이 축복받은 영웅들, 아달의 손으로 지위를 부여받았죠!"
rows["197:827310877"]="내가 보여드릴 모든 걸 제대로 따라갈 만큼 발전된 건 아니잖아"
rows["197:898920057"]="호바트 걱정 마, 보스, 그는 지금 좀 붕괴하고 있어요.$B$B그 대폭발은 더 나쁜 시기에 일어날 수 없었어요. 그는 미세 메차치킨을 끝낼 뻔했거든요."
rows["197:931222423"]="금발, 녹색 피부, 뿔 머리, 파란색 피부 - 우리에겐 이 모든 것이 훌륭한 괴물 공학에 대한 새로운 시장입니다! 레지온과의 또 다른 전쟁의 전망도 우리에게 더 많은 판매를 의미합니다!"
rows["197:943290061"]="브릴의 유일한 요리사는 도시 한가운데에 있어요$B$B왜 저렇게 나오는지, 그가 만든 것을 팔지 않거나, 신선한 생육을 어디서 얻는지도 모릅니다.$B$B아무 상관이 없지"
rows["197:979757727"]="당신은 하얀의 무제한으로 멸망했다 |cFFFF0000|Hspell:120195|h[Meteor]|h|r! 하얀의 무제를 사용할 때 당신의 동맹과 함께 그룹을 확실히 해 손상을 공유 할 수있는이 능력을 사용."
rows["197:992896277"]="이번 전쟁에서 어떻게든 이기겠지 하는 생각은 버리십시오. 이번 전쟁이 단지 전쟁일 뿐이라는 착각도 버리는 게 좋을 겁니다. 이 파괴된 땅의 모든 것을 위해 싸우고, 할퀴고, 걷어차지 않으면 모든 것을 잃게 될 테니까요."
rows["198:1085846022"]="그리고 당신은 정확히 무엇을 할 것이라고 생각합니까? 당신의 위협은 공허합니다. 당신의 다른 종류의 사람들과 함께 빈민가에 가라."
rows["198:1134121516"]="네 덕분에 이쪽은 우위를 점하고 있어 빨리 이 놈들을 데려다 줄 거야"
rows["198:1258592484"]="네, 나중에 다시 얘기할 수 있어. 문 뒤에 있는 게 뭔지 알아볼 때가 됐어."
rows["198:1280789648"]="이 거미들이 없었다면 우린 이 엉망에 빠지지 않았을 거야!$B$B그들은 세계 확대를 위한 기기들과 그 같은 말도 안되는 것들을 가지고 대폭폭탄을 일으킨 사람들이라는 사실은 잘 알려져 있습니다!"
rows["198:130381507"]="오그리마 내의 명예의 계곡의 무기 마스터, 사요크와 한아시, 활을 쏘는 법을 가르쳐 줄 수 있습니다. Farstrider 광장에서 발견 된 실버문의 무기 마스터, Ileda도 전문가입니다."
rows["198:1366278616"]="호드 우리 의 공급이 줄어들고 있다. 우리 땅 은 무산하고 있다. 우리 의 전사 들 은 휴식 에 필요 합니다. 이 는 호드 의 이익을 위해 해결 해야 할 과제 입니다."
rows["198:1559387530"]="오래전, 내 사람들은 모고 제국의 노예였을 때 우리는 무기를 가지고 다니는 것이 금지되어 있었습니다."
rows["198:1633209783"]="그래서 당신은 진주에게 용기를 준 존재입니다.$b$b이런 용기가 오래전부터 없던 것인데,"
rows["198:1693661970"]="우리가 할 수 있는 모든 것을 해야 합니다. 같은 일이 여기서 일어나지 않도록 해야 합니다. 오아이스에 대한 우리의 조사를 강화해야 합니다. 그리고 이 현상을 원천에서 막아야 합니다. 우리는 다시 교차로에서 이야기 할 것입니다."
rows["198:1735931452"]="우리는 스컬지에 지배를 하고 있습니다. 변화된 전염병의 영향은 적어도 또 한 날 동안 영향을 미칠 것입니다. 하지만 우리는 그 위에 있어야 합니다. 그래서 가능한 한 보일러를 파괴할 것을 확실히 하십시오."
rows["198:175708451"]="이 쳇바퀴처럼 돌아가는 세상을 영원히 부서뜨릴 때가 왔다! 우린 모래시계의 노예가 아니야! 경고한다. 이 위대한 뜻을 거부하는 자, 첫 번째 희생양이 되리라!"
rows["198:1864349228"]="툰데라안의 본질의 거의 남아있는 것은 원자 결합의 타리스마나 안에 저장되어 있습니다. 라그나로스는 그 타리스마나를 결함이 없는 두 조각으로 쪼개었습니다.\010"
rows["198:1875491290"]="- 오...$b$b내가 말해야지 모르지만, 이 도시를 떠나기 위해 돈을 절약하고 있어$b$b넌 모험가야, 알아, 도와줄래?"
rows["198:1936663408"]="이 오그레들은 모래 속에서 앉아서 그들의 삶을 낭비할 이유가 없다고 생각합니다. 그들이 호드에 합류하여 우리로 일할 수 있을 때 말이죠.$B$B우리가 그들을 이용하지 않는다면 누가 이용할까요?"
rows["198:1960052453"]="함께 힘을 모아야만 마지막 도전을 이겨낼 수 있네. 얼음왕관 심연에서 가장 강력한 스컬지 대리인 둘이 왔네. 무시무시한 발키르, 날개를 단 리치 왕의 전령일세!"
rows["198:1960077895"]="그렇다면 역사 에 대한 지식 을 시험 해 보겠습니다. 갈색 피부 의 오크 들 은 3차 전쟁 후 몇 년 후 아제로스 에 처음 나타났으며, 그 때 암흑 포털 포털 포털 이 다시 활성화 되었다."
rows["198:2025530934"]="그들은 워시프에게 보호자이자 지휘자의 역할을 하기 위해 만들어진 고위 오크 집단이었죠.$b$b이제 그들은 매우 잘 훈련된 구축함의 군대가 됐습니다. 가로쉬의 개인 레지온입니다."
rows["198:2046771467"]="날 기억 안나? 스컬지...그들은 당신을 정의로운 계산의 힘으로 만든 모든 것에서, 모든 좋은 것을..."
rows["198:2059037352"]="내 목표는 가능한 한 천천히 일하는 것입니다. 스컬지 우리들을 죽이고, 그 다음에 우리의 시체에 끔찍한 짓을 할 수 있는 큰 창문입니다. "
rows["198:2130771458"]="오크의 손잡이는 이미 강력한 무기이기 때문에 단단한 철의 칼이나 막대를 더해 줄 수 있겠죠. 이제 난 평야 늑대들을 숙제하기 위해 사용하는 손잡이를 적들의 장갑을 깨뜨리는 데도 사용할 수 있습니다."
rows["198:223260169"]="나엔 거미나 움직이는 동상이나 물건을 훔치는 스프리트들이 싫어요. 이 유적에 대해 싫어하는 것들이 많아요. 다행히 안지가 여기 있어 내 예쁜 모습을 그대로 유지하기 위해요!"
rows["198:315103837"]="이 전쟁 은 이기기 위한 싸움 이 아닙니다. 이 전쟁 은 이 전쟁 에 대항 하는 것 이 아니라 이 전쟁 에 대항 하는 것 이다. 이 전쟁 은 이 전쟁 에 승리 할 수 있는 전쟁 이 아닙니다. 이 전쟁 은 이 전쟁 에 대항 하는 것 이 아니라 이 전쟁 에 대항 하는 것 이다."
rows["198:350232164"]="토리움 형제자매 추락 카탈로그:$B$B그 안에 가장 멋진 거래가 있습니다. 모험에 필요한 모든 것! 우리는 심지어 어려운 부품과 물품을 어디서 찾을 수 있는지 보여 줄 것입니다."
rows["198:412835683"]="칼의 교육은 세 개의 무기 마스터에서 찾을 수 있습니다: 언더시티, 사요크 인 명예의 계곡 오그리마, 그리고 Ileda 실버문파스트라이더 스퀘어"
rows["198:527199645"]="여기 블러드하프 마을에는 알케미 트레이너가 없지만 북쪽에는 썬더 블러프에 있는 트레이너가 있습니다."
rows["198:540173257"]="천천히, 친구, 장군이 올 거라고?$B$B이제 내 벽에 트로피가 있습니다! 난 경호를 방해할 것이지만, 하토른 장군을 직접 죽이는 것이 당신 몫이 될 것입니다."
rows["198:57075883"]="저는 여러분들의 회사를 감사하지만, 솔직히 말씀드리자면, 여러분은 제가 하는 것보다 더 많은 경험들을 가지고 있습니다. 포세이큰 이 의 아포테카리움 언더시티."
rows["198:695466004"]="아티시, 수호자의 대참모자. 대참모는 시대를 거쳐 티리스팔의 각 경호자에게 전해졌다. 사르게라스가 부패한 대참모자. 마지막의 대참모자 수호자. 메디브의 대참모자.\010"
rows["198:706000591"]="네퍼셋족이 그의 편에 있습니다.$B$B오리스스는 자신의 반역을 분명히 했습니다.$B$B람카헨은 평화적인 해결책을 찾으려고 노력했지만, 죽음의 날개와 그의 동맹국들과는 평화가 불가능합니다."
rows["198:736881832"]="얼라이언스가 필요한 모든 것을 모아놓은 것 같습니다. 이제 우리는 호드를 기다리고 있습니다. 곧 제가 Tigule & Foror의 아이스크림을 근처에 있는지 보려고 할 것 같습니다."
rows["198:92013091"]="피의 엘프들의 릴라다, 실버문아치발드, 다 언더시티무기의 마스터도 당신을 훈련시켜요"
rows["198:924428149"]="그대가 데피아즈단과의 연결 고리를 찾았다는 말을 전하겠습니다. 에드윈 밴 클리프의 패배로 그들이 와해됐다고 생각한 제가 바보였군요. 그리고 바리안 국왕은 남은 백성 모두에게 본보기로 삼고자 하실 겁니다."
rows["199:103244851"]="크라사랑 파들레피쉬와 그 나쁜 괴물들을 크라사리 강의 가장 큰 수영장에서 찾을 수 있습니다. $b$b벤은 손톱으로 네 지도에 구멍을 뚫고 있다$b$b"
rows["199:1049010221"]="두개골의 덩어리는 불쾌한 냄새가 난다. 아라코아들이 최근에 덩어리에 추가한 것 같군요.\010당신이 필요로 할 것입니다 10 테록의 적들의 후손들을 불러올 시간 손실 스롤"
rows["199:1104769133"]="발린다 스톤하스 대장이 전선에 얼라이언스 그녀는 북쪽 전투장인 스톤헤어스 포스트에 있다.$B$B발린다는 현재 스톤하어스 포스트에 있습니다."
rows["199:110791035"]="고라 주께서는 폭풍의 힘을 손에 넣으셨습니다. 한 마디로 전기를  ⁇ 어 지을 수 있었습니다."
rows["199:1144865671"]="날 기억 안나? 스컬지...그들이 널 한 푼의 힘으로 만들었던 모든 것에서 너를 배제하려고 노력했어"
rows["199:1162897361"]="오그리마에 여행 해, 명예 의 계곡 에 가. 그 곳 에는 남편 과 두 딸 과 함께 살고 있다. 그 들 은 모두 뛰어난 수석 을 하고 있지만, 영 들 은 그 여인이 당신 의 학습 을 가장 잘 이끌 것 이라고 말 한다."
rows["199:120955590"]="이 동굴을 제거하기 위해 모든 것을 시도했습니다. 블랙 올프는 나에게 힘을 주었고, 한 바위도 움직일 수 없습니다. 아마도 내가 성전의 현장에서 전설의 위대한 무기를 빌려주면..."
rows["199:1264426934"]="그래그, 내가 이 말을 견디지 못해! 네가 말하고 생각하면서 우리의 적들이 점점 더 강해지고 있다! 호드!"
rows["199:1314571586"]="날 기억 안나? 스컬지...그들은 당신을 정당한 계산의 힘으로 만든 모든 것에서, 좋은 모든 것을"
rows["199:1549188630"]="내가 지켜보고 있는 건 언 고로를 지켜보는 일이야$b$b또한 저는 테스트를 하고 그 결과를 기록하고 있습니다. 이 테스트는 제가 가장 관심을 갖는 것을 관찰할 수 있게 해줍니다."
rows["199:1712933627"]="난 이 네싱워리 놈을 들었어, 스트랭글스톤밸리에서, 스포츠를 위해 온갖 짐승을 사냥하고 있어$B$B스포츠를 위해, 바보같은 놈이야!"
rows["199:1752543179"]="이시엘은 적의 반대를 예상하고 아웃랜드그래서 우리 경호원이 데려온 거야$B$B우리는 나가들이 보여준 힘이나 숫자에 대한 반대가 있을 것이라고 예상하지 못했습니다."
rows["199:1854379550"]="무역 구역에서 있는 그리폰 루스트를 알고 있나요?$B$B와일드햄어 왜구의 쌍은 그 곳에서 그리폰을 키우고 판매하고 심지어 짐승을 타고 다니는 훈련을 할 수 있습니다."
rows["199:1935088076"]="우리 상황이 그렇게 나쁘지 않다고 생각해요. 곧 모든 것이 바로잡을 것이고, 선웰의 전력은 회복될 겁니다."
rows["199:1949653023"]="이 순간을 오래 기다렸다, 스랄. 네 저주받은 투기장에 던져졌던 매 순간마다... 너 같은 녹색 피부 괴물을 죽일 때마다... 내 머릿속엔 단 하나뿐이었다."
rows["199:201169308"]="오, 내 생각대로 네 조상들은 세계 초기에 거슬러 올라간다. 트롤들의 고대 제국은 위대했다."
rows["199:2080266794"]="숲 송에서 다른 사람들의 목소리를 다시 듣는 것이 좋았습니다. 저는 그들이 부패에 빠지기 전에 이 땅을 보는 마지막 kaldorei가 될 수 있다고 느꼈습니다."
rows["199:2102176195"]="이 순간을 오랫동안 기다렸다, 스랄. 그 저주받은 투기장에 내던져질 때마다... 너 같은 녹색 피부의 괴물을 해치울 때마다... 오로지 한 가지 생각밖에 없었다."
rows["199:273153103"]="스파크, 아드미랄은 당신이 배신한 거 알아 얼라이언스이제 나랑 협조해 줄게 아니면 拳에 맞을 거야"
rows["199:361955264"]="오, 멋지다... 다시 한 번은 아니죠. 이 오크는 여기 있는 게 필요없지만, 그는 바닥을 먹이는 떡쟁이이기 때문에"
rows["199:400320901"]="내가 여기 있는 건 누군가 실망할 때만 신입생들이 흥분하고 가끔은 과장해\010...그것, 그리고 때로는 새로운 메카노 탱크 프로토타입 중 하나가 폭발합니다."
rows["199:448680032"]="아코웨이를 지나서 남동쪽으로 내려가서 포세이큰 더 진보된 기술을 가르쳐 줄 수 있는 사람이죠."
rows["199:525527942"]="처음부터 내 생각이 옳았어. 데솔름은 마지막에 처리할 거요. 우리는 유령의 땅부터 지켜야 하오. 적들이 우리 측면과 후방을 노리고 있는데 다르칸과 싸우는데만 매달릴 수는 없소!"
rows["199:808775233"]="왜 그런 놈의 도움이 필요해? 그 헐프단 블랙바드 (Hulfdan Blackbeard) 의 문제도 충분히 발생해"
rows["199:841578681"]="지금까지 우리는 너무나 많은 실패를 겪었다. 지옥불 성채, 무너진 하늘 마루, 불꽃날개 거점... 캘타스 왕자님께서 일이 이 이상 지연되는 것을 용서치 않을 것이다. 나 역시 완벽한 성공을 원한다!"
rows["199:88639915"]="당신이나 가로쉬가 걱정할 게 없어, 그가 명령한 대로 전염병의 생산을 중단했으니"
rows["199:889119132"]="이 사악하고 작은 짐승이 바로 임프지. 작고 약해서 고기 방패처럼 거의 쓸모가 없어. 물론 공격력도 보잘것없고. 이 짐승은 파티를 지원하는 정도의 용도로 사용하는 게 가장 좋지."
