rows["200:1089378884"]="유일론은 동쪽을 감시하고 있습니다. 불행히도, 그녀의 성전은 의심의 여지가 없습니다.$B$B지금에도 성전은 우리의 도움이 필요해요"
rows["200:1140339622"]="네가 내 가르침을 능가해 왔어. 지구 어머니의 축복으로 가서 썬더 블러프의 중부 고원지역의 북서부 상점에서 타우렌 타른을 찾아라. 그의 지혜로 인도되라."
rows["200:1354374362"]="램 레이싱은 브루페스트의 위대한 전통 중 하나입니다. 더 많은 것을 배우고 싶다면 램 스테이블에서 폴 앰버스틸과 이야기하십시오. 그것은 올바른 핫도그이며 브루페스트 상 토큰을 획득하는 훌륭한 방법이 될 수 있습니다!"
rows["200:1354548117"]="원심력 피조물이 $3486W개 남았도다. 그 피조물을 찾아내어 파괴해야 바로스 클라우드스트라이더의 보호막을 못 쓰게 할 수 있노라. 피조물은 마력의 눈 중간쯤에 있는 가속의 고리에서 찾을 수 있으리라."
rows["200:1484348538"]="< 당신이 당신의  ⁇ 추 조각들을  ⁇ 돌 결정조각에 넣고 레버를 끌어당기는 동안, 기기는 비세계적 소리를 내며 그들을 먼지로 깎아 내린다. 몇 분 후 당신의  ⁇ 은 '입'에서 튀어나온다.>"
rows["200:1636529351"]="너한테는 모르겠지만, 난 정말 망할 곳에 있던 무제한 원료를 그리워!$B$B이 동굴에서  ⁇ 을 수 있는 작은 것에서 거미탄을 만들 수 있을지 모르겠어요!"
rows["200:1749804729"]="폴드링, 훈련을 잘 시켰구나. 역사상 가장 뛰어난 군대를 데려오다니... 바로 내 손에 말이다. 내가 계획한 대로구나! 의도는 아니었겠지만, 희생물을 바쳤으니 합당한 보상이 있으리라."
rows["200:176993046"]="내 조상들이 무덤에서 벗어나게 되는 것을 보고 고통받습니다.$B$B우리는 당신의 힘의 선장 스틸자이의 저주받은 정신을 꺾어야 합니다. 이 신성한 땅을 통해 그의 카라반을 어리석은 방법으로 이끌었던 사람입니다."
rows["200:1825224562"]="아주 좋은 장비가 있어 정말 멋지다 오크의 집에 가 오그리마 오크들에게 줄게 될 것 하나, 그들은 아름다운 죽음의 도구를 만들어냅니다."
rows["200:1854155844"]="만년만에 드디어 자유로웠어요, 행복한 날입니다. 정말 행복한 날입니다. 최고의 파티가 필요할 것입니다."
rows["200:1875188254"]="상황이 어떻게 돌아가고 있는지 모르겠소? 눈을 크게 뜨시오. 보려고 하면 보일 거요. 대체 이 새 동맹은 뭐지? 우리가 오랜 동맹을 배신한 이유가 고작 공공의 적과 친해지기 위해서란 말이오?"
rows["200:1896160671"]="방사능이?$B$B아니, 걱정할 필요 없어, 요즘 사람들은 믿는 게 뭐지$B$B우리 운영에 대해 어떻게 생각하세요?"
rows["200:1999936643"]="오크들이 의심할 수 있는 방해가 될 수도 있고, 그런 경우 오크들은 우리를 적극적으로 찾아보게 될 수도 있습니다."
rows["200:2022407060"]="믿을 수 없는 것, 당신의 약물은 내 지식과 경쟁하는 지식을 보여줍니다. 더 많은 훈련을 할 수는 없지만,"
rows["200:2029816925"]="아름다우신 여사제님, 제가 말씀드릴 내용이 심기를 불편하게 해드릴지도 모르겠군요. 이 서판은 나가의 통신 수단입니다. 나가의 지도자인 장군 스리스티즈가 부하들에게 섬의 나머지 지역을 무력으로 점령하라고 명령한 내용이 담겨 있습니다."
rows["200:2063045653"]="나가들은 자신의 용도로 물을 모두 펌프하고 있고, 그 결과 전체 종들이 멸종되고 있습니다.$B$B우리가 빨리 뭔가를 하지 않으면, 이 죽어가는 세상에서 남은 생명은 영원히 사라질 것입니다."
rows["200:210796840"]="그리머 스톤브랜드는 도망친 놈에 대해 얘기할 거야 하지만 그는 여전히 가장 좋은 어업자 중 한 명이야"
rows["200:250236519"]="이 성의 작은 부족 중 하나가 이런 물건을 보관하는 것은 매우 드물다."
rows["200:289795140"]="첫 번째 도전은 당신이 아르헨티나 전투용으로 올라갈 필요가 있습니다. 이 콜리세움의 벽에 따라 이 마운트를 찾을 수 있습니다.$b$b제발, 배틀워그에 올라와 나와 얘기해, 그러면 계속할 수 있어요."
rows["200:335017008"]="이 곳을 보세요, 생태계가 고립되어 있고 모든 시간대에서 분리되어 있습니다.$b$b저같은 사람이 놀라게 되는 건 드물지 않아."
rows["200:345957215"]="내가 누군지 아세요?! 나는 매우 중요한 사람이에요. 당신은 나를 스컬지로부터 보호해야 하고, 무의미한 대화로 미루어서는 안되죠!$B$B난 전투가 아니야, 넌 싸운다"
rows["200:408091937"]="날 기억 안나? 스컬지...그들은 당신을 정당한 계산의 힘으로 만든 모든 것에서, 모든 좋은 것을..."
rows["200:484714315"]="악명 높은 범죄자와 악의적인 동물들을 위한 상금이 여기에 게시되어 있습니다. 지금 여기에 게시된 상금을 추구하는 것은 너무 위험할 것입니다."
rows["200:510599071"]="전쟁에서 죽은 사람들을 기리기 위해 기념관을 세우고 있습니다. 우리가 승리를 위해 희생한 것을 잊지 않는 것이 중요합니다.$B$B우리는 $3275w 이 목표를 달성하는 비율이"
rows["200:518764951"]="행성과 생명체를 해체해 금속, 암석, 기체 등의 기본적인 요소로 되돌리는 작업을 뜻합니다. 이후에, 각 요소를 초기 행성 청사진에 맞게 재구성하는 절차가 뒤따릅니다."
rows["200:605773725"]="스팀위들 전투 경로를 들어봤어?\010아레나 조직원들이 가젯잔에서 아레나 팀 차터를 판매하고 있고 나그란드와 블레이드즈 엣지 산맥의 아레나 밖에서도 있습니다."
rows["200:623461550"]="바로크 사우르파랑을 만났던 때를 얘기해봤나? 제가 그에게 가슴 근육의 거대한 부분을 서명하라고 요청했었는데, 그는 저를 뒤로 돌려주었고, 그래서 저는 가끔은 이제 그 일을 잊고 있습니다."
rows["200:658793882"]="얼마 지나지 않아, 갑자기 그들 앞에 눈이 쏟아지더니 요르문가르 크기만한 베라누스가 그들 앞에 나타났습니다... 그들이 반항하기도 전에 그들 중 한 명을 꿀꺽 삼켜 버렸습니다."
rows["200:692709058"]="제 애완용 개구리도 찾을 수 없어,  ⁇ jub 그녀는 다크 아이언 알을 좋아해요, 그밖에 안 마시고요, 하지만 너무 힘들어요!$B$B그녀가 돌아오길 바랄까..."
rows["200:694326014"]="보르고스는 그레이트 포지에서 일했으나, 재건이 끝나자 스톰윈드로 이사한 것으로 전해졌다."
rows["200:723184379"]="나라루에 접근하는 동안 진정성 있는 빛이 가득 차 있습니다. 느린 음악적 윙크는 여러분의 마음 속에 울려 퍼져 있습니다. 단 한 마디도 나오지 않더라도 안전에 대한 확신을 느낍니다."
rows["200:768984813"]="이 옷은 내 눈에서 파란 것을 드러내지 않아야지, 난 많은 기술을 가지고 있어"
rows["200:790549304"]="빛의 형제교회는 무엇인가? 우리는 모두 아르헨트 십자군의 핵심 회원입니다. 도덕, 죄책감 그리고 쓸모없는 인간 감정에 의해 통제되지 않는 아르헨트 십자인군의 구성원입니다."
rows["200:917837061"]="글리크스와는 합의했지, 그는 나를 공급하고 난 그를 부유하게 해 주겠소"
rows["200:944841025"]="부탁한 건 매우 친절하지만, 우리가 필요한 실크 배반을 모두 수집한 것 같습니다."
rows["200:953426855"]="< 당신이 당신의  ⁇ 돌  ⁇ 돌  ⁇ 돌 에  ⁇ 어  ⁇ 을  ⁇ 을 때, 기기는 비세계적 인 소리를 내며 그들을 먼지로  ⁇ 니다. 몇 분 후 당신의  ⁇ 돌이 '입'에서 튀어나옵니다.>"
rows["200:991016774"]="물론, 제 방법들은 의심스럽습니다. 제가 언급할 때, 그 \"그리파\"는 사기꾼으로 드러났어요. 당신은 평화를 유지해야만 했고, 그 간단한 작업에 실패했습니다."
rows["200:999866008"]="모가 우리의 방어력을 깨고...$B$B그들의 자이드 군대는 우리가 억제할 수 없을 정도로 많았습니다.$B$B저는 체를 돌볼 수 있도록 남아있었지만 다른 사람들은 마지막 항의를 위해 도시로 물러났다."
rows["201:1017516030"]="훈련에 와서 나랑 같이 하는 용기 때문에 재미없어요. 포세이큰 그 분들은 기본적인 것을 가르쳐 줄 수 있습니다."
rows["201:1152186752"]="형제 여러분, 이 때가 왔습니다. 우리는 적을 얼음 다그어 패스를 통과하도록 허용해서는 안 됩니다. 우리 중 일부는 분명 멸망할 것입니다. 그러나 여러분 중 누가 이 의무에서 회피 할 수 있습니까? 이 영광? 계속하세요! 호드"
rows["201:1167918098"]="제가 마직 쿼터에서 처음 가게를 세웠지만, 그곳은 꽤나 험난했습니다. 이 일은 확실히 개선된 일이었습니다. 제가 이사를 했음에도 불구하고 여전히 저를 추적하는 몇몇 끈끈한 학생을 제외하고는요."
rows["201:1298550611"]="바람 트레이더 마리드, 나더 드레이크에 대한 더 많은 정보를 가지고 돌아왔어요. 저는 당신의 비즈니스 파트너가 될 준비가 되어 있습니다."
rows["201:1440882587"]="만약 당신이 스카이게르드와 잘 어울리면, 스케틸 산맥에 있는 블랙윈드 착륙 기지로 직접 비행을 할 수 있습니다.$B$B내 아름다운 윗선선을 좋아해?"
rows["201:1443587000"]="심지어 이 도시를 보호하는 벽들처럼 차가운 벽들 속에서도, 평화와 평온을 찾을 수 있습니다."
rows["201:1450179582"]="마지막 순위는 여기 있습니다!$B$B ⁇ : $2200w$B카에른: $2201w$B실바나스: $2202w$B전체 호드: $2207w$B$B볼바르: $2203w$B마그니: $2204w$B타이란데: $2205w$B전체 얼라이언스: $2206w$B$B호드은 가장 인기있는 영웅을 가지고 있습니다!"
rows["201:1461760133"]="스톰후프는 북풍을 그 영역의 중심에 함락시키고 거의 그의 음모를 성공시켰다. 그러나 북풍은 스톰후프의 배신에서 살아남아 타타카를 그의 침략에 대한 처벌으로 집행했다."
rows["201:1599372990"]="난 네가 딱딱하다고 생각하겠지 아나마 내가 널 위해 뭔가 가질 수 있을거야$b$b오, 그리고 좋은 하루를 보내세요."
rows["201:1621969532"]="존경하는 귀부인, 그대는 나처럼 스컬지와 싸워본 경험이 없소. 그래서 우리 여군주께서는 내게 부인을 도와 다르칸을 물리치라 하신 거요. 그러니까 내 말을 잘 듣고 신중히 한번 생각해 보시오."
rows["201:1668726790"]="가끔씩 우리가 승리와 우리를 막는 독단적인 오크를 만나게 될 겁니다. 클로포름은 그런 상황에서 가장 잘 사용되죠."
rows["201:166952073"]="달옷  ⁇ 을 하는 데 있어서의 실력을 잊는 것은 가볍게 할 수 있는 일이 아닙니다. 만약 당신이 그것을 포기하기로 결정한다면, 달옷  ⁇ 이 만들어야 하는 모든 레시피를 잊어버릴 것입니다!$b$b- 확실해?\010"
rows["201:1677941981"]=" ⁇ 루나가 당신의 비전을 말해줬어요. 매우 혼란스럽습니다. 우리 사랑하는 고대인이 되살아난 자년일까요?$B$B더 많은 정보를 수집해 주세요"
rows["201:1788538567"]="남편은 며칠 동안 사라졌어요. 우리는 함께 순례를 했습니다.$B$B이 모든 걱정은 내가 실제로 해야 할 것보다 더 자주 마나 결정에  ⁇ 게 해 주었습니다."
rows["201:1820492530"]="네 가죽에 대한 이해는 내보다 깊어졌어 아마 네가 Aayndia Floralwind를 방문해야 할 것 이다 잿빛 골짜기 숲의 아스트라나르 마을. 그녀는 너의 재능의 학생에게 제공하는 많은 지식을 가지고 있다."
rows["201:1832136744"]="2년마다 경쟁의 영들이 더욱 열렬해지고... 그리고 지금 그 시간입니다! 우리는 이 타바드를 싸움을 위해 대전 현장에 입습니다."
rows["201:1857518036"]="난 널 알아냈어, 넌 유방 섬 출신이야?$b$b판다리아에 있는게 이상하지 않나요?$b$b이 곳은 전설일 뿐이라고 생각했는데, 실제로 존재한다는 건 믿기지 않아요!"
rows["201:1858518275"]="우리가 크레이터에 머무르면서, 다다나가 여기 곳곳에서 자라는 큰 피꽃잎을 좋아했습니다.$B$B그녀가 간식을 즐겨 먹으면 좋겠군"
rows["201:1864234165"]="스펠파이어 테일러링에 대한 실력을 잊는 것은 가볍게 할 수 있는 일이 아닙니다. 만약 당신이 그것을 포기하기로 결정한다면, 당신은 스펠파이어 테일러링을 만들어야 하는 모든 레시피를 잊을 것입니다!$b$b- 확실해?"
rows["201:1879930263"]="넌 정말 훌륭한 마법사야 이제 네가 앞으로 나아갈 시간이야 난 네가 위층에 있는 지블 틸레푸스와 얘기해줘"
rows["201:1895811398"]="안녕하세요! 이 음악 악기 중 가장 훌륭한 로데론마스터와 그의 손님들을 위해 공연하는 것이 영광입니다. 관객들 가운데 앉으세요. 곧 공연이 시작될 것으로 들었어요."
rows["201:1899077253"]="넌 내게서 새로운 것을 배울 수 없어 이미 너무 많은 것을 알고 있어 더 많은 훈련을 원한다면 썬더 블러프의 중부 고원 북서부 상점의 타우렌 우나와 이야기해봐"
rows["201:1956226598"]="로르테마르는 썬더 섬을 끝낼 때 공격할 준비가 돼 있고, 반시 여왕은 변명도 필요없지만 둘 다 바다를 건너가다."
rows["201:316317657"]="진정하지 않으면 날아가게 될 거야, 좀 편리하다고 생각 안되니?"
rows["201:329696955"]="실디나이어는 우리 사랑하는 도시를 지키는 많은 세티넬들을 훈련시켰어요."
rows["201:333816903"]="그럼 아마 아레나가 너한테 맞지 않을 거야? 네. 비스트온은 첫 시즌의 갑옷이 남아있었고, 어떻게든 제거해야 해"
rows["201:34030956"]="오타 웬의 눈은 이미 노예화되어서 더 이상 빛나는데, 당신의 제안에 따라 더더톨의 막대기의 힘이 당신의 몸으로 흘러들어오고 furbolg에 닿는 것을 느낄 수 있습니다.$B$B일어나자?"
rows["201:368841055"]="내 형제들을 죽이고, 그들의 피를 내 조상들의 거룩한 땅에 흘렸어!$B$B내가 사슬을 잡지 않았다면, 지금 널 죽일 거야!$B$B<노인 야롱은 폭발로 쓰러져 심하게 숨쉬고 있습니다.>"
rows["201:477257989"]="예, 그 이름. 잘... 좋은 이름은, 좋은 뜻과 마찬가지로, 많은 행동으로 얻으며, 한 가지로 잃어 버립니다. 어떻게 또는 왜, 말할 필요도 없습니다."
rows["201:492615772"]="이제 입 다물고 당신의 일에 충실하시오. 그렇지 않으면 폴드링 경과 그의 기사들에게 당신이 더는 우호적이 아니라는 사실을 알릴 것이오. 당신이 죗값을 치르는 모습을 본다면 그분께서 매우 기뻐하시겠지."
rows["201:514842387"]="그렇다면 역사 에 대한 지식 을 시험 해 보겠습니다. 스탈반 미스트만틀 은 교직원 으로 일 하면서 학생 중 한 명 인 티로아라는 젊은 여자 에게 집착 하게 되었습니다. 그 여동생 의 이름 은 무엇 이었습니까?"
rows["201:536807963"]="그 귀족 사냥꾼들은 스스로 생존을 위한 방법을 찾았습니다. 불은 열쇠였습니다. 그들은 땅에서 기름을 추출했습니다."
rows["201:541346795"]="당신 의 조사를 감사 합니다. 하지만 전쟁에 필요한 울타리 가닥은 이미 가지고 있습니다."
rows["201:582342111"]="모가들은 혼란을 일으키기 위해 신성 벨을 만들었지만 판다렌은 그 혼돈의 반향을 완벽한 조화로 바꾸기 위해 특별한 망트를 만들었습니다."
rows["201:632393864"]="지가 널 보냈어? 제이는 좋아! 그녀는 행복한 얼굴이야. 하지만 미친 맥주가, 그는 큰 비만 건조한 얼굴이 나빠!$b$b내 물 친구들을 더 잘 만들 수 있어?"
rows["201:662511058"]="우리는 울담의 비밀을 지키는 자들이야 모래 밑에, 피라미드 밑에 위대한 힘이 존재합니다.$B$B전 세계를 만들고 파괴할 수 있는 힘.$B$B하지만 그는 우리 없이 이 힘을 얻을 수 없습니다."
rows["201:699040064"]="아즈하라에서 보낸 시간은 우리 최고의 날과 영광의 날들 중 하나가 아니었지만 우리는 여전히 젊고, 혈관이 여전히 흐르고 있습니다."
rows["201:757710561"]="그래, 내가 그를 구하러 올 거야$B$B하지만 그의 작은 세계 중심 영웅의 조각에 빠지지 마요. 그는 단지 관심을 좋아해요. 맹세하지만, 그는 다음 측면이 될 것이라고 생각하죠. 그것은 웃기죠."
rows["201:791743428"]="화산이 폭발하는 동안 당신의 친구들은 모두 무역 왕자 갈리위크스가 포로로 잡혔습니다.$B$B우리가 그들을 구하고 이 섬에서 벗어나려면 빨리 얼라이언스를 처리해야 합니다."
rows["201:820676851"]="전투에서 숨어있으면 손가락을 흔들고 싶으면 마기스 스파크맨틀과 이야기해"
rows["201:842725147"]="언더버elly에서 3가지로 빠져나갑니다. 동쪽과 서쪽으로 올라가는 램프와 Dalaran의 바닥에서 나오는 터널$B$B터널을 타기 전에 비행할 수 있는지 확인해"
rows["201:863333171"]="창의적 인 능력 은 종종 당신 의 편 에 싸움을 이끌어 낼 수 있습니다.$b$b우리 주변 숲에서 온 식물들을 이용해 이 약을 만들었습니다."
rows["201:895822848"]="우리가 다시 자유의 오그로로 살아야 한다면 그루일의 아들들은 패배해야 합니다!$B$B우리가 조용히 일해야 하지만 빠르게 해야만 우리의 지하 저항이 성공할 수 있는 기회가 있다면"
rows["201:916731676"]="그 여자랑 대화를 하려고 하는 건 안 보냐?$B$B최고의 음료만 공급해 주죠."
rows["202:1151541519"]="검은 용의 존재가 신경을 쓰나요?$B$B좋은데, 그럴 거야, 이 용들도 긴장해 버렸어, 하지만 그들은 고대 덕에 집착해$B$B멍청이들"
rows["202:1344505445"]="저는 아저렘스트에 있는 야생동물을 산책으로 분류하고 있었는데 갑자기...\010무조는 손으로 폭발을 모방한다\010내 인생에서 이렇게 큰 폭발을 들은 적이 없다고 생각합니다!"
rows["202:1430043881"]="리코는 내가 만난 가장 성숙한 똥구멍이야$b$b쇼키아가 보여준 만큼 나쁘지 않은데, 사실 그는 좀 귀여운 것 같아요"
rows["202:1475061953"]="날 기억 안나? 스컬지...그들은 당신을 정당한 계산의 힘으로 만든 모든 것에서 당신을 배제하려고 노력했습니다."
rows["202:1573129760"]="전력으로 된 루비 드레이크는 순교를 수행 할 수 있습니다. 그것은 짧은 시간 동안 모든 적대적인 마술을 루비 드레이크로 전환함으로써 우호적인 목표를 보호합니다."
rows["202:1633930080"]="당신은 당신의 왕권을 보내고 '눈에 돌고 shoulder' 그리고 그 그림자를 두려워, tha 시간 올 때와 당신의 혈액이 천천히 배출' 될 때, 당신은 정확히 누가 화살표를 발사하는 것을 알 것입니다\010"
rows["202:1639278198"]="<길 옆에서 발견한 불행한 군인은 긴 칼로 절단됐습니다. 시신을 뒤집어 놓으면 치아 흔적을 발견할 수 있습니다.>$B$B<야생동물들이 이런 짓을 할 수 있었을까?> "
rows["202:1658674656"]="...이건 편리한 장치일 수도 있기 때문에 2000하지만 다른 한편으로는, 우리가 보고 싶은 마지막 것은  ⁇  모로흐의 산들이 붕괴하고 무너지는 것입니다. 아이언포지.\010"
rows["202:1733931727"]="아이사? 내가 그녀에게 뭐라고 해야 할지 모르겠어요. 그녀가 아름답다고 말해야 할까요? 아니면 그렇게 무서운 것 같을까요?"
rows["202:1736677764"]="와일드햄어는 항상 샤머니즘을 받아들였지만 지상의 반지의 일원으로 바다 밑에 있는 건 어떨까요?\010한 해 전 그 말을 믿기 위해서는 몇 가지 이상의  ⁇ 카드가 필요했을 겁니다."
rows["202:1801060099"]="저는 갈라나를 특별히 초보적인 훈련을 위해 고용했습니다. 가서 그녀와 이야기하세요. 이 가게는 효율적이고 효과적으로 운영될 예정이며, 고객들까지 모두 존중하기를 기대합니다."
rows["202:1808372919"]="난 많은 것을 알고 있지만, 당신의 지식은 내 지식보다 더 많은 것을 알고 있습니다. 마법사가 자신의 기술을 더 향상시키고 싶어하는 사람들은"
rows["202:1853779223"]="난 알렉스트라자 님의 가호를 받아 기억도 나지 않을 만큼 기나긴 시간 동안 이 제단을 지켜왔습니다. 어둠이 짙게 드리운 때에 난 실패했지요... 그 저주받은 죽음의 기사... 블러드베인의 발밑에 쓰러졌답니다."
rows["202:1970694516"]="안녕하세요$B$B<그 작은 소녀는 당신을 쳐다보고 있습니다.>$B$B상자와 얘기하는 걸 들었어$B$B네, 운이 좋군. 여기 일어나는 모든 일을 듣고 있거든."
rows["202:2072090032"]="다르나서스에 도착한 행운을 누리고 있습니다. 우리 훈련자들 중 조카스테 같은 성실한 사냥꾼을 찾을 수 있습니다."
rows["202:24251643"]="북쪽의 큰 도시 썬더 블러프에 풍자 라이더 마스터가 있습니다. 썬더 블러프의 밑에서 꼭대기에 엘리베이터를 타고 더 자세한 지침을 요청하십시오."
rows["202:404053245"]="만약 당신이 분노 카드 팩을 완성한다면 더 큰 복수카드가 주어질 것입니다. 이 카드를 들고 있는 동안 당신을 공격하는 사람은"
rows["202:423511682"]="피 엘프들에게 계속 봉사하는 것은 우리 생존에 가장 중요합니다.$B$B만약 당신이 일하기 위해 준비되면, 시작하자."
rows["202:452611543"]="어머... 어떻게든 다른 쪽으로 갔어요.$b$b당신이 전에 없었던 곳으로 포털을 만드는 것은 쉬운 일이 아닙니다.$b$b하지만, 만약 그것이 쉬운 일이라면, 모든 사람들이 그렇게 할 것입니다."
rows["202:464076542"]="타우라조 캠프에서 난 어린 사냥꾼들을 야생의 길에서 훈련시켰습니다.$B$B지금 우리는 그런 고급스러움을 누리지 않습니다. 우리 문앞에 있는 적과 전투에서 기술을 배울 수 있어야 합니다."
rows["202:500763173"]="\"사람에게 물고기를 줘서 하루 동안 먹여주고, 낚시를 가르쳐줘서 평생 먹여줬다\"라는 말이 있습니다. 물론, 그 물고기를 요리하고 싶어서 그런게 제가 하는 일입니다."
rows["202:505668773"]="- 네?$B$B로라크스가 웃는다$B$B의심스러운 말이지$B$B난 이 폐허에 서 꿈꾸고 그 불행한 도둑을 잡을 날을 꿈꾸고$B$B우린 협정을 했었는데, 그는 협정을 깨고 배신했지"
rows["202:590376467"]="고맙습니다 $p저  ⁇ 한 자이드 마녀로부터 날 구해줬다는 거야$b$b지금에도 다리가 딱딱해져 있어 군대를 지휘할 수 있지만, 전투에서 쓸모가 없을 것 같아"
rows["202:595592963"]="(성어대!성어대 혐오 증오 증오...) 상관없다. 한 눈이 닫으면 다른 눈이 열린다. (주님 모든 것을 보시고, 주님께서 모든 것을 아십니다!) 우리는 적의 마음을 알 수 있을 것입니다. 왜냐하면 그들은 약하기 때문입니다. 눈. 지금."
rows["202:596561548"]="스톰윈드에서 마법을 훈련시키는 사람이 없지 \010마지스퀘어에서 악마 활동이 목격됐지만"
rows["202:620904297"]="에스신아에게 기도하는 것은 응답되지 않고 있습니다. 라그나로스의 불타는 하사들이 우리를 가장자리에 몰아넣었습니다. 그들이 여기서 멈추지 않으면 세계 나무는 화염의 한가운데에 줄기보다 조금 더 이상 될 것입니다."
rows["202:739703566"]="샤렌은 도시 안에서 동물들을 돌보고 그들의 주인들이 그들의 삶을 계속 망쳐가는 동안 그들을 미쳐버리는 것을 막고 있습니다. 그녀는 포경관의 홀 바로 바깥에 있는 파스트라이더스 광장에서 서 있습니다."
rows["202:771018115"]="어떻게 훈련 부탁할 수 있겠지?  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어  ⁇ 어"
rows["202:791544640"]="이제 우리가 이웃이 된 후, 내가 당신에게 가장 좋은 선물을 줄 것을 결정했습니다. 이웃은 거의 누구에게나 줄 수 있습니다! 나는 당신이 내 소중한 야크 중 하나를 줄 것입니다!"
rows["202:839355997"]="내 능력에 대한 당신의 신뢰에 대해 칭찬 받았지만, 당신을 가르치는 것은 내 능력보다 더 이상입니다. 당신은 다르나서스에서 공예인 테라스로 가서 밤 엘프 아이네틸과 이야기해야합니다. 그녀는 당신을 도울 수 있습니다."
rows["202:932077990"]="가장 긴장한 항공선을 운반합니다 아제로스그녀는 두 개의 소총과 도시를 격파시킬 충분한 폭탄을 장착했습니다. 그녀의 그림자는 군대를 격파하기에 충분했습니다.$b$b- 물론 맞아요!"
rows["202:985142836"]="스컬지와 아만니 트롤 같은 외부 장애물을 극복하기 전에 우리는 내부의 장애물을 극복해야 합니다. 비참한 사람들은 오랫동안 괴롭혔습니다. 우리는 그들을 이길 때가 되었습니다."
rows["203:1040103292"]="하지만 이 사실을 알고, 호드 IS가 이 사실을 잊고 있는 지도자들 중 한 명이라도, 저는 여러분들과 함께 남아 Vol'jin이 돌아오기 전까지 여러분의 선출된 지도자들에게 힘을 줄 것입니다."
rows["203:1148988454"]="죽음의 날개가 돌아왔어, 그는 그림 배톨과 고원을 점령했고, 그를 막기에는 거의 힘이 없어서$B$B곧 여왕이 도착하고 함께 지구워더를 대신해 줄 것입니다."
rows["203:1182952401"]="이살레이 말해주고 있잖아, 하피들이 용들과 동맹을 맺고 있다고.$B$B ⁇ 루나에게 일 좀 도와줘요 "
rows["203:1232372846"]="일리니아 문파이어, 밤 엘프 무기 마스터 다르나서스, 또는 Buliwyf, Timberline 무기의 왜기 무기 마스터 아이언포지, 손잡이 무기를 사용하는 훈련을 할 수 있습니다."
rows["203:1242444245"]="날 보고 계신 분들께 감사해요 오늘 우리가 모두 떨어질 날이에요 호드- 검을 위해!"
rows["203:126967225"]=" ⁇  발다르는 알테락 계곡에서 가장 강한 얼라이언스 권력 지점이다.  ⁇  발다르는 계곡의 북쪽 끝에 자리 잡고 있으며 남쪽으로 모든 진전을 위한 발판지이다.$B$B ⁇  발다르는 건전하다"
rows["203:1270299430"]="항로... 보급품... 지겹도록 들었더니 귀에 딱지가 앉을 지경이군요! 필요한 건 호드의 투쟁 정신뿐입니다, 사울팽! 이 얼어붙은 황무지에 요새까지 굳건히 세운 이상 그 무엇도 우릴 막을 순 없습니다!"
rows["203:1320892710"]="사냥은 좋은 곳이고 새들은 대각층에서 부르고 짐승들이 아래쪽 어두운 곳에서 울고 있습니다.$b$b그리고 우리는 그들을 통제합니다.$b$b사냥꾼으로서 우리의 의무가기도 하지만, 좋은 스포츠이기도 합니다."
rows["203:1415761307"]="허브, 허브, hmmm, 여기 보도록 해. 아예, 여기 있습니다. 지금까지 우리는 $2048w의 $2047w의 목마귀, $2053w의 $2055w의 보라색 로투스, $2057w의 $2058w의 아타스 눈물을 축적했습니다."
rows["203:1473193733"]="내가 너보다 더 좋아하는 영들이 있잖아 아직 그들의 부르짖음을 듣지 못했지만 넌 그들의 교훈을 잘 배웠어"
rows["203:1497004474"]="이제 여러분들의 역사에 대한 지식을 시험해 보겠습니다. 얼마 전 이 약한  ⁇ 다라리 트롤은 거북이를 숙달하려고 노력했습니다. 거대 섬으로 여행했지만, 그 탐구에서 죽었습니다."
rows["203:1548524483"]="고장한 참전용사에게는 평화로운 환경에 익숙해지기 어려울 수 있지만, 그것은 우리의 의무입니다. 이 마을 사람들은 전쟁을 갈망하지 않습니다."
rows["203:1664296920"]="Xarodi 시장은 다시 열렸어요 사피어들이 늘고 있습니다. 은이 떨어지고 있습니다. 금이 상승하고 있습니다. 다이아몬드는 안정적으로 유지됩니다.$B$B네 동생은 지난주 빌린 홀로큐브를 돌려달라고 부탁해"
rows["203:1669200199"]="황제 비지어 조르'록은 |cFFFF0000|Hspell:122740|h[변경]|h|r Mantid 제국으로 싸우도록 당신을 구했다! 전 동맹국들은 당신의 건강을 50%로 낮추어야 해 황제의 지배로부터 해방시켜야 한다!"
rows["203:1799335305"]="이 용들은 장난을 치지 않아, 이 모든 똥구리는 무슨 짓을 하는지 모르겠어$B$B우리들은 괜찮을 거야, 우리들 이 일을 할 수 있어"
rows["203:1865072512"]="8,000 년 동안, 이 刃 들 의 몇 개 만이 만들어졌다. 그 刃 들 은 힘 과 외모 로 독특 하다."
rows["203:206821673"]="죽음 날개가 메일스트롬에서 올라오자, 어두운 분노의 파도가 잔다라리 수도에 충돌했습니다. 그 땅 의 척추는 두 가지로 갈라졌고 곧 도시 와 그 모든 부들이 굶주린 바다로 몰려들기 시작 했습니다."
rows["203:2145075329"]="<벤은 머리를 긁는다>$b$b 방향에 대해서는 내가 잘 모르겠지만, 레드벨리 만다린은 여기와 타운롱 스텝의 니우자오 현장에서 있다고 생각합니다. $b$b<벤은 지도에 있는 일반적인 지역을 둘러싸고 있습니다.>$b$b"
rows["203:368013023"]="쉐도웨이브 스티어링에 대한 실력을 잊는 것은 가볍게 할 수 있는 일이 아닙니다. 만약 당신이 그것을 포기하기로 결정한다면 당신은 셰도웨이브 테이어링이 만들어야 하는 모든 레시피를 잊어버릴 것입니다!$b$b- 확실해?\010"
rows["203:409947492"]="오, 저는 완벽하게 이해합니다. 나는 눈을 가지고 있습니다. 하지만 판다리아는 당신이 왔던 땅과 같지 않습니다. 그것은 살아 숨 쉬고 있습니다. 당신은 여기에 어떤 종류의 에너지를 가져온 것을 조심해야합니다. 이제 그 무기를 멀리!"
rows["203:436030817"]="내가 앉아 있을 수 없었어 스톰윈드 내 사람들의 피가 흘리는 동안 계속해!$B$B판다리아는 우리에게 많은 것을 가르쳐야 합니다.$B$B그리고 내가 찾기를 목표로 하고 있습니다."
rows["203:570674813"]="우리 마지막이자 가장 위대한 황제 샤오하오를 알고 싶으세요? 친구, 그의 모험을 모두 이야기할 시간이 없어요. 하지만 그의 행동들은 10천년 전까지 오늘날까지 울려 퍼져 있습니다."
rows["203:869660638"]=" ⁇ 다라리 백성은 그들의 왕에게 도움을 요청하였으나,  ⁇ 다라리가 한 명만 그들을 도울 수 있었다. 예언자 툴과 그의 왕이 무사히 앉아 있을 때 그가 모집한 강력한 함대들"
rows["203:918214917"]="오, 내게 신경 쓰지 마, 난 그냥 사신이야. 죽음의 스터커의 리더는 확실히 이 문에 서서"
rows["204:1059328986"]="마스터스 게이트에서 중요한 건 뭘 알아내려고 하는 거야$B$B이 망할 놈들이 잘 안하고 있는 건 알지만"
rows["204:1097539099"]="오그리마의 회전과 회전들은 침입자들을 방해하기 위해 설계되어 있습니다. 이 작은 기둥 중 하나가 얼마나 빨리 여기 사라지는지를 상상할 수 있습니까?"
rows["204:1125440780"]="여행자님, 켄라리온 포드의 벽 안에 있는 한,$B$B지체 보호 구역을 떠날 때 조심하세요. 최근에는 실리티드가 몰려오고 있습니다."
rows["204:1150770959"]="고드프리는 왕의 고통에 대해 알게 되면서  ⁇ 쳤다고 전해졌어요."
rows["204:1265530677"]="이 전쟁에서 한 인치도 내놓을 수 없어 밤낮으로 새로운 장갑을 만들고 구제할 수 있는 모든 것을 고치며 다른 일에 시간이 없어"
rows["204:127372698"]="이 자료를 통해 빛그래서 익숙해 보이는군. 이 운명인가? 운명인가? 아라토르, 네 아빠와 나는 가장 친한 친구였어. 내가 그를 건강하게 유지했어..."
rows["204:1334850440"]="마지막 순위는 여기 있습니다!$B$B ⁇ : $2200w$B카에른: $2201w$B실바나스: $2202w$B전체 호드: $2207w$B$B볼바르: $2203w$B마그니: $2204w$B타이란데: $2205w$B전체 얼라이언스: $2206w$B$B얼라이언스은 가장 인기있는 영웅을 가지고 있습니다!"
rows["204:137031011"]="주목. 이자가 훈련교관 라주비어스이다. 켈투자드는 모든 죽음의 기사를 교육하는 임무를 직접 이자에게 맡겼지. 그의 기술은 워낙 뛰어나서 직접 가르친 수제자 정도만이 겨우 그에게 맞서 싸울 수 있다고 하더군."
rows["204:1393451672"]="부족의 친구들, 우리 도시는 공격당하고 있습니다! 무기를 들고 우리의 집을 방어하십시오. 만약 당신이 전투를 원하지 않는다면, 날씨 브레이커를 잡고"
rows["204:1446520756"]="드르파 드르파는 가끔씩 마을로 돌아다니며 우리에게 이상한 기기를 팔려고 합니다."
rows["204:148505255"]="하지만, 나는 내 분노가 날 가려서 급증하는 것을 허용하고 있었다는 것을 두려워한다. Thrall은 그것이 무엇인 호드를 만들기 위해 자신을 바쳤다, 그래서 나는 그것을 떠나고 싶은 욕심이 없습니다."
rows["204:1592261837"]="니우자오, 검은 황소, 벽 너머의 적들을 견고하게 견디고 있습니다.$B$B그는 침입하는 마티드를 물리치기 위해 절실히 도움이 필요합니다.$B$B도움이 되고 싶다면 타운롱 스텝의 신전으로 서쪽으로 이동하세요."
rows["204:1608645887"]="만약 당신이 에레멘탈 카드 덱을 완성할 수 있다면, 당신은 더 큰 마블스트롬의 암흑 달 카드를 받게 될 것입니다. 이 카드는 때때로 당신이 싸우고 있는 적에 큰 피해를 끼칠 것입니다."
rows["204:1653781339"]="이 두 세계 사이의 격차를 만들어낸 데프홀름의 모든 종은 아제로스 만약 우리가 세계 기둥을 다시 함께 하지 않는다면"
rows["204:1766883427"]="부족들이 모여들었습니다. 당신은 하나의 힘이 아니라 트롤 제국 전체의 합동 힘과 직면합니다! 아제로스 다시 한번, 너희들 중 소수들은 고통에 시달릴 거야"
rows["204:1782922981"]="<너의 놀라움으로, 랩터 새끼는 당신과 소통할 수 있습니다.>$B$B손가락 끝은 무섭고 둥글다. 그래서 전투에 사용해야 할 다른 도구를 가지고 다니는 건가요?$B$B정말 흥미롭네요"
rows["204:1904298318"]="행운이 있는 사람이 그  ⁇ 블 바자르에 오는데$b$b나라는 '부러스카인 오트 코인'입니다. 가장 좋은 행운을 가진 아이로 이름을 붙여졌습니다."
rows["204:2003654867"]="내가 해냈어!$b$b방의 장식품에서 산파일을 사용하여, 저는 안경을 만들었습니다. 그것들로 저는... 놀라운 것들을 볼 수 있습니다!$b$b행운이 있으면 내 다음 입장은 신생 부자가 될 거야!"
rows["204:2111857346"]="이 중 $1998w 우리가 필요로 하는 구리 바는, 우리는 $2018w텐 바 컬렉션의 번호는 $2005w 이 중 $2006w 필요했습니다. 그리고, $2008w 이 중 $2009w 미트릴 바르는 그 원인에 의해 녹았습니다."
rows["204:247673599"]="스나르랑 얘기해봐, 그는 그냥 오그리마 사루의 지휘하에 공부하고, 사루의 수석 근처에서 그를 찾아라."
rows["204:282488528"]="이제 그들을 죽음에서 일으켜 스컬지의 주인으로 만드는 광경을 지켜보아라. 이 세계를 혼돈과 파괴로 덮을 자들이다. 그들이 직접, 아제로스의 몰락을 가져오리라. 그리고 가장 먼저 네놈부터 처리하리라."
rows["204:317083978"]="어쩌면, 너희는 자유의지를 지닌 불완전한 존재이기 때문에... 우주의 절대적인 질서에 맞설 수 있는지도 모르겠다. 티탄의 완벽한 창조물이 스러진 곳에서 너희는 번성하는구나."
rows["204:404597030"]="이 분야에서 충분히 발전해 왔어, 제 교수 능력도 넘어서요. 오그리마 당신을 훈련시킬 수 있는 사람이 될 수도 있습니다."
rows["204:411591860"]="이 물체 에 건조 된 여러 유혈 점 들 이 나타났는데, 아마도 트롤 들 이 이 유물을 얻기 위해 노력 한 결과일 것 이다. 하지만 물체 는 매우 단순 이며, 그 노력 이 가치가 없었을 수도 있다."
rows["204:532893989"]="다라란은 오케이션 하우스도 없고,$B$B그들은 달라란의 얼라이언스 및 호드 방에서 발견 될 수 있습니다: 은 엔클라브 및 선리어버의 성당."
rows["204:554820573"]="카른은 우리가 도금과 철의 영들을 듣고 그들이 우리를 인도할 것이라고 말합니다. 난 귀에서 울음밖에 듣지 않습니다. 여기, 해마를 가져와 함께 영들을 듣고자 노력하자."
rows["204:564133502"]="포털을 들여다보면 지하 동굴의 내부 부분을 볼 수 있습니다. 물이 떨어지는 소리가 땅이 움직이는 소리로 인해 억제됩니다. 이 포털은 어떤 이유 때문에 열렸어야 합니다. 하지만 왜요?"
rows["204:598235532"]="혈연 버섯은 다른 버섯 종류 보다 더 흔하며 대부분 혈연 버섯 주변 숲에서 발견 될 수 있습니다."
rows["204:671457185"]="이 전쟁 중 스컬지 이 낙스라마스, 만약 당신이 불성스러운 전사장과  ⁇ 돌판 잔해를 발견하면, 내게 돌려주면 영웅들이 착용하는 이 갑옷의 조각을 만들게 될 것이다."
rows["204:680050135"]="혹시 거래를 하려고 하십니까? 그렇다면 더 멀리 갈 필요 없습니다. 저는 정직한 장사꾼입니다. 제가 가진 물건 들은 매우 구하기 힘들었습니다. 뭐, 그렇지만 어디서 났는지는 상관없지 않겠습니까? 당신에게 필요한 건 뭐든지 있으니 둘러보십시오."
rows["204:706727748"]="호드의 봉사 에서 죽게 되는 것 은 큰 영광 이 되어야 하지만 당신 은 그 를 더러운 주머니 를 채울 기회 로 보고 있습니다!"
rows["204:761689110"]="신생생이니까 내가 아는 모든 걸 알려줄게 더 잘 되면"
rows["204:787455308"]="당신의 의식이 확장되고 있습니다. 당신이 찾고 있는 사람에게 집중하십시오. 소년 왕자, 젊은 사자. 그는 여기 있습니다. 그는 아니? 시간과 공간을 여행... 영혼의 눈을 열어. 당신은 그를 볼 수 있습니까?"
rows["204:986100725"]="재밌는 건, 방금 소식을 받았어요. 얼라이언스 모은 $2060w 이 중 $2061w 가죽 $2063w 이 중 $2064w 중형 가죽 및 $2069w 이 중 $2071w 두꺼운 가죽 피부."
rows["205:1025500066"]="듀로타에서 좋은 광업이 많다고 들었어요. 사실, 우리는 여기 라저 힐에서 광업 훈련자를 가지고 있습니다."
rows["205:1258783887"]="수천 년 전, 진주파인 부족은 모든 판다리아의 왕위에 서있었고, 이 마을은 우리 민족의 남은 전부였죠."
rows["205:129212023"]="어떤 사람들은 군대 성공에 힘과 용기가 가장 필요하다고 말합니다. 그리고 그것은 사실입니다! 하지만 군대도 자신을 잘 유지하기 위해 물품을 필요로 합니다. 그리고 그들이 필요로 하는 것을 보장하는 것이 제 임무입니다."
rows["205:1342584955"]="내가 당신이 알고 싶은 것을 보여줄 수 있지만 인내심을 가져야 합니다. 철을 작업하고, 당신의 해마 아래의 모양을 느낄 수 있습니다."
rows["205:140470212"]="만약 당신이 축복 카드들을 다듬어내면 더 큰 암흑달의 십자군 카드를 받게 될 것입니다. 이것은 당신의 싸움을 계속하면서 마법과 공격으로 인한 피해를 증가시킬 것입니다."
rows["205:1503378099"]="허브스, 드래그에서  ⁇ 디와 얘기해봐, 어소란 시장 뒤에 나무 계단 몇개 있어,"
rows["205:1600059857"]="어디 보자... 마법의 지배자께 반항하는 자들인가? 이해력도, 통찰력도 없는 것들... 어떻게 해야 알겠느냐? 말리고스 님은 세상을 근본적으로 구하고 계신단 말이다! 하! 말해 봐야 입만 아프지!"
rows["205:1688099396"]="|TInterface\\Icons\\inv_weapon_shortblade_37.blp:32|t 강력한 공격$b$b|TInterface\\Icons\\inv_weapon_shortblade_92.blp:32|t 더 강한 공격$b$b|TInterface\\Icons\\ability_rogue_shadowstrikes.blp:32|t 가장 강력한 공격"
rows["205:1792048045"]="그들은 내게 부끄러움을 없애고 한 가지만 해야 한다고 말해주고$b$b하지만 내가 할 수 없어 파로스의 힘을 내버려 둘 수는 없어"
rows["205:1838758607"]="남동 달라란에 있는 명예로운 상품에 있는 레드 (Red) 는 대부분의 일반 무역 물품을 제공할 수 있다.$B$B더 전문적인 물건이 필요하다면 매거스 상거래소를 찾아보세요."
rows["205:1996184661"]="제가 죽기 전, 저는 도서관관장이었는데, 전쟁과 전염병과 아무 관련이 없었어요. 저는 이런 사람이 되려고 요청한 적이 없었습니다. 한편으로는, 이제 제 마음이 다시 제 것이 되었으니, 저는 싸움을 하지 않고 항복할 수 없습니다."
rows["205:2061618547"]="저한테 공부할 능력이 없어서 마틴 펠벤 박사랑 얘기해봐 포세이큰 필요한 훈련을 줄 수 있는 사람이죠."
rows["205:261027246"]="피오른의 안빌은 현재  ⁇ 니펠렘에서 피오른과 그의 군대에 대한 그들의 승리의 상징으로 눈에 띄고 있습니다.$b$b당신은 당신의 행동이 세상에 지속적인 영향을 끼쳤다는 것을 알고 미소를 지는 것을 멈출 수 없습니다."
rows["205:45966595"]="<고르무난의 웃음, 깊고 긴, 땅이 흔들리고 먼 곳에 산사lides를 일으킨다.>$B$B아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아, 아! 아! 아! 아! 아! 아! 아! 아! 아! 아! 아! 아! 아! 아! 아! 아! 아! 아! 아! 아! 아! 아! 아! 아! 아! 아! 아! 아! 아! 아! 아! 아! 아! 아"
rows["205:463952806"]=" ⁇ 거 목표물에 스킬드 브레이커를 사용하세요.$B|TInterface\\Icons\\Ability_Warrior_ShieldBreak.blp:32|t$B그럼 방어력이 없는 동안 쉴드 브레이커를 사용하세요$B|TInterface\\Icons\\Ability_Warrior_ShieldBreak.blp:32|t"
rows["205:468244757"]="어떻게 다른 방법으로 이런 일이 일어날 수 있었을까요?$B$B'한은 널 향해 손자 흔들고 있다.'$B$B그래서 도와줘, 내가 여기서 빠져나갈 때, 내 남은 하루는 배신자를 찾아낼 거야"
rows["205:591305514"]="그가 쌓은 보물만 보세요!$b$b저는 그의 방법들이 항상 편리하지는 않지만 그 결과를 부정할 수는 없습니다.$b$b불쾌한 생각에는 집중하지 않는 게 좋을 거야"
rows["205:600865316"]="다행히 포털의 반대편에 있는 동맹국들은 이제 오포세트가 비활성화되어 있어 물품을 보낼 수 있습니다.$b$b불행히도 우리는 여전히 함정을 비활성화하지 못해"
rows["205:614351759"]="다 됐어, 그만해! 네 말만 들었어, 형아! 우리 아빠를 데려오야 했잖아! 일어나 싸워봐!"
rows["205:662512773"]="만약 당신이 원망하는 것은 전사의 길이라면, 당신은 크랭 스톤호프를 찾아야합니다. 당신은 그를 마을의 남동쪽 모퉁이에 그의 훈련 서클에서 찾을 것입니다."
rows["205:685105941"]=" ⁇ , 내 다리를 잡아먹어 호드 우린 이미 필요한 모든 전쟁 재료를 가지고 있어 얼라이언스 그들의 모든 것을 얻으려면 전쟁을 시작해야 합니다."
rows["205:727426088"]="다음 전투기는  ⁇ 프라크의 가장 깊은 무덤에서 발견되었습니다. 저주받은 피로 젖어, 수없이 많은 번 죽음에서 부활했습니다. 그는 이제 분노와 폭력만을 알고 있습니다!"
rows["205:744649150"]="그림자는 우리를 잘 숨길 수 있을 거야\010$b이 그림자 속의 숨겨져 있고, 그 마법은 당신에게 퍼져나갈 수 있습니다.\010$b그것은 우리를 보이지 않게 만들지 않을 것입니다. 하지만 우리가 적으로부터 거리를 유지하면 우리는 숨겨져있을 것입니다."
rows["205:922177812"]="네더스톰 지역에 있는 비스턴 핀치위슬을 방문할 수 있도록 52스팀위들 전투 회로의 공식 아레나 판매자로서 그는 아레나 포인트를 충분히 가진 사람들에게 모든 종류의 놀라운 물건을 판매합니다."
rows["206:110059629"]="우리는 엘프들과 그들의 겁쟁이를 제거해야 합니다 얼라이언스 존엄성의 계곡의 용맹의 홀에 가서 브라크글 죽음의 소수에게 호드."
rows["206:1169580793"]="놀라운 아뮬렛을 구경해보게! 정말 희귀한 작품일세! 오랜 세월에 걸쳐 검증을 받은 그립타 가문의 진정한 솜씨 앞에서는 최신 세공 기술도 어린애 장난에 불과하지! 마법 부적을 저렴한 가격에 구입해서 능력을 향상시킬 절호의 기회라고!"
rows["206:1418466223"]="그 크고 무고한 눈들이 당신을 속이지 않도록 해 테리라는 전문가입니다. 매일 새로운 것을 배우고 있습니다. 왜 내가 여기 있다고 생각하십니까? 기술공 내가 엔지니어처럼 보이시나요?"
rows["206:1427756204"]="와일드햄어 용병들과 함께 포트 트라이엄프를 지키기 위해 고용되었을 때, 저는 우리가 호드과 싸워 줄 줄 알았어요.$B$B하지만 우리는 모든 측면에서 공격당하고 있습니다! 폭발하는 괴물, 파고 벌레, 전기화 된 도마뱀... "
rows["206:1442938476"]="물론 그래, 자기 자신으로부터 큰 파란색을 구하기 위해 온거야. 영세계에 모든 시간을 보내고, 마법의 유물들에 집착하고 있어.$B$B내가 누군가를 만났어"
rows["206:1486288708"]="오랜만에 저지른 큰 실수를 끝내주셔서 감사합니다. 우리 민족을 이 어두운 곳으로 데려온 것에 대해 감사해요. 혼자서는 할 수 없었어요."
rows["206:1509457766"]="|TInterface\\Icons\\trade_archaeology_delicatemusicbox.blp:20|t제국 비지르 조로크는 |cFFFF0000|Hspell:123791|h[황후의 노래]|h|r, 모든 플레이어에게 전투를 할 때까지 손상을 입히고!"
rows["206:1679951902"]="그러니 두려움이 등뼈를 타고 올라와 머리끝이 쭈뼛하고 바지에 오줌이라도 지릴 것 같은 기분이 들어도, 참아내라. 두려움을 분노로 승화시켜라. 그 공포만이 제군들이 목숨을 부지하게 해 줄 것이다."
rows["206:1790127671"]="좋은 일이야, 배신자한테 복수하는 걸 보고 기쁘네요. 미란이 동쪽으로 가는 길을 따라가서"
rows["206:1879387549"]="난 와일드햄어 샤먼들이 왜성 구역을 방문한다고 들었어$B$B영웅의 계곡에 돌아다니던 파르세이르도 그들을 만나러 갔습니다."
rows["206:1981602665"]="랜드 로바트는 펠바츠를 잘 벗겨내는데 잘합니다. 브릴 남동쪽의 길에서 캠프에서 찾을 수 있습니다. 남동쪽으로 도심 밖으로 나가서 동쪽으로 갈 수 있습니다."
rows["206:2025062612"]="밤의 장막 아래에서도 대지모신께서 훤한 대낮과 같이 우리를 지켜 주시기를. 이 불이 우리의 몸과 영혼을 모두 비추며, 항상 우리를 이끌어 주시는 영광스러운 선조를 기억하게 해 주기를..."
rows["206:2101790225"]="아타스의 죽음 기사 들 은 리치 왕에 반발 할 때 많은 사람 들 이 강제로 빼앗긴 떠 있는 성 성 에서 훈련 을 받았읍니다. 그 성 성 의 이름 은 무엇 이었습니까?"
rows["206:213299479"]="아포니, 나는 그대에게 인내하라고 조언하지. 그러나 사실은 나도 그대만큼 여기 머무르는 것이 싫소. 이 어두운 시대에, 어쩌면 내가 한가하게 놀리는 이 손이 전세를 뒤집을 수도 있다고 생각하면 마음이 편치 않소."
rows["206:304610524"]="블랙 드래곤 플라이트의 영향력은 불타는 스텝스 국경을 넘어 스톰윈드 왕국 자체로 확장 된 것 처럼 보일 것 이다!"
rows["206:399296644"]="갈반가르 대장 (Drek'Thar) 의 신뢰받는 도움으로 전투장의 남쪽 부분에서 있는 아이스블러드 가리소에서 호드군을 이끌고 있다.$B$B갈반가르 대장은 아직 전투에 참여하지 않았습니다."
rows["206:530407322"]="마법사 군주 우롬이 다음 목표이다. 우롬은 변환의 고리에 있는 떠다니는 단 어딘가에 숨어 있는데, 아마 마력의 눈 꼭대기에 가까이 있을 것이로다. 조심하라, 우롬은 강력한 요술사인데다 혼자 있지는 않으리라."
rows["206:537905325"]="리는 크리스탈 레이크에서 이상한 걸 잡았어요. 몇 달 전에 발견한 이 이상한 마스크에 대해 이야기 한 적이 있어요."
rows["206:61736916"]="나는 개인적으로 토르텔드린 왕자가 하는 일에 관여하지 않았소. 예외적으로 하이 엘프를 자신의 영토에 들인 것은 토르텔드린 왕자였소. 유감스럽게도 나는 토르텔드린 왕자에게 의문을 제기할 입장이 못 되오. 조금이나마 왕자를 두둔하자면, 윈탈루스를 즉시 불태워 죽이지는 않았다는 거지."
rows["206:656591609"]="그 ⁇ 블 바자르에서 이상한 생물을 봤는데, 마치 진주에게 귀여워진 것처럼 보이지만 악당해서 \"Mrggmrrgmgmgl\" 같은 말을 했다$b$b한 번은 해안에서  ⁇ 어 올렸지"
rows["206:709071690"]="대사는 자신의 똥의 저수기에 죽은 채로 누워있어요.$b$b그의 임대 옷들을 통해 엄청난 깊은 치아 흔적들을 알아볼 수 있습니다.$b$b더 이상, 상처는 가열되어 있고, 심지어는 얼룩이 되어 있는 것 같습니다."
rows["206:841399254"]="사물들은 모두 팔릴 거야, 내 친구$B$B만약 당신의 생명을 소중히 여기고 있다면, 재급 없이 Manaforge Ultris에 접근하지 말라."
rows["206:957365137"]="빨리 말해주세요. 저는 방랑한 이야기로 시간을 낭비할 수 없습니다. 포세이큰는 계산할 수 있는 힘이 되었습니다. 하지만 주어진 날에 할 일이 많이 남아 있습니다. 이 도시는 스스로 운영되지 않습니다.$b$b- 뭐하고 싶은데?"
rows["206:979831123"]="우린 이 악마들과 함께 싸울 거야 나이트헤븐의 수비자들은 우리 가운데 있어 그들이 요청하면 죽을 때까지 싸우겠지 이제 빨리 이 변칙들을 악몽으로 돌려보내야 돼"
rows["206:994858203"]="왕자는 애쉬브링거의 이야기를 거부했나요? 그것은 그의 이야기 중 가장 좋아하는 이야기입니다. 그의 가장 좋아하는 이야기는 애쉬브링거의 후속입니다. 물론, 아무도 그 이야기를 그에게서 꺼낼 수 없었습니다."
rows["207:1009545803"]="드래곤은 돼지나 소처럼 단순한 짐승이 아니라 자연의 힘입니다.$B$B그들을 당신의 뜻대로 굴복시키는 것은 세상을 이용하는 것입니다.$B$B그들의 통치권을 잡는 것은 운명을 손에 쥐는 것입니다."
rows["207:1169154052"]="10천년 전 마지막 판다렌 황제가 제 조언을 구하러 왔어요. 그는 또한 갈등으로 가득 차 있었습니다."
rows["207:1274325136"]="베나는 마치 귀신처럼 일하고 있습니다. 밤낮으로 나는 그녀를 이 술에 걸려서 몸을 숙이고, 종종 잠을 잘거나 음식을 먹지 않고 보곤 했습니다."
rows["207:1312581497"]="알도르라는 이름의 그 사제들은 나루가 돌아왔으며 재건 사업이 곧 시작된다는 소식을 듣고 금세 기운을 회복했습니다. 부서진 사원은 현재 부상당한 난민들을 위한 진료소로 사용되고 있습니다."
rows["207:1585419527"]="토야는 제 프로젝트를 위해 자드 재료를 모으고 있습니다. 그가 끝나면, 황제의 오멘에 가져오세요."
rows["207:164343070"]="우리 전사 중 한 명이 탈출해서 많은 감옥을 파괴했습니다. 우리는 적어도 잠시 동안 자유로워졌습니다.$b$b어떤 사람들은 표면에 향해 수영을 했습니다. 어떤 사람들은 이 동굴을 보고 그 쪽으로 수영을 했습니다.$b$b내가 유일하게 살아왔어..."
rows["207:165627620"]="믿기지 않아, 그가 야생지방에 있을 거라고 확신했네$b$b파오쿠안 홀로, 곧 합류해 훈련이 계속될 수 있어"
rows["207:1878239870"]="황새에게 물고기를 줘 하루 동안 먹여라 황새에게 낚시를 가르치고 평생 먹여라 우탄 스틸워터도 낚시를 가르쳐 줄 수 있어"
rows["207:2038397498"]=" ⁇ 발이 못생긴 여자아이가니까 리치 왕 그가 널 만들었을 때 그의 과제를 충족시키려고 했나?"
rows["207:2070385563"]="이 참담한 곳을 지나 투영의 전당으로 들어갈 방법을 모색하겠어요. 전당 안에 감춰진, 강력한 마법이 느껴지는군요. 이 마법이 스컬지를 파괴하는 열쇠가 될 수 있어요!"
rows["207:214588507"]="다르나서스 재능있는 사람들로 둘러싸여 있는 이곳은 너무 흥분되네요! 저는 제 가족을 자랑스럽게 만들지 모른다고 생각합니다."
rows["207:240686635"]="난 타우렌 족장들을 지원하는 노동자들을 지휘하고 있어\010짐을 싣고 운전하고 차들을 풀고, 무대를 만들고, 내려놓고, 무대 무대를 설치하고, 그런 것들이죠."
rows["207:249254131"]="육류, 피부, 뼈... 좋은 사냥꾼은 아무것도 낭비하지 않는다. 모든 가죽 조각을 구출 할 수 있습니다. 아마도 동맹의 장갑을 강화하기 위해. 따라서, 우리 각자는 혼자 힘, 하지만 함께 우리는 이길 수 없습니다."
rows["207:279896869"]="우린 부패를 조사하고 있었는데 모든 게 잘못됐어요"
rows["207:322187484"]="네 마법은 내가 봤어 네가 사루크가 아닌 다른 사람이라는 걸 알아$b$b마법이 너를 약하게 해줘 넌 용감하지 않아$b$b고카르는 네 발에 뱉는다"
rows["207:373843924"]="스파키, 우린 다 해냈어 모든 것이 준비됐어 호드 이제 야후스, 그리고 그들이 그들의 연기를 함께하면 Ahn'Qiraj에서 경주로!"
rows["207:467960979"]="죽은 자에게 명예란 아무 의미도 없네. 전사는 명예를 위해 전장에서 죽어갈 수도 있지만, 족장은 그보다 더 많은 것을 책임져야 하는 법이야. 현자 아이레의 계획에 따르기로 하고 마을을 계속 방어하세."
rows["207:61385867"]="이 작전을 지휘하고 있어요$B$B우리 교통이 폭발하고 적들이 우리보다 높고, 우리는 프로이고, 이 일을 한결같이 해내고 있습니다."
rows["208:1023941977"]="카이데가 너를 비켜고 있다$B$B조용히 해, 아니면 오크와 얼라이언스들을 우리한테 몰아넣어 주겠네, 멍청한 놈!$B$B네, 머리를 숙여서, 우리가 얘기한 후에, 당신은 떠나서 여기서 나를 발견한 것을 잊을 것입니다."
rows["208:121921959"]="오페라톤의 끝: 노메레건은 대부분의 사람들에게 휴식을 취할 기회를 제공했습니다. 하지만, 저와 제 부하들은 부상자와 생존자들을 돌보고 있습니다."
rows["208:1255294530"]="비시와 볼리우프 사이에 오크를 깎거나 꺾는 즐거움을 누리지 못한 무기가 많아요"
rows["208:1460973957"]="이 도시를 방문하는 타우렌 부부가 있다. 그들은 멀고어에서 왔다고 전해졌습니다. 포세이큰 \"상태\"에 대해 더 자세히 알아보기 위해 또는 그 의미의 무언가가 있습니다.$B$B약당에서 약사 근처에 찾아봐"
rows["208:1549870675"]="여러 세대를 걸쳐 내 백성들을 안개로 보호했지만, 제가 보는 모든 챔피언들과 함께 제 방식의 잘못을 점점 더 깨닫게 되었습니다."
rows["208:1562019235"]="이 물고기를 먹은 크레인은 폭력적인 죽음을 맞았던 것 같습니다.$B$B몸 전체에 물기와 손톱 흔적이 있고 내장 대부분이 소모되었습니다.$B$B이건  ⁇ 한 음식이 아닐까?"
rows["208:1577581636"]=" ⁇ 과 그의 불안한 악몽에 지쳤던 라스타칸 왕은 예언자로부터 해방을 얻기 위해  ⁇ 과 그의 추종자들이 새로운 땅을 찾아갈 수 있도록 가장 큰 배들을 사용하도록 허락하였다."
rows["208:1635539230"]="우슈올라이, 폭풍마녀$B$B그의 힘은 하늘, 비가, 그리고 파괴된 땅의 힘입니다.  $B$B우슈올리는 이제 멀리 떨어져 살고 있습니다. 언젠가는, 그는 돌아올 수 있습니다..."
rows["208:1713297707"]="우리 군대는 대부분 마을과 농민들로 구성되어 있습니다. 좋은 사람들이지만, 그들의 교육의 편견과 미신들을 완전히 없애지 못하고 있습니다. 그들은 우리의 더 이상적인 동맹국들과 함께 싸울 준비가 되어 있지 않습니다."
rows["208:1824501670"]="인상적 인. 주인 은 당신 과 당신 의 백성 이 곤란 을 겪게 될 것 이라고 말 했 다. 그 어떤 상황 이 있더라도, 당신 의 끝 이 가까우니. 곧 낙스라마스의 합동 힘 이 이 곳 에 내려와서 당신 의 소소한 존재 를 파괴 할 것 이다."
rows["208:183233581"]="여기 고산지대의 나무들은 강대 나무로 만들어져 있고, 일부는 돌로 만들어져 있습니다.$B$B우리는 다이아몬드 블레이드 셔더를 가지고 있습니다. 하지만 얼라이언스는 계속 그들을 때려."
rows["208:1920957886"]="여행자님, 환영합니다. 이 곳에 집을 짓으세요. 위층에는 은행보호관과 도시 포털이 있습니다. 모든 종류의 무역업자들이 건물 주변에 매장을 세우고 있습니다."
rows["208:2066499904"]="몇 년 전, 그리모테마는 내 마을을 침공했고, 고통, 분노, 상실감은 여전히 내 마음속에 있습니다.$B$B그리고 이제 저는 야만적인 공격으로 마을을 잃은 다른 사람들에게 위로와 도움을 주고 있습니다."
rows["208:2103826251"]="재조조를 하고 싶었소?\010하지만 스톰윈드의 성당 구역에 있는 \"삼풍\"의 이성들은 도움이 될 것입니다.\010도시의 경비원이라면 누구나 안내를 줄 수 있습니다."
rows["208:2126147930"]="네가 내가 본 최고의 쓰레기처럼 행동해줘요 괜찮아요, 하지만 매일 이런 걸 보고 있어요."
rows["208:348641250"]="예, 전통과 그 모든 교훈에 관한 노래요. 흥미진진한 소리죠.$b$b하지만 아직 연구중이야 차드릭은 최근 쉽게 주의를 기울이고 있어"
rows["208:404891451"]="그래, 이곳 정령들은 충분히 구원을 받았어요. 하지만, 암호가 다른 이들에게 알려지면... 불의 정령들이 동요하고 있습니다... 이것을 막지 못하면 필멸의 존재들이 온 세계는 멸망할 것입니다."
rows["208:421934812"]="이럴 수 없는 싸움이 있지만, 은날개 헐드의 엘프들이 평화롭게 우리에게 말을 하지 않는다면, 그들은 우리에게 어떤 대안을 남길 수 있을까요?"
rows["208:438018060"]="샤파르의 유성들이 입구 위에 놓은 것은 신경쓰지 않는다 마나- 무덤들, 그 구역들이 제거될 때까지 일해야 해"
rows["208:470637614"]="친구, 최근 여행에서 크라사랑으로 왔나요?$B$B어류는 가장 행운의 작물만큼 풍요롭다.$B$B아버지가 말했듯이, 어업자는 잡을 수 있습니다!"
rows["208:605499384"]="침입자들아, 너희 승리는 덧없는 것이다. 나는 사령관인 바로스 클라우드스트라이더다. 내 비룡들이 하늘을 지키고, 이 마력의 통로를 보호하지. 분명히 말하건대, 마력의 눈을 너희에게 내주지는 않을 것이다."
rows["208:6219584"]="우리의 에이전트들이 수많은 실패를 거쳐 스컬지 분석을 위해, 전선으로 나 직접 왔고 노력들을 감독해 왔습니다. 그들이 말하는 것처럼, 만약 당신이 일을 제대로 하고 싶다면..."
rows["208:691600097"]="물은 곧... 생명... 여기 아웃랜드에서 물을 구하기란 결코 쉽지 않지. 오직 우리만이 물을 통제할 수 있다. 마침내 우리 귀족들이 이 세계에서 본래 자리를 되찾을 시간이 왔도다!"
rows["209:1028847084"]="트램을 들어봤어요. 그 물건은 얼마나 큰 차인지! 당신은 그 트램을 뒤쪽으로 왜니언 구역에서 찾을 것입니다. 오, 그리고 트램이 움직이고 있는 동안 당신의 팔과 다리를 트램 안에 보관하고 있는지 확인하십시오."
rows["209:104323150"]="그대들이 쓰러뜨려야만 했던 엔트로피우스는 한때는 고귀한 나루, 므우루였다네. 생전에 므우루는 막대한 빛과 희망을 뿜는 존재였지. 한동안, 눈먼 이들이 그 힘을 훔치려고 했다네..."
rows["209:1077057634"]="스피릿 라이즈의 서쪽 끝에서 젤펠린의 기둥 근처에 크렌들 빅포켓을 찾을 수 있습니다. 오그리마 견딜 수 있다면"
rows["209:1344558445"]="나가$B$B<비레톤은 혐오로 땅에 뱉는다.>$B$B오크가 지팡이를 쳐서 일을 할 수 있다고 생각한다는 건 어리석은 짓이야"
rows["209:1453843608"]="지구 어머니 앞에서 자연과 하나가 되는 법을 배우려면 자랑스러운 일이야 사냥꾼의 길을 배우려면"
rows["209:1561274353"]=" ⁇ 랄 장군 스스로 이 자리에 오라고 부탁했는데, 난 순종하는 것이 영광이었는데, 난 그보다 더 좋은 포스팅을 요청할 수 없었어요."
rows["209:1694342853"]="<블랜치는 폭풍의 혼란에 대해 소리치고 있습니다.>$B$B밥 ⁇ 과 컵이 준비됐어 이제 자연이 마법을 할 수 있을 거야$B$B불꽃놀이를 준비해?"
rows["209:1708074996"]="이 신성한 물 은 훼손 되었지만 희망 은 사라지지 않았습니다. 우리 의 고대 의식 은 이 큰 부패 와도 불구하고 지속 되고 깨끗 해집니다. 그리고 물 이 회복되면서, 그것 을 오염 시키 는 사람 들 의 힘 은 쇠퇴 합니다."
rows["209:1715311511"]="절대 안 됩니다. 우리 자신을 위험에 빠뜨릴 수는 없습니다. 주인님께서 사라지시면 흐름을 유지시킬 수 있는 것은 우리밖에 없습니다. 이제 다른 자들의 도움을 받을 때가 됐습니다. 아제로스의 영웅들과 모험가들 말입니다..."
rows["209:1737243262"]="너의 여정은 이제 막 시작이다, 젊은 왕자여. 병사들을 모아 극한의 땅, 노스렌드로 나를 찾아와라. 그곳에서 모든 일이 결판날 것이다. 네 진정한 운명도 그곳에서 시작되지."
rows["209:1768367925"]="넌 꽤나 좋은 친구였어 이제 이웃이 됐으니 내가 너한테 닭을 줄게"
rows["209:1845768943"]="우리가 지금 얘기하는 동안 최종 준비를 하고 있습니다. 나머지는 루안 웰드에서 얼마나 빨리 힘을 정리할 수 있는지에 달려 있습니다.$B$B빨리 처리할 수 있다고 생각하십니까?"
rows["209:2010567915"]="네가 여기 온 건 술조술에 대한 가르침을 받겠나? 내가 네게 이득이 없는 특권을 줄 줄 줄 생각하면 잘못됐어. 가서 더 뛰어난 기술을 가지기 전까지는 내게 돌아오지 마."
rows["209:2071275002"]="어린 시절, 저는 성직자 로 훈련 을 많이 받았습니다.$B$B오늘날 성별은 중요하지 않습니다. 모든 것은 용기와 확신이 중요합니다."
rows["209:226941060"]="카엘타스를 물리치는 일은 당신의 집중력을 받을 가치가 있습니다. $b$b그 외에도 군대를 조직할 수 있다면, 선웰에서 해결해야 할 많은 잘못이 있습니다.$b$b어쩌면 우리는 다시 거기서 만날 수 있을지도 모릅니다."
rows["209:298532675"]="이 호드 배는 괴물들에 의해 제작되었다. 원래 Thrall와 Aggra를 Maelstrom으로 데려오려고 의도되었으나 얼라이언스에 의해 깜짝 공격으로 파괴되었습니다."
rows["209:300853731"]="아우리페러스 귀부인, 우리는 지원부대요. 여군주께서 곧 병력을 더 보내실 거요. 실버문의 지도자들을 설득하여 모든 병력을 소집해 우리에게 지휘권을 넘기도록 해주시오."
rows["209:317148674"]="첫 번째 구호가 필요하다면, 니사 파이어스톤에게 물어봐라. 아이언포지 의사야"
rows["209:387774585"]="잘했어, 종아. 내가 오랫동안 불의 주인 감옥에서 갇혀있었으니 다시 한 번 자유로웠어 바깥 세계를 누릴 수 있어"
rows["209:476219034"]="세계 샤만 - 판드랄 스태겔름의 손으로 찢어졌어?$B$B더 큰 힘들이 여기 작용하고 있습니다. 라그나로스는 내가 상상했던 것보다 더 멀리 그의 힘을 이 영역으로 밀어 넣었습니다.$B$B불의 주인이 막아야 돼!"
rows["209:480951425"]="베스프리스투스 (Vesprystus) 를 찾고 있습니다. 그는 테일드라실의 기지에서 오는 히포그리프들을 감시합니다. 당신은 그를 서쪽 다르나서스의 포털을 통해 찾을 것입니다."
rows["209:596071588"]=" ⁇ 스플라이프즈가 마법사의 직업을 배우려면  ⁇ 스플라이프즈 아케네리에서 그리폰 마스터 바로 옆에 있는  ⁇ 스플라이프즈 아케네리에서 찾아볼 수 있을 것 같아요"
rows["209:63653323"]="다들 우리 걸 빼앗기만 했지. 이제 우리가 되찾을 차례다. 앞을 막는 놈은 누구든... 자기 피에 빠져 죽게 될 거다! 아마니 제국이 돌아왔다... 복수를 위해서. 그리고 시작은... 너다!"
rows["209:653507907"]="우리는 왜소들이 지구와 연결돼 있습니다. 우리는 그 고통을 느낄 수 있습니다. 그리고 지금 지구는 울고 있습니다. 이 지진은 자연스럽고, 그렇지 않습니다."
rows["209:707156026"]="오늘 돈을 지불해 줄 수 있었으면 좋겠어요 하지만 최근엔 사업이 너무 나쁘지 않아$b$b금은 가족에게 저녁을 먹으러 가는데"
rows["209:711514536"]="야생동물들의 유적지, 난 야생동물들에 대한 잔다라리 기술에 감탄하지만 더 많은 인상을 받은 것은 이 불쾌한 냄새를 견딜 수 있는 능력이다.$b$b바람을 피우면 절대 무감각하게 될 거야"
rows["209:711830343"]="나의 백성은 에너지와 마력에 중독됐지. 태양샘이 파괴되자 지독한 금단 현상이 발생했다. 미래에 온 것을... 환영하노라. 중단하기에는 이미 늦었다. 이제 아무도 날 막지 못해! 셀라마 아샬라노레!"
rows["209:72560656"]="안녕하세요, 낯선 사람. 저는 실크마스터 타이입니다. 고대 제국 실크 농장에 오신 것을 환영합니다.$b$b이 농장은 판다리아의 초기 왕조 중 일부로 거슬러 올라갑니다. 그리고 각각의 세대들은 실크 품질에 있어서 마지막을 뛰어넘습니다."
